Here is the **updated plan** with the auth/guard flow and frontend architecture:

---

## Updated: Auth/Guard Verification Chain

### Complete Flow

```
┌─────────────────────────────────────────────────────────────────┐
│                        USER LOGIN                                │
│  Email/Password → Auth Service → Validate → Generate JWT         │
│  JWT Payload: { userId, email, establishmentId?, tenantId? }    │
└──────────────────────────┬──────────────────────────────────────┘
                           │
                           ▼
┌─────────────────────────────────────────────────────────────────┐
│                    MIDDLEWARE LAYER (every request)              │
│                                                                  │
│  1. Extract JWT from Authorization header                       │
│  2. Validate JWT signature + expiry                             │
│  3. Resolve User from DB (isActive check)                       │
│  4. Resolve establishmentId from JWT (if present)               │
│  5. Check Tenant → Subscription → Plan exists & is ACTIVE       │
│     ❌ If subscription expired/suspended → 403 Forbidden        │
│     ✅ If subscription OK → attach context to request           │
│  6. ROOT user bypass: can access ALL tenants, no sub check     │
└──────────────────────────┬──────────────────────────────────────┘
                           │
                           ▼
┌─────────────────────────────────────────────────────────────────┐
│                     GUARD LAYER (per route)                      │
│                                                                  │
│  @UseGuards(JwtAuthGuard, RolesGuard, PermissionsGuard)         │
│  @Permissions('students:list')                                   │
│                                                                  │
│  1. Get user's roles (UserRoleAssignment → Role)                │
│  2. Get establishment context from JWT                           │
│  3. Get tenant's subscription → plan → plan modules             │
│  4. Get role's permissions (RolePermission → SaaSPermission)    │
│  5. Check: Does this permission's MODULE exist in plan modules? │
│     ❌ Module not in plan → 403 (Feature not available)         │
│  6. Check: Does role have this specific PERMISSION?             │
│     ❌ Permission not granted → 403 (Access denied)             │
│  7. ROOT user: Always pass (full access)                        │
│  8. Attach permissions to request for downstream use            │
└──────────────────────────┬──────────────────────────────────────┘
                           │
                           ▼
┌─────────────────────────────────────────────────────────────────┐
│                  DATA LAYER (per service)                        │
│                                                                  │
│  - All queries auto-filter by tenantId (middleware)             │
│  - All queries auto-filter by establishmentId (if set)          │
│  - ROOT user: Can override tenant filter via dropdown           │
└─────────────────────────────────────────────────────────────────┘
```

### Backend Implementation

```typescript
// ============ MIDDLEWARE ============
// subscription.middleware.ts
@Injectable()
export class SubscriptionMiddleware implements NestMiddleware {
  async use(req: Request, res: Response, next: NextFunction) {
    const user = req.user;

    // ROOT user bypass
    if (user.roles.some(r => r.code === 'ROOT')) {
      req.context = { ...req.context, isRoot: true };
      return next();
    }

    // Get tenant from user
    const tenant = await this.prisma.tenant.findUnique({
      where: { userId: user.id },
      include: { subscriptions: { where: { status: 'ACTIVE' } } }
    });

    if (!tenant || !tenant.subscriptions.length) {
      throw new ForbiddenException('No active subscription');
    }

    req.context = { ...req.context, tenantId: tenant.id };
    next();
  }
}

// ============ GUARD ============
// permissions.guard.ts
@Injectable()
export class PermissionsGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const requiredPermissions = this.reflector.get<string[]>(
      'permissions', context.getHandler()
    );

    if (!requiredPermissions) return true; // No permissions required

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    const { tenantId, establishmentId } = request.context;

    // ROOT user: full access
    if (request.context.isRoot) return true;

    // Get user's role permissions for this establishment
    const userPermissions = await this.getUserPermissions(
      user.id, establishmentId
    );

    // Get tenant's plan modules
    const planModules = await this.getPlanModules(tenantId);

    // Check each required permission
    return requiredPermissions.every(permission => {
      const [moduleCode, action] = permission.split(':');

      // 1. Is module in plan?
      if (!planModules.includes(moduleCode)) return false;

      // 2. Does role have permission?
      return userPermissions.includes(permission);
    });
  }
}
```

### Frontend: Dynamic Dashboard

```
src/app/(dashboard)/
├── layout.tsx                    # Dynamic sidebar + header
│   ├── EstablishmentSwitcher     # Dropdown (for Root/multi-establishment users)
│   ├── DynamicSidebar            # Menu items based on role + permissions
│   └── NotificationBell          # Real-time notifications
│
├── page.tsx                      # Dashboard home (role-adaptive)
│   └── Shows: widgets based on role
│       - Student: schedule, grades, attendance
│       - Teacher: classes, attendance to mark, exams
│       - Parent: children overview, payments
│       - Admin: full overview, reports
│       - Root: platform stats, tenants
│
├── students/page.tsx             # Student list (if permission: students:list)
├── students/[id]/page.tsx        # Student detail
├── teachers/page.tsx             # Teacher list (if permission: teachers:list)
├── ... etc
```

### Frontend Permission Handling

```typescript
// ============ HOOK ============
// usePermissions.ts
export function usePermissions() {
  const { user, establishment } = useAuth();

  const hasPermission = (permission: string) => {
    if (user.isRoot) return true;
    return user.permissions.includes(permission);
  };

  const hasModule = (moduleCode: string) => {
    if (user.isRoot) return true;
    return user.planModules.includes(moduleCode);
  };

  return { hasPermission, hasModule };
}

// ============ COMPONENT ============
// PermissionGate.tsx
export function PermissionGate({ 
  permission, 
  children, 
  fallback 
}: PermissionGateProps) {
  const { hasPermission } = usePermissions();

  if (!hasPermission(permission)) {
    return fallback || null;
  }

  return <>{children}</>;
}

// ============ USAGE ============
// In any page/component
<PermissionGate permission="students:list">
  <StudentList />
</PermissionGate>

// In sidebar
const menuItems = [
  { label: 'Students', path: '/students', permission: 'students:list' },
  { label: 'Teachers', path: '/teachers', permission: 'teachers:list' },
  { label: 'Finance', path: '/finance', permission: 'finance:view' },
  // ... filtered by hasPermission()
].filter(item => hasPermission(item.permission));
```

---

## Updated: Frontend Architecture (Single Dynamic Dashboard)

### Layout Structure

```
src/app/(dashboard)/
├── layout.tsx
│   ├── Header
│   │   ├── Logo + Breadcrumb
