import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { Observable, tap } from 'rxjs';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class AuditInterceptor implements NestInterceptor {
  private readonly logger = new Logger(AuditInterceptor.name);

  constructor(private prisma: PrismaService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const request = context.switchToHttp().getRequest();
    const { method, url, body, user } = request;
    const startTime = Date.now();

    return next.handle().pipe(
      tap({
        next: async (response) => {
          const duration = Date.now() - startTime;
          this.logger.log(
            `${method} ${url} ${duration}ms - User: ${user?.id || 'anonymous'}`,
          );

          // Log mutation operations
          if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
            try {
              await this.prisma.auditLog.create({
                data: {
                  userId: user?.id,
                  action: this.getMethodAction(method),
                  entity: this.extractEntity(url),
                  entityId: this.extractEntityId(url),
                  newValues: method !== 'DELETE' ? response : undefined,
                  ipAddress: request.ip,
                  userAgent: request.headers['user-agent'],
                },
              });
            } catch (error) {
              this.logger.error('Failed to create audit log', error);
            }
          }
        },
        error: (error) => {
          const duration = Date.now() - startTime;
          this.logger.error(
            `${method} ${url} ${duration}ms - Error: ${error.message}`,
          );
        },
      }),
    );
  }

  private getMethodAction(method: string): string {
    const actionMap: Record<string, string> = {
      POST: 'CREATE',
      PUT: 'UPDATE',
      PATCH: 'UPDATE',
      DELETE: 'DELETE',
    };
    return actionMap[method] || 'READ';
  }

  private extractEntity(url: string): string {
    const parts = url.split('/').filter(Boolean);
    return parts[1] || 'unknown';
  }

  private extractEntityId(url: string): string | undefined {
    const parts = url.split('/').filter(Boolean);
    const uuidRegex =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    for (const part of parts) {
      if (uuidRegex.test(part)) {
        return part;
      }
    }
    return undefined;
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable, map } from 'rxjs';

export interface ApiResponse<T> {
  success: boolean;
  data: T;
  meta?: {
    page?: number;
    limit?: number;
    total?: number;
    totalPages?: number;
  };
}

@Injectable()
export class TransformInterceptor<T>
  implements NestInterceptor<T, ApiResponse<T>>
{
  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<ApiResponse<T>> {
    return next.handle().pipe(
      map((data) => {
        if (data && data.data && data.meta) {
          return {
            success: true,
            data: data.data,
            meta: data.meta,
          };
        }
        return {
          success: true,
          data,
        };
      }),
    );
  }
}

export * from './decorators';
export * from './filters';
export * from './guards';
export * from './interceptors';
export * from './middleware';
export * from './pipes';
export * from './dto';

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { AllExceptionsFilter } from './common/filters';
import { AppValidationPipe } from './common/pipes';
import { Logger } from '@nestjs/common';

async function bootstrap() {
  const logger = new Logger('Bootstrap');
  const app = await NestFactory.create(AppModule);

  // Global prefix
  app.setGlobalPrefix('api');

  // CORS
  app.enableCors({
    origin: process.env.FRONTEND_URL || 'http://localhost:3000',
    credentials: true,
  });

  // Global pipes
  app.useGlobalPipes(AppValidationPipe);

  // Global filters
  app.useGlobalFilters(new AllExceptionsFilter());

  // Trust proxy for rate limiting
  app.getHttpAdapter().getInstance().set('trust proxy', 1);

  const port = process.env.PORT || 3001;
  await app.listen(port);
  logger.log(`Application running on: http://localhost:${port}`);
  logger.log(`API documentation: http://localhost:${port}/api`);
}
