const permissionActions = ['list', 'read', 'create', 'update', 'delete', 'export', 'import'];

// ============================================================
// SAAS PLANS
// ============================================================

const plans = [
  {
    name: 'Free',
    description: 'Free plan for small establishments',
    price: 0,
    currency: 'DZD',
    interval: 'MONTHLY' as const,
    sortOrder: 1,
  },
  {
    name: 'Basic',
    description: 'Basic plan for schools',
    price: 5000,
    currency: 'DZD',
    interval: 'MONTHLY' as const,
    sortOrder: 2,
  },
  {
    name: 'Premium',
    description: 'Premium plan with all features',
    price: 15000,
    currency: 'DZD',
    interval: 'MONTHLY' as const,
    sortOrder: 3,
  },
  {
    name: 'Enterprise',
    description: 'Enterprise plan for large institutions',
    price: 50000,
    currency: 'DZD',
    interval: 'YEARLY' as const,
    sortOrder: 4,
  },
];

// ============================================================
// CLASS LEVELS
// ============================================================

const classLevels = [
  { name: 'Petite Section', code: 'PS', level: 1, category: 'DAYCARE', sortOrder: 1 },
  { name: 'Moyenne Section', code: 'MS', level: 2, category: 'DAYCARE', sortOrder: 2 },
  { name: 'Grande Section', code: 'GS', level: 3, category: 'DAYCARE', sortOrder: 3 },
  { name: 'CP', code: 'CP', level: 4, category: 'SCHOOL', sortOrder: 4 },
  { name: 'CE1', code: 'CE1', level: 5, category: 'SCHOOL', sortOrder: 5 },
  { name: 'CE2', code: 'CE2', level: 6, category: 'SCHOOL', sortOrder: 6 },
  { name: 'CM1', code: 'CM1', level: 7, category: 'SCHOOL', sortOrder: 7 },
  { name: 'CM2', code: 'CM2', level: 8, category: 'SCHOOL', sortOrder: 8 },
  { name: '6ème', code: '6EME', level: 9, category: 'MIDDLE_SCHOOL', sortOrder: 9 },
  { name: '5ème', code: '5EME', level: 10, category: 'MIDDLE_SCHOOL', sortOrder: 10 },
  { name: '4ème', code: '4EME', level: 11, category: 'MIDDLE_SCHOOL', sortOrder: 11 },
  { name: '3ème', code: '3EME', level: 12, category: 'MIDDLE_SCHOOL', sortOrder: 12 },
  { name: 'Seconde', code: 'SEC', level: 13, category: 'HIGH_SCHOOL', sortOrder: 13 },
  { name: 'Première', code: 'PRE', level: 14, category: 'HIGH_SCHOOL', sortOrder: 14 },
  { name: 'Terminale', code: 'TER', level: 15, category: 'HIGH_SCHOOL', sortOrder: 15 },
];

// ============================================================
// ESTABLISHMENT CATEGORIES
// ============================================================

const establishmentCategories = [
  { name: 'Daycare', code: 'DAYCARE', description: 'Nursery & kindergarten', sortOrder: 1 },
  { name: 'School', code: 'SCHOOL', description: 'Primary school (CP-CM2)', sortOrder: 2 },
  { name: 'Middle School', code: 'MIDDLE_SCHOOL', description: 'Middle school (6ème-3ème)', sortOrder: 3 },
  { name: 'High School', code: 'HIGH_SCHOOL', description: 'High school (Seconde-Terminale)', sortOrder: 4 },
  { name: 'University', code: 'UNIVERSITY', description: 'University & higher education', sortOrder: 5 },
];

// ============================================================
// MAIN SEED FUNCTION
// ============================================================

async function main() {
  console.log('🌱 Seeding database...\n');

  // 1. Create SaaS Modules
  console.log('📦 Creating SaaS modules...');
  const createdModules = await Promise.all(
    modules.map((m) =>
      prisma.saaSModule.upsert({
        where: { code: m.code },
        update: { name: m.name, description: m.description, sortOrder: m.sortOrder },
        create: m,
      }),
    ),
  );
  console.log(`   ✅ ${createdModules.length} modules created`);

  // 2. Create Permissions
  console.log('🔐 Creating permissions...');
  const permissionsToCreate: Array<{ moduleId: string; name: string; code: string; description: string }> = [];
  for (const mod of createdModules) {
    for (const action of permissionActions) {
      permissionsToCreate.push({
        moduleId: mod.id,
        name: `${mod.name} ${action}`,
        code: `${mod.code}:${action}`,
        description: `${action} access for ${mod.name}`,
      });
    }
  }
  const createdPermissions = await Promise.all(
    permissionsToCreate.map((p) =>
      prisma.saaSPermission.upsert({
        where: { code: p.code },
        update: { name: p.name, description: p.description },
        create: p,
      }),
    ),
  );
  console.log(`   ✅ ${createdPermissions.length} permissions created`);

  // 3. Create SaaS Plans
  console.log('💳 Creating SaaS plans...');
  const createdPlans = await Promise.all(
    plans.map((p) =>
      prisma.saaSPlan.upsert({
        where: { name: p.name },
        update: { price: p.price, description: p.description },
        create: p,
      }),
    ),
  );
  console.log(`   ✅ ${createdPlans.length} plans created`);

  // 4. Assign all permissions to Premium & Enterprise plans
  console.log('🔗 Assigning permissions to plans...');
  for (const plan of createdPlans) {
    if (plan.name === 'Free') {
      // Free plan gets limited permissions
      const limitedModules = ['users', 'students', 'teachers'];
      const limitedPerms = createdPermissions.filter((p) =>
        limitedModules.some((m) => p.code.startsWith(m)),
      );
      for (const perm of limitedPerms) {
        await prisma.saaSPlanPermission.upsert({
          where: { planId_permissionId: { planId: plan.id, permissionId: perm.id } },
          update: {},
          create: { planId: plan.id, permissionId: perm.id },
        });
      }
    } else {
      // All other plans get all permissions
      for (const perm of createdPermissions) {
        await prisma.saaSPlanPermission.upsert({
          where: { planId_permissionId: { planId: plan.id, permissionId: perm.id } },
          update: {},
          create: { planId: plan.id, permissionId: perm.id },
        });
      }
    }
  }
  console.log('   ✅ Plan permissions assigned');

  // 5. Create System Roles
  console.log('👑 Creating system roles...');
  const roles = [
    { name: 'Super Admin', code: 'SUPER_ADMIN', description: 'Establishment owner', isSystem: true },
    { name: 'Admin', code: 'ADMIN', description: 'Administrative staff', isSystem: true },
    { name: 'Employee', code: 'EMPLOYEE', description: 'Office staff', isSystem: true },
    { name: 'Teacher', code: 'TEACHER', description: 'Teaching staff', isSystem: true },
    { name: 'Student', code: 'STUDENT', description: 'Students', isSystem: true },
    { name: 'Parent', code: 'PARENT', description: 'Parents & guardians', isSystem: true },
  ];

  const createdRoles = await Promise.all(
    roles.map((r) =>
      prisma.role.upsert({
        where: { code: r.code },
        update: { name: r.name, description: r.description },
        create: r,
      }),
    ),
  );
  console.log(`   ✅ ${createdRoles.length} roles created`);

  // 6. Assign permissions to roles
  console.log('🔗 Assigning permissions to roles...');
  const rolePermissionsMap: Record<string, string[]> = {
    SUPER_ADMIN: createdPermissions.map((p) => p.code), // All permissions
    ADMIN: createdPermissions.filter((p) => !p.code.startsWith('billing')).map((p) => p.code),
    EMPLOYEE: ['students:list', 'students:read', 'teachers:list', 'teachers:read', 'payments:list', 'payments:read'],
    TEACHER: ['students:list', 'students:read', 'lessons:list', 'lessons:read', 'lessons:create', 'grades:list', 'grades:read', 'grades:create', 'attendance:list', 'attendance:create', 'exams:list', 'exams:read', 'exams:create'],
    STUDENT: ['lessons:list', 'lessons:read', 'grades:list', 'grades:read', 'exams:list', 'exams:read', 'attendance:list', 'attendance:read'],
    PARENT: ['students:list', 'students:read', 'grades:list', 'grades:read', 'payments:list', 'payments:read', 'attendance:list', 'attendance:read'],
  };

  for (const role of createdRoles) {
    const permCodes = rolePermissionsMap[role.code] || [];
    const perms = createdPermissions.filter((p) => permCodes.includes(p.code));
    for (const perm of perms) {
      await prisma.rolePermission.upsert({
        where: { roleId_permissionId: { roleId: role.id, permissionId: perm.id } },
        update: {},
        create: { roleId: role.id, permissionId: perm.id },
      });
    }
  }
  console.log('   ✅ Role permissions assigned');

  // 7. Create Class Levels
  console.log('📚 Creating class levels...');
  const createdClassLevels = await Promise.all(
    classLevels.map((cl) =>
      prisma.classLevel.upsert({
        where: { code: cl.code },
        update: { name: cl.name, level: cl.level, sortOrder: cl.sortOrder },
        create: cl,
      }),
    ),
  );
  console.log(`   ✅ ${createdClassLevels.length} class levels created`);

  // 8. Create Establishment Categories
  console.log('🏫 Creating establishment categories...');
  const createdCategories = await Promise.all(
    establishmentCategories.map((c) =>
      prisma.establishmentCategory.upsert({
        where: { code: c.code },
        update: { name: c.name, description: c.description, sortOrder: c.sortOrder },
        create: c,
      }),
    ),
  );
  console.log(`   ✅ ${createdCategories.length} establishment categories created`);

  // 9. Create Super Admin User (Root)
  console.log('👤 Creating super admin user...');
  const hashedPassword = await bcrypt.hash('Admin@123', 12);
  const superAdmin = await prisma.user.upsert({
    where: { email: 'admin@bsofts.com' },
    update: {},
    create: {
      email: 'admin@bsofts.com',
      username: 'admin',
      firstName: 'Super',
      lastName: 'Admin',
      password: hashedPassword,
      isRoot: true,
      isActive: true,
    },
  });

  // Assign SUPER_ADMIN role
  await prisma.userRoleAssignment.upsert({
    where: {
      userId_roleId_establishmentId: {
        userId: superAdmin.id,
        roleId: createdRoles.find((r) => r.code === 'SUPER_ADMIN')!.id,
        establishmentId: null,
      },
    },
    update: {},
    create: {
      userId: superAdmin.id,
      roleId: createdRoles.find((r) => r.code === 'SUPER_ADMIN')!.id,
    },
  });
  console.log(`   ✅ Super admin user created: admin@bsofts.com / Admin@123`);

  console.log('\n🎉 Seeding complete!');
  console.log('\n📋 Summary:');
  console.log(`   - ${createdModules.length} modules`);
  console.log(`   - ${createdPermissions.length} permissions`);
  console.log(`   - ${createdPlans.length} plans`);
  console.log(`   - ${createdRoles.length} roles`);
  console.log(`   - ${createdClassLevels.length} class levels`);
  console.log(`   - ${createdCategories.length} establishment categories`);
  console.log(`   - 1 super admin user (admin@bsofts.com)`);
}

main()
  .then(async () => {
    await prisma.$disconnect();
  })
  .catch(async (e) => {
    console.error('❌ Error during seeding:', e);
    await prisma.$disconnect();
    process.exit(1);
  });

