import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { PaginatedDto } from '../common/dto/pagination.dto';

@Injectable()
export class EstablishmentsService {
  constructor(private prisma: PrismaService) {}

  async findAll(query: any) {
    const { page = 1, limit = 10, search, tenantId, isActive, sortBy, sortOrder } = query;
    const skip = (page - 1) * limit;

    const where: any = {};
    if (tenantId) where.tenantId = tenantId;
    if (isActive !== undefined) where.isActive = isActive;
    if (search) {
      where.OR = [
        { name: { contains: search, mode: 'insensitive' } },
        { email: { contains: search, mode: 'insensitive' } },
      ];
    }

    const orderBy: any = {};
    if (sortBy) {
      orderBy[sortBy] = sortOrder || 'asc';
    } else {
      orderBy.createdAt = 'desc';
    }

    const [data, total] = await Promise.all([
      this.prisma.establishment.findMany({
        where,
        skip,
        take: limit,
        orderBy,
        include: {
          tenant: {
            select: { id: true, user: { select: { firstName: true, lastName: true } } },
          },
          _count: {
            select: { classes: true, users: true },
          },
        },
      }),
      this.prisma.establishment.count({ where }),
    ]);

    return new PaginatedDto(data, total, page, limit);
  }

  async findOne(id: string) {
    const establishment = await this.prisma.establishment.findUnique({
      where: { id },
      include: {
        tenant: {
          select: { id: true, user: { select: { firstName: true, lastName: true } } },
        },
        classes: {
          select: { id: true, name: true, code: true },
          take: 10,
        },
        users: {
          select: { id: true, firstName: true, lastName: true, email: true },
          take: 10,
        },
        config: true,
      },
    });

    if (!establishment) {
      throw new NotFoundException(`Establishment with ID ${id} not found`);
    }

    return establishment;
  }

  async create(dto: any) {
    const tenant = await this.prisma.tenant.findUnique({ where: { id: dto.tenantId } });
    if (!tenant) throw new NotFoundException(`Tenant with ID ${dto.tenantId} not found`);

    return this.prisma.establishment.create({
      data: {
        name: dto.name,
        slug: dto.slug || dto.name.toLowerCase().replace(/\s+/g, '-'),
        category: dto.category || 'SCHOOL',
        country: dto.country || 'DZ',
        timezone: dto.timezone || 'Africa/Algiers',
        email: dto.email,
        phone: dto.phone,
        address: dto.address,
        logo: dto.logo,
        website: dto.website,
        isActive: dto.isActive ?? true,
        tenantId: dto.tenantId,
      },
      include: {
        tenant: { select: { id: true, user: { select: { firstName: true, lastName: true } } } },
      },
    });
  }

  async update(id: string, dto: any) {
    const establishment = await this.prisma.establishment.findUnique({ where: { id } });
    if (!establishment) {
      throw new NotFoundException(`Establishment with ID ${id} not found`);
    }

    return this.prisma.establishment.update({
      where: { id },
      data: {
        name: dto.name,
        slug: dto.slug,
        category: dto.category,
        country: dto.country,
        timezone: dto.timezone,
        email: dto.email,
        phone: dto.phone,
        address: dto.address,
        logo: dto.logo,
        website: dto.website,
        isActive: dto.isActive,
      },
      include: {
        tenant: { select: { id: true, user: { select: { firstName: true, lastName: true } } } },
      },
    });
  }

  async remove(id: string) {
    const establishment = await this.prisma.establishment.findUnique({ where: { id } });
    if (!establishment) {
      throw new NotFoundException(`Establishment with ID ${id} not found`);
    }

    // Soft delete
    await this.prisma.establishment.update({
      where: { id },
      data: { isActive: false },
    });

    return { message: 'Establishment deactivated successfully' };
  }
}

