import { IsString, IsOptional, IsBoolean, IsNumber, IsEnum, MinLength } from 'class-validator';
import { PaginationQueryDto } from '../../common/dto/pagination.dto';

export class CreateRoomDto {
  @IsString()
  establishmentId: string;

  @IsString()
  @MinLength(2)
  name: string;

