  @IsString()
  code?: string;

  @IsEnum(['CLASSROOM', 'LABORATORY', 'LIBRARY', 'GYM', 'AUDITORIUM', 'COMPUTER_LAB', 'ART_ROOM', 'MUSIC_ROOM', 'OTHER'])
  type: string;

  @IsNumber()
  capacity: number;

