  @IsNumber()
  floor?: number;

  @IsOptional()
  @IsString()
  building?: string;

  @IsOptional()
  @IsString()
  description?: string;
}

export class UpdateRoomDto {
  @IsOptional()
  @IsString()
  name?: string;

  @IsOptional()
  @IsString()
  code?: string;

  @IsOptional()
  @IsNumber()
  capacity?: number;

  @IsOptional()
  @IsNumber()
  floor?: number;

  @IsOptional()
  @IsString()
  building?: string;

  @IsOptional()
  @IsString()
  description?: string;

  @IsOptional()
  @IsBoolean()
  isActive?: boolean;
}

export class QueryRoomDto extends PaginationQueryDto {
  @IsOptional()
  @IsString()
  establishmentId?: string;

  @IsOptional()
  @IsEnum(['CLASSROOM', 'LABORATORY', 'LIBRARY', 'GYM', 'AUDITORIUM', 'COMPUTER_LAB', 'ART_ROOM', 'MUSIC_ROOM', 'OTHER'])
  type?: string;
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateRoomDto, UpdateRoomDto, QueryRoomDto } from './dto/room.dto';
import { PaginatedDto } from '../common/dto/pagination.dto';

@Injectable()
export class RoomsService {
  constructor(private prisma: PrismaService) {}

  async findAll(query: QueryRoomDto) {
    const { page = 1, limit = 10, search, establishmentId, type, sortBy, sortOrder } = query;
    const skip = (page - 1) * limit;

    const where: any = {};
    if (establishmentId) where.establishmentId = establishmentId;
    if (type) where.type = type;
    if (search) {
      where.OR = [
        { name: { contains: search, mode: 'insensitive' } },
        { code: { contains: search, mode: 'insensitive' } },
      ];
    }

    const orderBy: any = sortBy ? { [sortBy]: sortOrder || 'asc' } : { name: 'asc' };

    const [data, total] = await Promise.all([
      this.prisma.room.findMany({
        where, skip, take: limit, orderBy,
        include: { _count: { select: { equipment: true, sessions: true } } },
      }),
      this.prisma.room.count({ where }),
    ]);

    return new PaginatedDto(data, total, page, limit);
  }

  async findOne(id: string) {
    const room = await this.prisma.room.findUnique({
      where: { id },
      include: {
        equipment: true,
        sessions: { take: 5, orderBy: { date: 'desc' } },
      },
    });
    if (!room) throw new NotFoundException(`Room with ID ${id} not found`);
    return room;
  }

  async create(dto: CreateRoomDto) {
    return this.prisma.room.create({
      data: {
        establishmentId: dto.establishmentId,
        name: dto.name,
        code: dto.code,
        type: dto.type as any,
        capacity: dto.capacity,
        floor: dto.floor,
        building: dto.building,
        description: dto.description,
      },
    });
  }

  async update(id: string, dto: UpdateRoomDto) {
    const room = await this.prisma.room.findUnique({ where: { id } });
    if (!room) throw new NotFoundException(`Room with ID ${id} not found`);

    return this.prisma.room.update({
      where: { id },
      data: {
        name: dto.name,
        code: dto.code,
        capacity: dto.capacity,
        floor: dto.floor,
        building: dto.building,
        description: dto.description,
        isActive: dto.isActive,
      },
    });
  }

  async remove(id: string) {
    const room = await this.prisma.room.findUnique({ where: { id } });
    if (!room) throw new NotFoundException(`Room with ID ${id} not found`);
    await this.prisma.room.update({ where: { id }, data: { isActive: false } });
    return { message: 'Room deactivated successfully' };
  }
}

