import { IsString, IsOptional, IsEnum, IsDateString } from 'class-validator';
import { PaginationQueryDto } from '../../common/dto/pagination.dto';

export class MarkStudentAttendanceDto {
  @IsString()
  studentId: string;

  @IsString()
  sessionId: string;

  @IsEnum(['PRESENT', 'ABSENT', 'LATE', 'EXCUSED'])
  status: string;

  @IsOptional()
  @IsString()
  reason?: string;

  @IsOptional()
  @IsString()
  markedBy?: string;
}

export class BulkMarkAttendanceDto {
  @IsString()
  sessionId: string;

  attendances: Array<{
    studentId: string;
    status: 'PRESENT' | 'ABSENT' | 'LATE' | 'EXCUSED';
    reason?: string;
  }>;

  @IsOptional()
  @IsString()
  markedBy?: string;
}

export class QueryStudentAttendanceDto extends PaginationQueryDto {
  @IsOptional()
  @IsString()
  studentId?: string;

  @IsOptional()
  @IsString()
  sessionId?: string;

  @IsOptional()
  @IsString()
  classId?: string;

  @IsOptional()
  @IsDateString()
  startDate?: string;

  @IsOptional()
  @IsDateString()
  endDate?: string;
}

import { Injectable, NotFoundException, ConflictException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { MarkStudentAttendanceDto, BulkMarkAttendanceDto, QueryStudentAttendanceDto } from './dto/student-attendance.dto';
import { PaginatedDto } from '../common/dto/pagination.dto';

@Injectable()
export class StudentAttendanceService {
  constructor(private prisma: PrismaService) {}

  async findAll(query: QueryStudentAttendanceDto) {
    const { page = 1, limit = 10, studentId, sessionId, classId, startDate, endDate, sortBy, sortOrder } = query;
    const skip = (page - 1) * limit;

    const where: any = {};
    if (studentId) where.studentId = studentId;
    if (sessionId) where.sessionId = sessionId;
    if (classId) where.session = { classId };
    if (startDate || endDate) {
      where.session = { ...where.session, date: {} };
      if (startDate) where.session.date.gte = new Date(startDate);
      if (endDate) where.session.date.lte = new Date(endDate);
    }

    const orderBy: any = sortBy ? { [sortBy]: sortOrder || 'asc' } : { createdAt: 'desc' };

    const [data, total] = await Promise.all([
      this.prisma.studentAttendance.findMany({
        where, skip, take: limit, orderBy,
        include: {
          student: { select: { id: true, firstName: true, lastName: true, registrationNumber: true } },
          session: { select: { id: true, date: true, topic: true, class: { select: { id: true, name: true } } } },
        },
      }),
      this.prisma.studentAttendance.count({ where }),
    ]);

    return new PaginatedDto(data, total, page, limit);
  }

  async findOne(id: string) {
    const attendance = await this.prisma.studentAttendance.findUnique({
      where: { id },
      include: {
        student: true,
        session: { include: { class: true } },
      },
    });
    if (!attendance) throw new NotFoundException(`Attendance with ID ${id} not found`);
    return attendance;
  }

  async mark(dto: MarkStudentAttendanceDto) {
    const existing = await this.prisma.studentAttendance.findUnique({
      where: { studentId_sessionId: { studentId: dto.studentId, sessionId: dto.sessionId } },
    });

    if (existing) {
      return this.prisma.studentAttendance.update({
        where: { id: existing.id },
        data: { status: dto.status as any, reason: dto.reason, markedBy: dto.markedBy },
      });
    }

    return this.prisma.studentAttendance.create({
      data: {
        studentId: dto.studentId,
        sessionId: dto.sessionId,
        status: dto.status as any,
        reason: dto.reason,
        markedBy: dto.markedBy,
      },
    });
  }

  async bulkMark(dto: BulkMarkAttendanceDto) {
    const results = [];
    for (const att of dto.attendances) {
      const result = await this.mark({
        studentId: att.studentId,
        sessionId: dto.sessionId,
        status: att.status,
        reason: att.reason,
        markedBy: dto.markedBy,
      });
      results.push(result);
    }
    return { message: `${results.length} attendance records marked`, data: results };
  }

  async getStats(studentId: string, academicYearId?: string) {
    const where: any = { studentId };
    if (academicYearId) {
      where.session = { academicYearId };
    }

    const [total, present, absent, late, excused] = await Promise.all([
      this.prisma.studentAttendance.count({ where }),
      this.prisma.studentAttendance.count({ where: { ...where, status: 'PRESENT' } }),
      this.prisma.studentAttendance.count({ where: { ...where, status: 'ABSENT' } }),
      this.prisma.studentAttendance.count({ where: { ...where, status: 'LATE' } }),
      this.prisma.studentAttendance.count({ where: { ...where, status: 'EXCUSED' } }),
    ]);

    return { total, present, absent, late, excused, rate: total > 0 ? (present / total) * 100 : 0 };
  }

  async remove(id: string) {
    const attendance = await this.prisma.studentAttendance.findUnique({ where: { id } });
    if (!attendance) throw new NotFoundException(`Attendance with ID ${id} not found`);
    await this.prisma.studentAttendance.delete({ where: { id } });
    return { message: 'Attendance record deleted' };
  }
}

import {
  Controller, Get, Post, Delete, Body, Param, Query, UseGuards, ParseUUIDPipe,
} from '@nestjs/common';
import { StudentAttendanceService } from './student-attendance.service';
import { MarkStudentAttendanceDto, BulkMarkAttendanceDto, QueryStudentAttendanceDto } from './dto/student-attendance.dto';
import { JwtAuthGuard } from '../common/guards/jwt-auth.guard';
import { RolesGuard } from '../common/guards/roles.guard';
import { Permissions } from '../common/decorators/permissions.decorator';

@Controller('student-attendance')
@UseGuards(JwtAuthGuard, RolesGuard)
export class StudentAttendanceController {
  constructor(private readonly service: StudentAttendanceService) {}

  @Get()
  @Permissions('attendance:list')
  findAll(@Query() query: QueryStudentAttendanceDto) {
    return this.service.findAll(query);
  }

  @Get('stats/:studentId')
  @Permissions('attendance:read')
  getStats(@Param('studentId', ParseUUIDPipe) studentId: string, @Query('academicYearId') academicYearId?: string) {
    return this.service.getStats(studentId, academicYearId);
  }

  @Get(':id')
  @Permissions('attendance:read')
  findOne(@Param('id', ParseUUIDPipe) id: string) {
    return this.service.findOne(id);
  }

  @Post()
  @Permissions('attendance:create')
  mark(@Body() dto: MarkStudentAttendanceDto) {
    return this.service.mark(dto);
  }

  @Post('bulk')
  @Permissions('attendance:create')
  bulkMark(@Body() dto: BulkMarkAttendanceDto) {
    return this.service.bulkMark(dto);
  }

  @Delete(':id')
  @Permissions('attendance:delete')
  remove(@Param('id', ParseUUIDPipe) id: string) {
    return this.service.remove(id);
  }
}

