import { IsString, IsOptional, IsNumber, IsEnum, IsDateString, Min } from 'class-validator';
import { PaginationQueryDto } from '../../common/dto/pagination.dto';

export class CreateStudentPaymentDto {
  @IsString()
  studentId: string;

  @IsString()
  parentId: string;

  @IsOptional()
  @IsString()
  planId?: string;

  @IsNumber()
  @Min(0)
  amount: number;

  @IsString()
  currency: string;

  @IsEnum(['CASH', 'CHECK', 'CARD', 'BANK_TRANSFER', 'STRIPE', 'PAYPAL'])
  method: string;

  @IsOptional()
  @IsDateString()
  dueDate?: string;

  @IsOptional()
  @IsString()
  reference?: string;

  @IsOptional()
  @IsString()
  notes?: string;

  @IsOptional()
  @IsString()
  createdBy?: string;
}

export class UpdatePaymentStatusDto {
  @IsEnum(['PENDING', 'PAID', 'PARTIAL', 'OVERDUE', 'CANCELLED', 'REFUNDED'])
  status: string;

  @IsOptional()
  @IsDateString()
  paidAt?: string;

  @IsOptional()
  @IsString()
  reference?: string;

  @IsOptional()
  @IsString()
  stripePaymentId?: string;

  @IsOptional()
  @IsString()
  paypalPaymentId?: string;
}

export class QueryStudentPaymentDto extends PaginationQueryDto {
  @IsOptional()
  @IsString()
  studentId?: string;

  @IsOptional()
  @IsString()
  parentId?: string;

  @IsOptional()
  @IsEnum(['PENDING', 'PAID', 'PARTIAL', 'OVERDUE', 'CANCELLED', 'REFUNDED'])
  status?: string;

  @IsOptional()
  @IsEnum(['CASH', 'CHECK', 'CARD', 'BANK_TRANSFER', 'STRIPE', 'PAYPAL'])
  method?: string;
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateStudentPaymentDto, UpdatePaymentStatusDto, QueryStudentPaymentDto } from './dto/student-payment.dto';
import { PaginatedDto } from '../common/dto/pagination.dto';

@Injectable()
export class StudentPaymentsService {
  constructor(private prisma: PrismaService) {}

  async findAll(query: QueryStudentPaymentDto) {
    const { page = 1, limit = 10, search, studentId, parentId, status, method, sortBy, sortOrder } = query;
    const skip = (page - 1) * limit;

    const where: any = {};
    if (studentId) where.studentId = studentId;
    if (parentId) where.parentId = parentId;
    if (status) where.status = status;
    if (method) where.method = method;
    if (search) {
      where.OR = [
        { reference: { contains: search, mode: 'insensitive' } },
        { notes: { contains: search, mode: 'insensitive' } },
      ];
    }

    const orderBy: any = sortBy ? { [sortBy]: sortOrder || 'asc' } : { createdAt: 'desc' };

    const [data, total] = await Promise.all([
      this.prisma.studentPayment.findMany({
        where, skip, take: limit, orderBy,
        include: {
          student: { select: { id: true, firstName: true, lastName: true, registrationNumber: true } },
          parent: { select: { id: true, firstName: true, lastName: true } },
          plan: { select: { id: true, name: true } },
        },
      }),
      this.prisma.studentPayment.count({ where }),
    ]);

    return new PaginatedDto(data, total, page, limit);
  }

  async findOne(id: string) {
    const payment = await this.prisma.studentPayment.findUnique({
      where: { id },
      include: { student: true, parent: true, plan: true },
    });
    if (!payment) throw new NotFoundException(`Payment with ID ${id} not found`);
    return payment;
  }

  async create(dto: CreateStudentPaymentDto) {
    return this.prisma.studentPayment.create({
      data: {
        studentId: dto.studentId,
        parentId: dto.parentId,
        planId: dto.planId,
        amount: dto.amount,
        currency: dto.currency,
        method: dto.method as any,
        dueDate: dto.dueDate ? new Date(dto.dueDate) : null,
        reference: dto.reference,
        notes: dto.notes,
        createdBy: dto.createdBy,
      },
    });
  }

  async updateStatus(id: string, dto: UpdatePaymentStatusDto) {
    const payment = await this.prisma.studentPayment.findUnique({ where: { id } });
    if (!payment) throw new NotFoundException(`Payment with ID ${id} not found`);

    return this.prisma.studentPayment.update({
      where: { id },
      data: {
        status: dto.status as any,
        paidAt: dto.paidAt ? new Date(dto.paidAt) : dto.status === 'PAID' ? new Date() : undefined,
        reference: dto.reference,
        stripePaymentId: dto.stripePaymentId,
        paypalPaymentId: dto.paypalPaymentId,
      },
    });
  }

  async getStudentPayments(studentId: string) {
    return this.prisma.studentPayment.findMany({
      where: { studentId },
      orderBy: { createdAt: 'desc' },
      include: { plan: { select: { id: true, name: true } } },
    });
  }

  async remove(id: string) {
    const payment = await this.prisma.studentPayment.findUnique({ where: { id } });
    if (!payment) throw new NotFoundException(`Payment with ID ${id} not found`);
    await this.prisma.studentPayment.update({ where: { id }, data: { status: 'CANCELLED' } });
    return { message: 'Payment cancelled' };
  }
}

