export class GenerateReportDto {
  @IsEnum([
    'ATTENDANCE', 'EXAM_RESULTS', 'FINANCIAL', 'ENROLLMENT',
    'TEACHER_PERFORMANCE', 'CLASS_PERFORMANCE', 'PAYMENT_COLLECTION'
  ])
  reportType: string;

  @IsOptional()
  @IsString()
  establishmentId?: string;

  @IsOptional()
  @IsString()
  academicYearId?: string;

  @IsOptional()
  @IsDateString()
  startDate?: string;

  @IsOptional()
  @IsDateString()
  endDate?: string;

  @IsOptional()
  @IsString()
  classId?: string;

  @IsOptional()
  @IsString()
  studentId?: string;
