import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateLandingContentDto, UpdateLandingContentDto } from './dto/landing.dto';

@Injectable()
export class LandingService {
  constructor(private prisma: PrismaService) {}

  async getContent(key?: string) {
    if (key) {
      const content = await this.prisma.landingContent.findUnique({ where: { key } });
      if (!content) throw new NotFoundException(`Content with key ${key} not found`);
      return content;
    }

    return this.prisma.landingContent.findMany({
      orderBy: { key: 'asc' },
    });
  }

  async create(dto: CreateLandingContentDto) {
    return this.prisma.landingContent.create({
      data: {
        key: dto.key,
        title: dto.title,
        subtitle: dto.subtitle,
        content: dto.content,
        metadata: dto.metadata,
        features: dto.features,
        testimonials: dto.testimonials,
        pricingPlans: dto.pricingPlans,
      },
    });
  }

  async update(key: string, dto: UpdateLandingContentDto) {
    const content = await this.prisma.landingContent.findUnique({ where: { key } });
    if (!content) throw new NotFoundException(`Content with key ${key} not found`);

    return this.prisma.landingContent.update({
      where: { key },
      data: {
        title: dto.title,
        subtitle: dto.subtitle,
        content: dto.content,
        metadata: dto.metadata,
        features: dto.features,
        testimonials: dto.testimonials,
        pricingPlans: dto.pricingPlans,
      },
    });
  }

  async getStats() {
    const [tenants, users, students] = await Promise.all([
      this.prisma.tenant.count(),
      this.prisma.user.count(),
      this.prisma.student.count(),
    ]);

    return {
      tenants,
      users,
      students,
      establishments: tenants,
    };
  }
}

import {
  Controller, Get, Post, Put, Body, Param, UseGuards,
} from '@nestjs/common';
import { LandingService } from './landing.service';
import { CreateLandingContentDto, UpdateLandingContentDto } from './dto/landing.dto';
import { JwtAuthGuard } from '../common/guards/jwt-auth.guard';

@Controller('landing')
export class LandingController {
  constructor(private readonly service: LandingService) {}

  @Get('content')
  getContent() {
    return this.service.getContent();
  }

  @Get('content/:key')
  getContentByKey(@Param('key') key: string) {
    return this.service.getContent(key);
  }

  @Get('stats')
  getStats() {
    return this.service.getStats();
  }

  @Post('content')
  @UseGuards(JwtAuthGuard)
  create(@Body() dto: CreateLandingContentDto) {
    return this.service.create(dto);
  }

  @Put('content/:key')
  @UseGuards(JwtAuthGuard)
  update(@Param('key') key: string, @Body() dto: UpdateLandingContentDto) {
    return this.service.update(key, dto);
  }
}

