export default function DashboardPage() {
  const [stats, setStats] = useState<Stats>({
    students: 0,
    teachers: 0,
    classes: 0,
    revenue: 0,
  });

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const [studentsRes, teachersRes, classesRes] = await Promise.all([
          api.get('/students?limit=1'),
          api.get('/teachers?limit=1'),
          api.get('/classes?limit=1'),
        ]);

        setStats({
          students: studentsRes.data.meta?.total || 0,
          teachers: teachersRes.data.meta?.total || 0,
          classes: classesRes.data.meta?.total || 0,
          revenue: 0,
        });
      } catch (error) {
        console.error('Failed to fetch stats:', error);
      }
    };

    fetchStats();
  }, []);

  const statCards = [
    {
      title: 'Total Students',
      value: stats.students,
      icon: GraduationCap,
      color: 'bg-blue-500',
      change: '+12%',
    },
    {
      title: 'Total Teachers',
      value: stats.teachers,
      icon: Users,
      color: 'bg-green-500',
      change: '+5%',
    },
    {
      title: 'Active Classes',
      value: stats.classes,
      icon: BookOpen,
      color: 'bg-purple-500',
      change: '+8%',
    },
    {
      title: 'Revenue',
      value: `${stats.revenue.toLocaleString()} DZD`,
      icon: CreditCard,
      color: 'bg-yellow-500',
      change: '+23%',
    },
  ];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {statCards.map((stat) => (
          <Card key={stat.title}>
            <CardContent>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">{stat.title}</p>
                  <p className="text-2xl font-bold text-gray-900 mt-1">{stat.value}</p>
                </div>
                <div className={`${stat.color} p-3 rounded-lg`}>
                  <stat.icon className="w-6 h-6 text-white" />
                </div>
              </div>
              <div className="flex items-center gap-1 mt-4 text-sm">
                <TrendingUp className="w-4 h-4 text-green-500" />
                <span className="text-green-500">{stat.change}</span>
                <span className="text-gray-500">vs last month</span>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="grid lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <h3 className="text-lg font-semibold">Recent Activity</h3>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {[
                { action: 'New student enrolled', time: '2 minutes ago', type: 'student' },
                { action: 'Attendance marked for Class A', time: '15 minutes ago', type: 'attendance' },
                { action: 'Exam results published', time: '1 hour ago', type: 'exam' },
                { action: 'Payment received from John Doe', time: '2 hours ago', type: 'payment' },
              ].map((activity, i) => (
                <div key={i} className="flex items-center justify-between py-2 border-b border-gray-100 last:border-0">
                  <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-blue-500" />
                    <span className="text-sm text-gray-700">{activity.action}</span>
                  </div>
                  <span className="text-xs text-gray-500">{activity.time}</span>
