'use client';

import { useEffect, useState } from 'react';
import { Calendar, Check, X, Clock, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import api from '@/lib/api';

interface Student {
  id: string;
  firstName: string;
  lastName: string;
  matricule: string;
}

interface Attendance {
  id: string;
  student: Student;
  date: string;
  status: 'PRESENT' | 'ABSENT' | 'LATE' | 'EXCUSED';
  remarks?: string;
}

export default function AttendancePage() {
  const [attendances, setAttendances] = useState<Attendance[]>([]);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchAttendances();
  }, [selectedDate]);

  const fetchAttendances = async () => {
    try {
      const response = await api.get('/student-attendance', {
        params: { date: selectedDate },
      });
      setAttendances(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch attendances:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'PRESENT':
        return <Check className="w-4 h-4 text-green-500" />;
      case 'ABSENT':
        return <X className="w-4 h-4 text-red-500" />;
      case 'LATE':
        return <Clock className="w-4 h-4 text-yellow-500" />;
      case 'EXCUSED':
        return <AlertCircle className="w-4 h-4 text-blue-500" />;
      default:
        return null;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PRESENT':
        return 'bg-green-100 text-green-700';
      case 'ABSENT':
        return 'bg-red-100 text-red-700';
      case 'LATE':
        return 'bg-yellow-100 text-yellow-700';
      case 'EXCUSED':
        return 'bg-blue-100 text-blue-700';
      default:
        return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Attendance</h1>
          <p className="text-gray-600">Track student attendance</p>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Calendar className="w-5 h-5 text-gray-500" />
            <input
              type="date"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
              className="border border-gray-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
          <Button>
            <Check className="w-4 h-4 mr-2" />
            Mark Attendance
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-4 gap-4">
        <Card>
          <CardContent>
            <div className="text-center">
              <p className="text-3xl font-bold text-green-600">
                {attendances.filter((a) => a.status === 'PRESENT').length}
              </p>
              <p className="text-sm text-gray-600 mt-1">Present</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent>
            <div className="text-center">
              <p className="text-3xl font-bold text-red-600">
                {attendances.filter((a) => a.status === 'ABSENT').length}
              </p>
              <p className="text-sm text-gray-600 mt-1">Absent</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent>
            <div className="text-center">
              <p className="text-3xl font-bold text-yellow-600">
                {attendances.filter((a) => a.status === 'LATE').length}
              </p>
              <p className="text-sm text-gray-600 mt-1">Late</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent>
            <div className="text-center">
              <p className="text-3xl font-bold text-blue-600">
                {attendances.filter((a) => a.status === 'EXCUSED').length}
              </p>
              <p className="text-sm text-gray-600 mt-1">Excused</p>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <h3 className="text-lg font-semibold">Attendance Records</h3>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="flex items-center justify-center py-8">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600" />
            </div>
          ) : attendances.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              No attendance records for this date
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-gray-200">
                    <th className="text-left py-3 px-4 text-sm font-medium text-gray-600">Student</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-gray-600">Matricule</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-gray-600">Status</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-gray-600">Remarks</th>
                  </tr>
                </thead>
                <tbody>
                  {attendances.map((attendance) => (
                    <tr key={attendance.id} className="border-b border-gray-100 hover:bg-gray-50">
                      <td className="py-3 px-4">
                        <span className="font-medium text-gray-900">
                          {attendance.student.firstName} {attendance.student.lastName}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-gray-600">{attendance.student.matricule}</td>
                      <td className="py-3 px-4">
                        <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(attendance.status)}`}>
                          {getStatusIcon(attendance.status)}
                          {attendance.status}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-gray-600">{attendance.remarks || '-'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

