    try {
      const response = await api.get('/student-payments');
      setPayments(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch payments:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredPayments = payments.filter(
    (p) =>
      p.student?.firstName.toLowerCase().includes(search.toLowerCase()) ||
      p.student?.lastName.toLowerCase().includes(search.toLowerCase()) ||
      p.feeType?.name.toLowerCase().includes(search.toLowerCase())
  );

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'PAID':
        return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'PENDING':
        return <Clock className="w-4 h-4 text-yellow-500" />;
