            name="Students"
          />
          <Line
            type="monotone"
            dataKey="teachers"
            stroke="#10B981"
            strokeWidth={2}
            dot={{ fill: '#10B981' }}
            name="Teachers"
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

