import { NestFactory } from '@nestjs/core';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import { AppModule } from './app.module';
import { AllExceptionsFilter } from './common/filters';
import { AppValidationPipe } from './common/pipes';
import { Logger } from '@nestjs/common';

async function bootstrap() {
  const logger = new Logger('Bootstrap');
  const app = await NestFactory.create(AppModule);

  // Global prefix
  app.setGlobalPrefix('api');

  // CORS
  app.enableCors({
    origin: process.env.FRONTEND_URL || 'http://localhost:3025',
    credentials: true,
  });

  // Global pipes
  app.useGlobalPipes(AppValidationPipe);

  // Global filters
  app.useGlobalFilters(new AllExceptionsFilter());

  // Trust proxy for rate limiting
  app.getHttpAdapter().getInstance().set('trust proxy', 1);

  // Swagger documentation
  const config = new DocumentBuilder()
    .setTitle('BSofts School API')
    .setDescription('API documentation for BSofts School - Multi-tenant School Management System')
    .setVersion('1.0')
    .addTag('Auth')
    .addTag('Users')
    .addTag('Roles')
    .addTag('Permissions')
    .addTag('Establishments')
    .addTag('Tenants')
    .addTag('Classes')
    .addTag('Students')
    .addTag('Teachers')
    .addTag('Parents')
    .addTag('Employees')
    .addTag('Academic')
    .addTag('Lessons')
    .addTag('Exams')
    .addTag('Payments')
    .addTag('Caisses')
    .addTag('Finance')
    .addTag('Attendance')
    .addTag('Scheduling')
    .addTag('Reports')
    .addTag('Settings')
    .addBearerAuth()
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api-docs', app, document);

  const port = process.env.PORT || 3025;
  await app.listen(port);
  logger.log(`Application running on: http://localhost:${port}`);
  logger.log(`API documentation: http://localhost:${port}/api-docs`);

  console.log(`http://localhost:${port}`);
  console.log(`http://localhost:${port}/api-docs`);
}
bootstrap();

