    { name: 'Journée de la République', startDate: new Date('2025-10-15'), endDate: new Date('2025-10-15'), type: 'PUBLIC' as const },
    { name: 'Toussaint', startDate: new Date('2025-11-01'), endDate: new Date('2025-11-01'), type: 'PUBLIC' as const },
