    { name: 'Vacances d\'hiver (suite)', startDate: new Date('2026-02-14'), endDate: new Date('2026-02-22'), type: 'VACATION' as const },
    { name: 'Journée des Martyrs', startDate: new Date('2026-04-09'), endDate: new Date('2026-04-09'), type: 'PUBLIC' as const },
    { name: 'Vacances de Pâques', startDate: new Date('2026-04-10'), endDate: new Date('2026-04-20'), type: 'VACATION' as const },
    { name: 'Fête du Travail', startDate: new Date('2026-05-01'), endDate: new Date('2026-05-01'), type: 'PUBLIC' as const },
    { name: 'Vacances d\'été', startDate: new Date('2026-06-15'), endDate: new Date('2026-09-01'), type: 'VACATION' as const },
  ];
  const createdHolidays = [];
  for (const h of holidayData) {
    for (const establishment of createdEstablishments) {
      const existing = await prisma.holiday.findFirst({
        where: { name: h.name, establishmentId: establishment.id },
      });
      if (!existing) {
        const holiday = await prisma.holiday.create({
          data: {
            name: h.name,
            startDate: h.startDate,
            endDate: h.endDate,
            type: h.type,
            establishmentId: establishment.id,
          },
        });
        createdHolidays.push(holiday);
      }
    }
  }
  console.log(`   ✅ ${createdHolidays.length} holidays created`);

  // 39. Create TeacherLeave
