import {
  Controller, Get, Post, Put, Delete, Body, Param, Query, UseGuards, ParseUUIDPipe,
} from '@nestjs/common';
import { StudentsService } from './students.service';
import { CreateStudentDto, UpdateStudentDto, QueryStudentDto } from './dto/student.dto';
import { JwtAuthGuard } from '../common/guards/jwt-auth.guard';
import { RolesGuard } from '../common/guards/roles.guard';
import { Permissions } from '../common/decorators/permissions.decorator';
import { Roles } from '../common/decorators/roles.decorator';

@Controller('students')
@UseGuards(JwtAuthGuard, RolesGuard)
export class StudentsController {
  constructor(private readonly service: StudentsService) {}

  @Get()
  @Permissions('students:list')
  findAll(@Query() query: QueryStudentDto) {
    return this.service.findAll(query);
  }

  @Get(':id')
  @Permissions('students:read')
  findOne(@Param('id', ParseUUIDPipe) id: string) {
    return this.service.findOne(id);
  }

  @Post()
  @Permissions('students:create')
  @Roles('ROOT', 'SUPER_ADMIN', 'ADMIN', 'EMPLOYEE')
  create(@Body() dto: CreateStudentDto) {
    return this.service.create(dto);
  }

  @Put(':id')
  @Permissions('students:update')
  @Roles('ROOT', 'SUPER_ADMIN', 'ADMIN')
  update(@Param('id', ParseUUIDPipe) id: string, @Body() dto: UpdateStudentDto) {
    return this.service.update(id, dto);
  }

  @Delete(':id')
  @Permissions('students:delete')
  @Roles('ROOT', 'SUPER_ADMIN')
  remove(@Param('id', ParseUUIDPipe) id: string) {
    return this.service.remove(id);
  }
}

