'use client';

import { useEffect, useState } from 'react';
import { Plus, Edit, Trash2, CreditCard } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import api from '@/lib/api';

interface Plan {
  id: string;
  name: string;
  description: string;
  price: number;
  currency: string;
  interval: string;
  isActive: boolean;
  sortOrder: number;
  features?: { code: string; value: string; description: string }[];
}

export default function PlansPage() {
  const [plans, setPlans] = useState<Plan[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editPlan, setEditPlan] = useState<Plan | null>(null);
  const [form, setForm] = useState({ name: '', description: '', price: 0, currency: 'TND', interval: 'MONTHLY' });

  useEffect(() => { fetchPlans(); }, []);

  const fetchPlans = async () => {
    try {
      const res = await api.get('/saas-plans');
      setPlans(res.data.data || res.data || []);
    } catch (e) { console.error(e); }
    finally { setIsLoading(false); }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editPlan) {
        await api.patch(`/saas-plans/${editPlan.id}`, form);
      } else {
        await api.post('/saas-plans', form);
      }
      setIsFormOpen(false);
      setEditPlan(null);
      setForm({ name: '', description: '', price: 0, currency: 'TND', interval: 'MONTHLY' });
      fetchPlans();
    } catch (e) { console.error(e); }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this plan?')) return;
    try { await api.delete(`/saas-plans/${id}`); fetchPlans(); } catch (e) { console.error(e); }
  };

  const intervalLabels: Record<string, string> = { MONTHLY: 'Monthly', YEARLY: 'Yearly' };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">SaaS Plans</h1>
          <p className="text-gray-600">Manage subscription plans for tenants</p>
        </div>
        <Button onClick={() => { setEditPlan(null); setForm({ name: '', description: '', price: 0, currency: 'TND', interval: 'MONTHLY' }); setIsFormOpen(true); }}>
          <Plus className="w-4 h-4 mr-2" />Add Plan
        </Button>
      </div>

      {isFormOpen && (
        <Card>
          <CardHeader>
            <h3 className="font-semibold">{editPlan ? 'Edit Plan' : 'New Plan'}</h3>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                  <input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" required />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Price (TND)</label>
                  <input type="number" value={form.price} onChange={(e) => setForm({ ...form, price: Number(e.target.value) })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" required />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Interval</label>
                  <select value={form.interval} onChange={(e) => setForm({ ...form, interval: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm">
                    <option value="MONTHLY">Monthly</option>
                    <option value="YEARLY">Yearly</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Currency</label>
                  <select value={form.currency} onChange={(e) => setForm({ ...form, currency: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm">
                    <option value="TND">TND</option>
                    <option value="EUR">EUR</option>
                    <option value="USD">USD</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                <textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" rows={2} />
              </div>
              <div className="flex gap-2">
                <Button type="submit">{editPlan ? 'Update' : 'Create'}</Button>
                <Button type="button" variant="outline" onClick={() => { setIsFormOpen(false); setEditPlan(null); }}>Cancel</Button>
              </div>
            </form>
          </CardContent>
        </Card>
      )}

      <Card>
        <CardContent className="p-0">
          {isLoading ? (
            <div className="flex items-center justify-center py-8"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600" /></div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 p-6">
              {plans.map((plan) => (
                <div key={plan.id} className={`rounded-xl border-2 p-6 ${plan.isActive ? 'border-blue-200 bg-blue-50/30' : 'border-gray-200 bg-gray-50'}`}>
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-lg bg-blue-100 flex items-center justify-center">
                      <CreditCard className="w-5 h-5 text-blue-600" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-gray-900">{plan.name}</h3>
                      <span className="text-xs text-gray-500">{intervalLabels[plan.interval] || plan.interval}</span>
                    </div>
                  </div>
                  <div className="mb-4">
                    <span className="text-3xl font-bold text-gray-900">{plan.price}</span>
                    <span className="text-sm text-gray-500 ml-1">{plan.currency}</span>
                  </div>
                  <p className="text-sm text-gray-600 mb-4">{plan.description}</p>
                  <div className="flex gap-2">
                    <button onClick={() => { setEditPlan(plan); setForm({ name: plan.name, description: plan.description, price: plan.price, currency: plan.currency, interval: plan.interval }); setIsFormOpen(true); }}
                      className="flex-1 flex items-center justify-center gap-1 px-3 py-1.5 text-sm text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50">
                      <Edit className="w-3.5 h-3.5" />Edit
                    </button>
                    <button onClick={() => handleDelete(plan.id)}
                      className="flex items-center justify-center px-3 py-1.5 text-sm text-red-600 bg-white border border-gray-300 rounded-lg hover:bg-red-50">
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { Building2, ExternalLink } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import api from '@/lib/api';

interface Tenant {
  id: string;
  userId: string;
  user?: { id: string; email: string; firstName: string; lastName: string; username: string };
  establishments?: { id: string; name: string; slug: string; category: string }[];
  subscriptions?: { id: string; status: string; plan?: { name: string; price: number } }[];
  settings?: { currency: string; language: string; theme: string };
  createdAt: string;
}

export default function TenantsPage() {
  const [tenants, setTenants] = useState<Tenant[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => { fetchTenants(); }, []);

  const fetchTenants = async () => {
    try {
      const res = await api.get('/tenants');
      setTenants(res.data.data || res.data || []);
    } catch (e) { console.error(e); }
    finally { setIsLoading(false); }
  };

  const statusColors: Record<string, string> = {
    ACTIVE: 'bg-green-100 text-green-700',
    TRIAL: 'bg-yellow-100 text-yellow-700',
    EXPIRED: 'bg-red-100 text-red-700',
    CANCELLED: 'bg-gray-100 text-gray-700',
  };

  const categoryLabels: Record<string, string> = {
    DAYCARE: 'Daycare', SCHOOL: 'School', MIDDLE_SCHOOL: 'Middle School',
    HIGH_SCHOOL: 'High School', UNIVERSITY: 'University',
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Tenants</h1>
        <p className="text-gray-600">Manage all registered tenants on the platform</p>
      </div>

      <Card>
        <CardContent className="p-0">
          {isLoading ? (
            <div className="flex items-center justify-center py-8"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600" /></div>
          ) : tenants.length === 0 ? (
            <div className="text-center py-8 text-gray-500">No tenants found</div>
          ) : (
            <div className="divide-y divide-gray-200">
              {tenants.map((tenant) => {
                const sub = tenant.subscriptions?.[0];
                return (
                  <div key={tenant.id} className="p-6 hover:bg-gray-50 transition-colors">
                    <div className="flex items-start justify-between">
                      <div className="flex items-start gap-4">
                        <div className="w-12 h-12 rounded-xl bg-blue-100 flex items-center justify-center">
                          <Building2 className="w-6 h-6 text-blue-600" />
                        </div>
                        <div>
                          <h3 className="font-semibold text-gray-900">
                            {tenant.user?.firstName} {tenant.user?.lastName}
                          </h3>
                          <p className="text-sm text-gray-500">{tenant.user?.email}</p>
                          <div className="flex items-center gap-3 mt-2">
                            {tenant.establishments?.map((est) => (
                              <span key={est.id} className="inline-flex items-center gap-1 px-2 py-1 bg-gray-100 rounded-md text-xs font-medium text-gray-700">
                                {est.name}
                                <span className="text-gray-400">({categoryLabels[est.category] || est.category})</span>
                              </span>
                            ))}
                          </div>
                          <div className="flex items-center gap-4 mt-2 text-xs text-gray-500">
                            {tenant.settings && (
