'use client';

import { useEffect, useState } from 'react';
import { Shield, Check, X } from 'lucide-react';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import api from '@/lib/api';

interface Role {
  id: string;
  name: string;
  code: string;
  isSystem: boolean;
  permissions?: { permission: { id: string; code: string; name: string } }[];
}

interface Permission {
  id: string;
  code: string;
  name: string;
  module?: { code: string; name: string };
}

export default function PermissionsPage() {
  const [roles, setRoles] = useState<Role[]>([]);
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [rolePermissions, setRolePermissions] = useState<Record<string, Set<string>>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [selectedRole, setSelectedRole] = useState<string | null>(null);
  const [modules, setModules] = useState<Record<string, { name: string; permissions: Permission[] }>>({});

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    try {
      const [rolesRes, permsRes] = await Promise.all([
        api.get('/roles'),
        api.get('/permissions'),
      ]);
      const rolesData = rolesRes.data.data || rolesRes.data || [];
      const permsData = permsRes.data.data || permsRes.data || [];

      setRoles(rolesData);
      setPermissions(permsData);

      const rpm: Record<string, Set<string>> = {};
      for (const role of rolesData) {
        rpm[role.id] = new Set(
          (role.permissions || []).map((rp: any) => rp.permission?.code || rp.permissionId)
        );
      }
      setRolePermissions(rpm);

      const modMap: Record<string, { name: string; permissions: Permission[] }> = {};
      for (const perm of permsData) {
        const modCode = perm.code.split(':')[0];
        if (!modMap[modCode]) {
          modMap[modCode] = { name: perm.module?.name || modCode, permissions: [] };
        }
        modMap[modCode].permissions.push(perm);
      }
      setModules(modMap);

      if (rolesData.length > 0) setSelectedRole(rolesData[0].id);
    } catch (e) { console.error(e); }
    finally { setIsLoading(false); }
  };

  const togglePermission = async (roleId: string, permissionCode: string) => {
    if (!selectedRole) return;
    const currentSet = rolePermissions[roleId] || new Set();
    const hasPerm = currentSet.has(permissionCode);

    const newSet = new Set(currentSet);
    if (hasPerm) newSet.delete(permissionCode);
    else newSet.add(permissionCode);

    setRolePermissions({ ...rolePermissions, [roleId]: newSet });

    try {
      if (hasPerm) {
        await api.delete(`/role-permissions/${roleId}/${permissionCode}`);
      } else {
        await api.post('/role-permissions', { roleId, permissionCode });
      }
    } catch (e) {
      setRolePermissions({ ...rolePermissions, [roleId]: currentSet });
      console.error(e);
    }
  };

  const selectedRoleData = roles.find(r => r.id === selectedRole);
  const selectedPerms = rolePermissions[selectedRole || ''] || new Set();

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Roles & Permissions</h1>
        <p className="text-gray-600">Manage roles and their permission assignments</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        <Card className="lg:col-span-1">
          <CardHeader>
            <h3 className="font-semibold">Roles</h3>
          </CardHeader>
          <CardContent className="p-0">
            <div className="divide-y divide-gray-200">
              {isLoading ? (
                <div className="flex items-center justify-center py-8"><div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600" /></div>
              ) : (
                roles.map((role) => (
                  <button
                    key={role.id}
                    onClick={() => setSelectedRole(role.id)}
                    className={`w-full text-left px-4 py-3 flex items-center gap-3 transition-colors ${
                      selectedRole === role.id ? 'bg-blue-50 text-blue-600' : 'hover:bg-gray-50'
                    }`}
                  >
                    <Shield className="w-4 h-4" />
                    <div>
                      <p className="text-sm font-medium">{role.name}</p>
                      <p className="text-xs text-gray-500">{role.code}</p>
                    </div>
                    {role.isSystem && (
                      <span className="ml-auto text-xs bg-gray-100 text-gray-500 px-1.5 py-0.5 rounded">System</span>
                    )}
                  </button>
                ))
              )}
            </div>
          </CardContent>
        </Card>

        <Card className="lg:col-span-3">
          <CardHeader>
            <h3 className="font-semibold">
              {selectedRoleData ? `Permissions for ${selectedRoleData.name}` : 'Select a role'}
            </h3>
            <p className="text-sm text-gray-500">
              {selectedRoleData ? `${selectedPerms.size} permissions assigned` : ''}
            </p>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="flex items-center justify-center py-8"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600" /></div>
            ) : !selectedRole ? (
              <div className="text-center py-8 text-gray-500">Select a role to view permissions</div>
            ) : (
              <div className="space-y-6">
                {Object.entries(modules).map(([modCode, mod]) => (
                  <div key={modCode}>
                    <h4 className="text-sm font-semibold text-gray-700 mb-2 uppercase tracking-wide">{mod.name}</h4>
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-2">
                      {mod.permissions.map((perm) => {
                        const action = perm.code.split(':')[1];
                        const hasPerm = selectedPerms.has(perm.code);
                        return (
                          <button
                            key={perm.id}
                            onClick={() => togglePermission(selectedRole, perm.code)}
                            className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                              hasPerm
                                ? 'bg-green-100 text-green-700 border border-green-200'
                                : 'bg-gray-50 text-gray-500 border border-gray-200 hover:bg-gray-100'
                            }`}
                          >
                            {hasPerm ? <Check className="w-4 h-4" /> : <X className="w-4 h-4" />}
                            {action}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

