import { Injectable, NotFoundException, ConflictException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateStudentDto, UpdateStudentDto, QueryStudentDto } from './dto/student.dto';
import { PaginatedDto } from '../common/dto/pagination.dto';

@Injectable()
export class StudentsService {
  constructor(private prisma: PrismaService) {}

  async findAll(query: QueryStudentDto) {
    const { page = 1, limit = 10, search, establishmentId, isActive, sortBy, sortOrder } = query;
    const skip = (page - 1) * limit;

    const where: any = {};
    if (establishmentId) where.establishmentId = establishmentId;
    if (isActive !== undefined) where.isActive = isActive;
    if (search) {
      where.OR = [
        { firstName: { contains: search, mode: 'insensitive' } },
        { lastName: { contains: search, mode: 'insensitive' } },
        { registrationNumber: { contains: search, mode: 'insensitive' } },
      ];
    }

    const orderBy: any = sortBy ? { [sortBy]: sortOrder || 'asc' } : { createdAt: 'desc' };

    const [data, total] = await Promise.all([
      this.prisma.student.findMany({
        where, skip, take: limit, orderBy,
        include: {
          classAssignments: {
            include: { class: { select: { id: true, name: true } } },
            take: 1,
          },
        },
      }),
      this.prisma.student.count({ where }),
    ]);

    return new PaginatedDto(data, total, page, limit);
  }

  async findOne(id: string) {
    const student = await this.prisma.student.findUnique({
      where: { id },
      include: {
        classAssignments: {
          include: {
            class: { include: { classLevel: true } },
            academicYear: { select: { id: true, name: true } },
          },
        },
        parents: {
          include: { parent: { select: { id: true, firstName: true, lastName: true, phone: true } } },
        },
        notes: { take: 5 },
        payments: { take: 5 },
      },
    });
    if (!student) throw new NotFoundException(`Student with ID ${id} not found`);
    return student;
  }

  async create(dto: CreateStudentDto) {
    const existing = await this.prisma.student.findUnique({
      where: { registrationNumber: dto.registrationNumber },
    });
    if (existing) throw new ConflictException('Registration number already exists');

    return this.prisma.student.create({
      data: {
        establishmentId: dto.establishmentId,
        firstName: dto.firstName,
        lastName: dto.lastName,
        dateOfBirth: dto.dateOfBirth ? new Date(dto.dateOfBirth) : null,
        gender: dto.gender as any,
        phone: dto.phone,
        address: dto.address,
        photo: dto.photo,
        registrationNumber: dto.registrationNumber,
        userId: dto.userId,
      },
    });
  }

  async update(id: string, dto: UpdateStudentDto) {
    const student = await this.prisma.student.findUnique({ where: { id } });
    if (!student) throw new NotFoundException(`Student with ID ${id} not found`);

    return this.prisma.student.update({
      where: { id },
      data: {
        firstName: dto.firstName,
        lastName: dto.lastName,
        dateOfBirth: dto.dateOfBirth ? new Date(dto.dateOfBirth) : undefined,
        gender: dto.gender as any,
        phone: dto.phone,
        address: dto.address,
        photo: dto.photo,
        isActive: dto.isActive,
      },
    });
  }

  async remove(id: string) {
    const student = await this.prisma.student.findUnique({ where: { id } });
    if (!student) throw new NotFoundException(`Student with ID ${id} not found`);
    await this.prisma.student.update({ where: { id }, data: { isActive: false } });
    return { message: 'Student deactivated successfully' };
  }
}

