'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Modal } from '@/components/ui/modal';
import api from '@/lib/api';

interface ClassFormProps {
  isOpen: boolean;
  onClose: () => void;
  classId?: string | null;
  onSuccess: () => void;
}

interface ClassData {
  name: string;
  code: string;
  classLevelId: string;
  academicYearId: string;
  maxStudents: number;
  description: string;
}

export function ClassForm({ isOpen, onClose, classId, onSuccess }: ClassFormProps) {
  const [formData, setFormData] = useState<ClassData>({
    name: '',
    code: '',
    classLevelId: '',
    academicYearId: '',
    maxStudents: 40,
    description: '',
  });
  const [classLevels, setClassLevels] = useState<{ id: string; name: string }[]>([]);
  const [academicYears, setAcademicYears] = useState<{ id: string; name: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (isOpen) {
      fetchClassLevels();
      fetchAcademicYears();
      if (classId) {
        fetchClass();
      } else {
        resetForm();
      }
    }
  }, [isOpen, classId]);

  const fetchClassLevels = async () => {
    try {
      const response = await api.get('/class-levels?limit=100');
      setClassLevels(response.data.data || []);
    } catch (err) {
      console.error('Failed to fetch class levels:', err);
    }
  };

  const fetchAcademicYears = async () => {
    try {
      const response = await api.get('/academic-years?limit=100');
      setAcademicYears(response.data.data || []);
    } catch (err) {
      console.error('Failed to fetch academic years:', err);
    }
  };

  const fetchClass = async () => {
    if (!classId) return;
    try {
      const response = await api.get(`/classes/${classId}`);
      const cls = response.data;
      setFormData({
        name: cls.name || '',
        code: cls.code || '',
        classLevelId: cls.classLevelId || '',
        academicYearId: cls.academicYearId || '',
        maxStudents: cls.maxStudents || 40,
        description: cls.description || '',
      });
    } catch (err) {
      console.error('Failed to fetch class:', err);
    }
  };

  const resetForm = () => {
    setFormData({
      name: '',
      code: '',
      classLevelId: '',
      academicYearId: '',
      maxStudents: 40,
      description: '',
    });
    setError('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      if (classId) {
        await api.patch(`/classes/${classId}`, formData);
      } else {
        await api.post('/classes', formData);
      }
      onSuccess();
      onClose();
    } catch (err: any) {
      setError(err.response?.data?.message || 'An error occurred');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title={classId ? 'Edit Class' : 'Add Class'}
      size="lg"
    >
      <form onSubmit={handleSubmit} className="space-y-4">
        {error && (
          <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg">
            {error}
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          <Input
            label="Class Name"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            required
          />
          <Input
            label="Class Code"
            value={formData.code}
            onChange={(e) => setFormData({ ...formData, code: e.target.value })}
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <Select
            label="Class Level"
            value={formData.classLevelId}
            onChange={(e) => setFormData({ ...formData, classLevelId: e.target.value })}
            options={[
              { value: '', label: 'Select a level' },
              ...classLevels.map((l) => ({ value: l.id, label: l.name })),
            ]}
          />
          <Select
            label="Academic Year"
            value={formData.academicYearId}
            onChange={(e) => setFormData({ ...formData, academicYearId: e.target.value })}
            options={[
              { value: '', label: 'Select a year' },
              ...academicYears.map((y) => ({ value: y.id, label: y.name })),
            ]}
          />
        </div>

        <Input
          label="Max Students"
          type="number"
          value={formData.maxStudents}
          onChange={(e) => setFormData({ ...formData, maxStudents: parseInt(e.target.value) || 40 })}
        />

        <Textarea
          label="Description"
          value={formData.description}
          onChange={(e) => setFormData({ ...formData, description: e.target.value })}
          rows={3}
        />

        <div className="flex justify-end gap-3 pt-4">
          <Button type="button" variant="secondary" onClick={onClose}>
            Cancel
          </Button>
          <Button type="submit" isLoading={isLoading}>
            {classId ? 'Update' : 'Create'}
          </Button>
        </div>
      </form>
    </Modal>
  );
}

