'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select } from '@/components/ui/select';
import { Modal } from '@/components/ui/modal';
import api from '@/lib/api';
import { useAuthStore } from '@/store/auth-store';

interface ExamFormProps {
  isOpen: boolean;
  onClose: () => void;
  examId?: string | null;
  onSuccess: () => void;
}

interface ExamData {
  title: string;
  description: string;
  type: string;
  classId: string;
  periodId: string;
  matiereId: string;
  academicYearId: string;
  maxScore: number;
  duration: string;
  startTime: string;
  endTime: string;
}

export function ExamForm({ isOpen, onClose, examId, onSuccess }: ExamFormProps) {
  const { user } = useAuthStore();
  const [formData, setFormData] = useState<ExamData>({
    title: '',
    description: '',
    type: 'QUIZ',
    classId: '',
    periodId: '',
    matiereId: '',
    academicYearId: '',
    maxScore: 20,
    duration: '',
    startTime: '',
    endTime: '',
  });
  const [classes, setClasses] = useState<{ id: string; name: string }[]>([]);
  const [periods, setPeriods] = useState<{ id: string; name: string }[]>([]);
  const [matieres, setMatieres] = useState<{ id: string; name: string }[]>([]);
  const [academicYears, setAcademicYears] = useState<{ id: string; name: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (isOpen) {
      fetchDropdowns();
      if (examId) {
        fetchExam();
      } else {
        resetForm();
      }
    }
  }, [isOpen, examId]);

  const fetchDropdowns = async () => {
    try {
      const [classesRes, periodsRes, matieresRes, yearsRes] = await Promise.all([
        api.get('/classes?limit=100'),
        api.get('/academic-periods?limit=100'),
        api.get('/matieres?limit=100'),
        api.get('/academic-years?limit=100'),
      ]);
      setClasses(classesRes.data.data || []);
      setPeriods(periodsRes.data.data || []);
      setMatieres(matieresRes.data.data || []);
      setAcademicYears(yearsRes.data.data || []);
    } catch (err) {
      console.error('Failed to fetch dropdowns:', err);
    }
  };

  const fetchExam = async () => {
    if (!examId) return;
    try {
      const response = await api.get(`/exams/${examId}`);
      const exam = response.data;
      setFormData({
        title: exam.title || '',
        description: exam.description || '',
        type: exam.type || 'QUIZ',
        classId: exam.classId || '',
        periodId: exam.periodId || '',
        matiereId: exam.matiereId || '',
        academicYearId: exam.academicYearId || '',
        maxScore: exam.maxScore || 20,
        duration: exam.duration?.toString() || '',
        startTime: exam.startTime ? new Date(exam.startTime).toISOString().slice(0, 16) : '',
        endTime: exam.endTime ? new Date(exam.endTime).toISOString().slice(0, 16) : '',
      });
    } catch (err) {
      console.error('Failed to fetch exam:', err);
    }
  };

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      type: 'QUIZ',
      classId: '',
      periodId: '',
      matiereId: '',
      academicYearId: '',
      maxScore: 20,
      duration: '',
      startTime: '',
      endTime: '',
    });
    setError('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      const payload = {
        ...formData,
        maxScore: Number(formData.maxScore),
        duration: formData.duration ? Number(formData.duration) : undefined,
        establishmentId: user?.establishmentId,
      };
      if (examId) {
