### 2. Fix `src/components/providers/i18n-provider.tsx`
Read it first. The issue is that before mounting, `t()` returns raw keys. Fix by:
- Import the translation files at the top
- Before mounting, use the default locale's translations instead of `(k) => k`
- Show a loading skeleton or null during SSR to prevent flash

```tsx
// Before mounting, use French translations as default
if (!mounted) {
  const defaultMessages = messages['fr'] || {};
  const defaultT = (key: string) => {
    const keys = key.split('.');
    let value: any = defaultMessages;
    for (const k of keys) {
      value = value?.[k];
    }
    return value || key;
  };
  return (
    <I18nContext.Provider value={{ locale: 'fr', setLocale, t: defaultT }}>
      {children}
    </I18nContext.Provider>
  );
}
```

### 3. Fix `src/app/layout.tsx`
Read it first. The root layout is a Server Component and can't use `useTranslation()`. Instead:
- Create a client component wrapper `src/components/locale-sync.tsx` that sets `document.documentElement.lang` and `document.documentElement.dir` dynamically via `useEffect` when locale changes
- Import and render it inside `<Providers>` in the root layout
- Keep the layout as a server component

Create `src/components/locale-sync.tsx`:
```tsx
'use client';

import { useEffect } from 'react';
import { useTranslation } from '@/components/providers/i18n-provider';

export function LocaleSync() {
  const { locale } = useTranslation();

  useEffect(() => {
    document.documentElement.lang = locale;
    document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
  }, [locale]);

  return null;
}
```

Then update `src/app/layout.tsx` to render `<LocaleSync />` inside `<Providers>`:
```tsx
import { LocaleSync } from '@/components/locale-sync';
// In the JSX:
<Providers>
  <LocaleSync />
  {children}
</Providers>
```

