'use client';

import { useTheme } from 'next-themes';
import { Moon, Sun, Monitor } from 'lucide-react';
import { useEffect, useState } from 'react';
import { useTranslation } from '@/components/providers/i18n-provider';

export function ThemeToggle() {
  const { theme, setTheme } = useTheme();
  const { t } = useTranslation();
  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);

  if (!mounted) {
    return (
      <button className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800">
        <Sun className="w-5 h-5 text-gray-500" />
      </button>
    );
  }

  return (
    <div className="flex items-center gap-1 bg-gray-100 dark:bg-gray-800 rounded-lg p-1">
      <button
        onClick={() => setTheme('light')}
        className={`p-1.5 rounded-md transition-colors ${
          theme === 'light' ? 'bg-white dark:bg-gray-700 shadow-sm text-yellow-600' : 'text-gray-500 hover:text-gray-700'
        }`}
        title={t('settings.lightMode')}
      >
        <Sun className="w-4 h-4" />
      </button>
      <button
        onClick={() => setTheme('dark')}
        className={`p-1.5 rounded-md transition-colors ${
          theme === 'dark' ? 'bg-white dark:bg-gray-700 shadow-sm text-blue-500' : 'text-gray-500 hover:text-gray-700'
        }`}
        title={t('settings.darkMode')}
      >
        <Moon className="w-4 h-4" />
      </button>
      <button
        onClick={() => setTheme('system')}
        className={`p-1.5 rounded-md transition-colors ${
          theme === 'system' ? 'bg-white dark:bg-gray-700 shadow-sm text-purple-500' : 'text-gray-500 hover:text-gray-700'
        }`}
        title={t('settings.systemDefault')}
      >
        <Monitor className="w-4 h-4" />
      </button>
    </div>
  );
}

