  '/schedule': 'pages.scheduleTitle',
  '/attendance': 'pages.attendanceTitle',
  '/holidays': 'pages.holidaysTitle',
  '/exams': 'pages.examsTitle',
  '/payments': 'pages.paymentsTitle',
  '/reports': 'pages.reportsTitle',
  '/rooms': 'pages.roomsTitle',
  '/settings': 'pages.settingsTitle',
  '/admin/plans': 'pages.plansTitle',
  '/admin/tenants': 'pages.tenantsTitle',
  '/admin/subscriptions': 'pages.subscriptionsTitle',
  '/admin/permissions': 'pages.permissionsTitle',
  '/admin/modules': 'pages.modulesTitle',
};

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const { user, isLoading, isAuthenticated, loadUser, logout } = useAuthStore();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const { t } = useTranslation();

  useEffect(() => {
    loadUser();
  }, [loadUser]);

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      router.push('/login');
    }
    if (!isLoading && isAuthenticated && pathname.startsWith('/admin') && user && !user.isRoot) {
      router.push('/dashboard');
    }
  }, [isLoading, isAuthenticated, pathname, user, router]);

  const handleLogout = () => {
    logout();
    router.push('/login');
  };

  const titleKey = routeTitles[pathname] || 'pages.dashboardTitle';

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex">
        {/* Sidebar skeleton */}
        <div className="hidden lg:flex lg:w-64 bg-white dark:bg-gray-900 flex-col gap-3 p-4">
          <div className="h-10 bg-white/10 rounded-xl animate-pulse" />
          <div className="space-y-2 mt-4">
            {[...Array(8)].map((_, i) => (
              <div key={i} className="h-10 bg-white/10 rounded-xl animate-pulse" style={{ animationDelay: `${i * 100}ms` }} />
            ))}
          </div>
          <div className="mt-auto space-y-2">
            <div className="h-10 bg-white/10 rounded-xl animate-pulse" />
          </div>
        </div>
        {/* Main skeleton */}
        <div className="flex-1 flex flex-col">
          <div className="h-16 bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700 animate-pulse" />
          <div className="flex-1 p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="h-32 bg-gray-200 dark:bg-gray-800 rounded-2xl animate-pulse" />
              ))}
            </div>
            <div className="grid lg:grid-cols-2 gap-6">
              <div className="h-64 bg-gray-200 dark:bg-gray-800 rounded-2xl animate-pulse" />
              <div className="h-64 bg-gray-200 dark:bg-gray-800 rounded-2xl animate-pulse" />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!isAuthenticated || !user) {
    return null;
  }

  return (
    <ToastProvider>
      <ErrorBoundary>
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex transition-colors duration-200">
          <Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />
          <div className="flex-1 flex flex-col min-w-0">
            <Header onMenuClick={() => setSidebarOpen(true)} title={t(titleKey)} />
            <main className="flex-1 p-6 overflow-y-auto">{children}</main>
          </div>
        </div>
      </ErrorBoundary>
    </ToastProvider>
  );
}

