Build a complete RBAC permission system for the frontend at E:\ReFactory\BSofts-School\frontend.

**Step 1: Create permissions store** at `src/store/permissions-store.ts`:
```tsx
import { create } from 'zustand';
import api from '@/lib/api';

interface PermissionsState {
  permissions: string[];
  isLoading: boolean;
  fetchPermissions: () => Promise<void>;
  hasPermission: (permission: string) => boolean;
  hasAnyPermission: (permissions: string[]) => boolean;
}

export const usePermissionsStore = create<PermissionsState>((set, get) => ({
  permissions: [],
  isLoading: false,
  fetchPermissions: async () => {
    set({ isLoading: true });
    try {
      // Fetch user's role assignments and extract permissions
      const userRes = await api.get('/auth/profile');
      const user = userRes.data;
      if (user.isRoot) {
        // Root has all permissions
        set({ permissions: ['*'], isLoading: false });
        return;
      }
      // Get the user's roles and their permissions
      const roles = user.userRoles || [];
      const permSet = new Set<string>();
      for (const ur of roles) {
        const roleRes = await api.get(`/role-permissions/role/${ur.roleId}`);
        const rolePerms = roleRes.data || [];
        for (const rp of rolePerms) {
          if (rp.permission) {
            permSet.add(`${rp.permission.moduleCode}:${rp.permission.action}`);
          }
        }
      }
      set({ permissions: Array.from(permSet), isLoading: false });
    } catch {
      set({ permissions: [], isLoading: false });
    }
  },
  hasPermission: (permission: string) => {
    const { permissions } = get();
    if (permissions.includes('*')) return true;
    return permissions.includes(permission);
  },
  hasAnyPermission: (permissions: string[]) => {
    const { permissions: userPerms } = get();
    if (userPerms.includes('*')) return true;
    return permissions.some(p => userPerms.includes(p));
  },
}));
```

