  cancelLabel?: string;
  children: React.ReactNode;
}

export function FormModal({ isOpen, onClose, title, size = 'xl', isLoading, error, onSubmit, submitLabel, cancelLabel = 'Cancel', children }: FormModalProps) {
  return (
    <Modal isOpen={isOpen} onClose={onClose} title={title} size={size}>
      <form onSubmit={onSubmit}>
        {error && (
          <div className="p-3 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 text-sm rounded-xl mb-4">
            {error}
          </div>
        )}
        {children}
        <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-gray-200 dark:border-gray-700">
          <Button type="button" variant="secondary" onClick={onClose}>{cancelLabel}</Button>
          <Button type="submit" isLoading={isLoading}>{submitLabel}</Button>
        </div>
      </form>
    </Modal>
  );
}

'use client';

interface FormSectionProps {
  title: string;
  children: React.ReactNode;
}

export function FormSection({ title, children }: FormSectionProps) {
  return (
    <div className="border border-gray-200 dark:border-gray-700 rounded-xl p-4 mb-4">
      <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">{title}</h4>
