  children: React.ReactNode;
}
```

### Custom Hooks Pattern
```tsx
// useFormState - manages form state
function useFormState<T>(defaultValues: T) {
  const [formData, setFormData] = useState<T>(defaultValues);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const setField = (field: keyof T, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const resetForm = () => {
    setFormData(defaultValues);
    setError('');
    setIsLoading(false);
  };

  return { formData, setField, resetForm, isLoading, setIsLoading, error, setError };
}

// usePagination - generic pagination
function usePagination<T>({ items, itemsPerPage = 10 }) {
  const [currentPage, setCurrentPage] = useState(1);
  const totalPages = Math.ceil(items.length / itemsPerPage);
  const paginatedItems = items.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );
  return { paginatedItems, currentPage, totalPages, goToPage: setCurrentPage };
}
```

### Permission-Based Rendering
```tsx
// Can component
<Can permission="students:create">
  <Button>Add Student</Button>
</Can>

// useCan hook
const canDelete = useCan('students:delete');
```

## Performance Rules
- Use `React.memo` only when profiling proves re-renders are expensive
- Use `useMemo` for expensive computations, not every value
- Use `useCallback` for functions passed to child components
- Avoid creating new objects/arrays in render
- Use Zustand for global state (not Context for frequent updates)

