'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { clsx } from 'clsx';
import {
  LayoutDashboard,
  Users,
  GraduationCap,
  BookOpen,
  ClipboardCheck,
  FileText,
  CreditCard,
  Settings,
  LogOut,
  ChevronLeft,
  School,
  BarChart3,
  Crown,
  CreditCard as PlanIcon,
  UserCheck,
  Shield,
  Building2,
  Home,
  Calendar,
  Layers,
} from 'lucide-react';
import { useAuthStore } from '@/store/auth-store';
import { usePermissionsStore } from '@/store/permissions-store';
import { useTranslation } from '@/components/providers/i18n-provider';

interface NavigationItem {
  name: string;
  href: string;
  icon: any;
  key: string;
  permission?: string;
}

const navigation: NavigationItem[] = [
  { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard, key: 'nav.dashboard' },
  { name: 'Students', href: '/students', icon: GraduationCap, key: 'nav.students', permission: 'students:list' },
  { name: 'Teachers', href: '/teachers', icon: Users, key: 'nav.teachers', permission: 'teachers:list' },
  { name: 'Parents', href: '/parents', icon: Users, key: 'nav.parents', permission: 'parents:list' },
  { name: 'Employees', href: '/employees', icon: Users, key: 'nav.employees', permission: 'employees:list' },
  { name: 'Classes', href: '/classes', icon: BookOpen, key: 'nav.classes', permission: 'classes:list' },
  { name: 'Attendance', href: '/attendance', icon: ClipboardCheck, key: 'nav.attendance', permission: 'attendance:list' },
  { name: 'Schedule', href: '/schedule', icon: Calendar, key: 'nav.schedule', permission: 'calendar:list' },
  { name: 'Holidays', href: '/holidays', icon: Calendar, key: 'nav.holidays', permission: 'calendar:list' },
  { name: 'Exams', href: '/exams', icon: FileText, key: 'nav.exams', permission: 'exams:list' },
  { name: 'Payments', href: '/payments', icon: CreditCard, key: 'nav.payments', permission: 'payments:list' },
  { name: 'Reports', href: '/reports', icon: BarChart3, key: 'nav.reports', permission: 'reports:list' },
  { name: 'Rooms', href: '/rooms', icon: Home, key: 'nav.rooms', permission: 'rooms:list' },
  { name: 'Settings', href: '/settings', icon: Settings, key: 'nav.settings', permission: 'settings:list' },
];

const rootNavigation: NavigationItem[] = [
  { name: 'Plans', href: '/admin/plans', icon: PlanIcon, key: 'nav.plans' },
  { name: 'Tenants', href: '/admin/tenants', icon: Building2, key: 'nav.tenants' },
  { name: 'Subscriptions', href: '/admin/subscriptions', icon: UserCheck, key: 'nav.subscriptions' },
  { name: 'Roles & Permissions', href: '/admin/permissions', icon: Shield, key: 'nav.rolesPermissions' },
  { name: 'Modules', href: '/admin/modules', icon: Layers, key: 'pages.modulesTitle' },
];

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout?: () => void;
}

export function Sidebar({ isOpen, onClose, onLogout }: SidebarProps) {
  const pathname = usePathname();
  const { user } = useAuthStore();
  const { hasPermission } = usePermissionsStore();
  const { t } = useTranslation();

  const filteredNavigation = navigation.filter(item => {
    if (!item.permission) return true;
    return hasPermission(item.permission);
  });

  return (
    <>
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/50 lg:hidden z-20"
          onClick={onClose}
        />
      )}

      <aside
        className={clsx(
          'fixed lg:static inset-y-0 left-0 z-30 w-64 bg-white dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700 transform transition-transform duration-200 ease-in-out',
          isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        )}
      >
        <div className="flex flex-col h-full">
          <div className="flex items-center justify-between h-16 px-4 border-b border-gray-200 dark:border-gray-700">
            <Link href="/dashboard" className="flex items-center gap-2">
              <School className="w-8 h-8 text-blue-600" />
              <span className="font-bold text-xl text-gray-900 dark:text-gray-100">BSofts</span>
            </Link>
            <button
              onClick={onClose}
              className="lg:hidden p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            >
              <ChevronLeft className="w-5 h-5 text-gray-600 dark:text-gray-400" />
            </button>
          </div>

          <nav className="flex-1 px-3 py-4 pb-4 space-y-1 overflow-y-auto">
            {filteredNavigation.map((item) => {
              const isActive = pathname === item.href || pathname.startsWith(item.href + '/');
              return (
                <Link
                  key={item.key}
                  href={item.href}
                  className={clsx(
                    'flex items-center gap-3 px-3 py-2 rounded-xl text-sm font-medium transition-colors',
                    isActive
                      ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                      : 'text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800'
                  )}
                  onClick={onClose}
                >
                  <item.icon className="w-5 h-5" />
                  {t(item.key)}
                </Link>
              );
            })}
            {user?.isRoot && (
              <>
                <div className="pt-4 pb-2">
                    <div className="flex items-center gap-2 px-3 text-xs font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider">
                    <Crown className="w-4 h-4" />
                    {t('nav.rootAdmin')}
                  </div>
                </div>
                {rootNavigation.map((item) => {
                  const isActive = pathname === item.href || pathname.startsWith(item.href + '/');
                  return (
                    <Link
                      key={item.key}
                      href={item.href}
                      className={clsx(
                        'flex items-center gap-3 px-3 py-2 rounded-xl text-sm font-medium transition-colors',
                        isActive
                          ? 'bg-purple-50 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400'
                          : 'text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800'
                      )}
                      onClick={onClose}
                    >
                      <item.icon className="w-5 h-5" />
                      {t(item.key)}
                    </Link>
                  );
                })}
              </>
            )}
          </nav>

          <div className="p-4 border-t border-gray-200 dark:border-gray-700">
            <div className="flex items-center gap-3 mb-3">
              <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center">
                <span className="text-blue-600 dark:text-blue-400 font-medium">
                  {user?.firstName?.[0]}{user?.lastName?.[0]}
                </span>
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
                  {user?.firstName} {user?.lastName}
                </p>
                <p className="text-xs text-gray-500 dark:text-gray-400 truncate">{user?.email}</p>
              </div>
            </div>
            <button
              onClick={() => { onLogout?.(); onClose(); }}
              className="w-full flex items-center gap-3 px-3 py-2 rounded-xl text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            >
              <LogOut className="w-5 h-5" />
              {t('nav.logout')}
            </button>
          </div>
        </div>
      </aside>
    </>
  );
}

