'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { clsx } from 'clsx';
import {
  LayoutDashboard,
  Users,
  GraduationCap,
  BookOpen,
  ClipboardCheck,
  FileText,
  CreditCard,
  Settings,
  LogOut,
  ChevronLeft,
  School,
  BarChart3,
  Crown,
  CreditCard as PlanIcon,
  UserCheck,
  Shield,
  Building2,
  Home,
  Calendar,
  Layers,
} from 'lucide-react';
import { useAuthStore } from '@/store/auth-store';
import { usePermissionsStore } from '@/store/permissions-store';
import { useTranslation } from '@/components/providers/i18n-provider';

interface NavigationItem {
  name: string;
  href: string;
  icon: typeof LayoutDashboard;
  key: string;
  permission?: string;
}

const navigation: NavigationItem[] = [
  { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard, key: 'nav.dashboard' },
  { name: 'Students', href: '/students', icon: GraduationCap, key: 'nav.students', permission: 'students:list' },
  { name: 'Teachers', href: '/teachers', icon: Users, key: 'nav.teachers', permission: 'teachers:list' },
  { name: 'Parents', href: '/parents', icon: Users, key: 'nav.parents', permission: 'parents:list' },
  { name: 'Employees', href: '/employees', icon: Users, key: 'nav.employees', permission: 'employees:list' },
  { name: 'Classes', href: '/classes', icon: BookOpen, key: 'nav.classes', permission: 'classes:list' },
  { name: 'Attendance', href: '/attendance', icon: ClipboardCheck, key: 'nav.attendance', permission: 'attendance:list' },
  { name: 'Schedule', href: '/schedule', icon: Calendar, key: 'nav.schedule', permission: 'calendar:list' },
  { name: 'Holidays', href: '/holidays', icon: Calendar, key: 'nav.holidays', permission: 'calendar:list' },
  { name: 'Exams', href: '/exams', icon: FileText, key: 'nav.exams', permission: 'exams:list' },
  { name: 'Payments', href: '/payments', icon: CreditCard, key: 'nav.payments', permission: 'payments:list' },
  { name: 'Reports', href: '/reports', icon: BarChart3, key: 'nav.reports', permission: 'reports:list' },
  { name: 'Rooms', href: '/rooms', icon: Home, key: 'nav.rooms', permission: 'rooms:list' },
  { name: 'Settings', href: '/settings', icon: Settings, key: 'nav.settings', permission: 'settings:list' },
];

const rootNavigation: NavigationItem[] = [
  { name: 'Plans', href: '/admin/plans', icon: PlanIcon, key: 'nav.plans' },
  { name: 'Tenants', href: '/admin/tenants', icon: Building2, key: 'nav.tenants' },
  { name: 'Subscriptions', href: '/admin/subscriptions', icon: UserCheck, key: 'nav.subscriptions' },
  { name: 'Roles & Permissions', href: '/admin/permissions', icon: Shield, key: 'nav.rolesPermissions' },
  { name: 'Modules', href: '/admin/modules', icon: Layers, key: 'pages.modulesTitle' },
];

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout?: () => void;
}

export function Sidebar({ isOpen, onClose, onLogout }: SidebarProps) {
  const pathname = usePathname();
  const { user } = useAuthStore();
  const { hasPermission } = usePermissionsStore();
  const { t } = useTranslation();

  const filteredNavigation = navigation.filter(item => {
    if (!item.permission) return true;
    return hasPermission(item.permission);
  });

  return (
    <>
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/50 backdrop-blur-sm lg:hidden z-20"
          onClick={onClose}
        />
      )}

      <aside
        className={clsx(
          'fixed lg:static inset-y-0 left-0 z-30 w-60 bg-sidebar-bg border-r border-sidebar-border flex flex-col transform transition-transform duration-fast ease-default',
          isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        )}
      >
        <div className="flex items-center justify-between h-14 px-5 border-b border-sidebar-border">
          <Link href="/dashboard" className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-brand flex items-center justify-center">
              <School className="w-4.5 h-4.5 text-white" />
            </div>
            <span className="font-semibold text-sm text-text-primary tracking-tight">BSofts School</span>
          </Link>
          <button
            onClick={onClose}
            className="lg:hidden p-1.5 rounded-lg hover:bg-sidebar-hover transition-colors duration-fast"
            aria-label="Close sidebar"
          >
            <ChevronLeft className="w-4 h-4 text-text-tertiary" />
          </button>
        </div>

        <nav className="flex-1 px-3 py-4 space-y-0.5 overflow-y-auto" aria-label="Main navigation">
          <p className="px-3 py-2 text-[11px] font-medium uppercase tracking-widest text-text-tertiary">Main</p>
          {filteredNavigation.map((item) => {
            const isActive = pathname === item.href || pathname.startsWith(item.href + '/');
            return (
              <Link
                key={item.key}
                href={item.href}
                className={clsx(
                  'flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors duration-fast',
                  isActive
                    ? 'bg-sidebar-active text-brand'
                    : 'text-text-secondary hover:bg-sidebar-hover hover:text-text-primary'
                )}
                onClick={onClose}
              >
                <item.icon className="w-[18px] h-[18px]" />
                {t(item.key)}
              </Link>
            );
          })}

          {user?.isRoot && (
            <>
              <p className="px-3 py-2 mt-4 pt-4 border-t border-sidebar-border text-[11px] font-medium uppercase tracking-widest text-text-tertiary flex items-center gap-2">
                <Crown className="w-3.5 h-3.5" />
                {t('nav.rootAdmin')}
              </p>
              {rootNavigation.map((item) => {
                const isActive = pathname === item.href || pathname.startsWith(item.href + '/');
                return (
                  <Link
                    key={item.key}
                    href={item.href}
                    className={clsx(
                      'flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors duration-fast',
                      isActive
                        ? 'bg-sidebar-active text-brand'
                        : 'text-text-secondary hover:bg-sidebar-hover hover:text-text-primary'
                    )}
                    onClick={onClose}
                  >
                    <item.icon className="w-[18px] h-[18px]" />
                    {t(item.key)}
                  </Link>
                );
              })}
            </>
          )}
        </nav>

        <div className="p-3 border-t border-sidebar-border">
          <div className="flex items-center gap-3 px-3 py-2 mb-2">
            <div className="w-8 h-8 rounded-full bg-brand-muted flex items-center justify-center shrink-0">
              <span className="text-xs font-medium text-brand">
                {user?.firstName?.[0]}{user?.lastName?.[0]}
              </span>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-text-primary truncate">
                {user?.firstName} {user?.lastName}
              </p>
              <p className="text-xs text-text-tertiary truncate">{user?.email}</p>
            </div>
          </div>
          <button
            onClick={() => { onLogout?.(); onClose(); }}
            className="w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium text-text-secondary hover:bg-sidebar-hover hover:text-text-primary transition-colors duration-fast"
          >
            <LogOut className="w-[18px] h-[18px]" />
            {t('nav.logout')}
          </button>
        </div>
      </aside>
    </>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { Menu, Bell, Search, X } from 'lucide-react';
import { ThemeToggle } from '@/components/theme-toggle';
import { LanguageSelector } from '@/components/language-selector';
import { useTranslation } from '@/components/providers/i18n-provider';
import api from '@/lib/api';

interface HeaderProps {
  onMenuClick: () => void;
  title: string;
}

interface SearchResult {
  id: string;
  type: 'student' | 'teacher';
  firstName: string;
  lastName: string;
  email?: string;
}

interface Notification {
  id: string;
  title: string;
  message: string;
  isRead: boolean;
  createdAt: string;
}

export function Header({ onMenuClick, title }: HeaderProps) {
  const { t } = useTranslation();
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [searchLoading, setSearchLoading] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);

  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  const fetchNotifications = useCallback(async () => {
    try {
      const res = await api.get('/notifications', { params: { isRead: false } });
      const data = res.data.data || res.data || [];
      setNotifications(data);
      setUnreadCount(data.filter((n: Notification) => !n.isRead).length);
    } catch {
      // notifications endpoint may not exist
    }
  }, []);

  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 60000);
    return () => clearInterval(interval);
  }, [fetchNotifications]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
        setShowSearchResults(false);
      }
      if (notifRef.current && !notifRef.current.contains(e.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const debounceRef = useRef<NodeJS.Timeout | null>(null);

  const handleSearch = useCallback((query: string) => {
    setSearchQuery(query);
    if (debounceRef.current) clearTimeout(debounceRef.current);

    if (!query.trim()) {
      setSearchResults([]);
      setShowSearchResults(false);
      return;
    }

    debounceRef.current = setTimeout(async () => {
      setSearchLoading(true);
      try {
        const [studentsRes, teachersRes] = await Promise.all([
          api.get('/students', { params: { search: query, limit: 5 } }).catch(() => ({ data: { data: [] } })),
          api.get('/teachers', { params: { search: query, limit: 5 } }).catch(() => ({ data: { data: [] } })),
        ]);

        const students = (studentsRes.data.data || []).map((s: Record<string, unknown>) => ({
          id: s.id as string, type: 'student' as const, firstName: s.firstName as string, lastName: s.lastName as string, email: s.email as string,
        }));
        const teachers = (teachersRes.data.data || []).map((item: Record<string, unknown>) => ({
          id: item.id as string, type: 'teacher' as const, firstName: item.firstName as string, lastName: item.lastName as string, email: item.email as string,
        }));

        setSearchResults([...students, ...teachers]);
        setShowSearchResults(true);
      } catch {
        setSearchResults([]);
      } finally {
        setSearchLoading(false);
      }
    }, 300);
  }, []);

  const handleMarkAllRead = async () => {
    try {
      await Promise.all(
        notifications.filter(n => !n.isRead).map(n =>
          api.put(`/notifications/${n.id}/read`)
        )
      );
      fetchNotifications();
    } catch {
      // ignore
    }
  };

  return (
    <header className="sticky top-0 z-40 bg-surface/80 backdrop-blur-xl border-b border-border">
      <div className="flex items-center justify-between h-14 px-4 lg:px-6">
        <div className="flex items-center gap-3">
          <button
            onClick={onMenuClick}
            className="lg:hidden p-1.5 rounded-lg hover:bg-surface-hover transition-colors duration-fast"
            aria-label="Open menu"
          >
            <Menu className="w-5 h-5 text-text-secondary" />
          </button>
          <h1 className="text-base font-semibold text-text-primary tracking-tight truncate max-w-[calc(100vw-2rem)]" title={title}>{title}</h1>
        </div>

        <div className="flex items-center gap-2">
          <div ref={searchRef} className="relative hidden sm:block">
            <div className="flex items-center gap-2 h-9 px-3 bg-surface border border-border rounded-lg transition-colors duration-fast focus-within:border-brand focus-within:ring-2 focus-within:ring-brand/20">
              <Search className="w-4 h-4 text-text-tertiary shrink-0" />
              <input
                type="text"
                placeholder={t('header.searchPlaceholder')}
                className="bg-transparent border-none outline-none text-sm w-40 text-text-primary placeholder:text-text-tertiary"
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                onFocus={() => searchResults.length > 0 && setShowSearchResults(true)}
              />
              {searchQuery && (
                <button onClick={() => { setSearchQuery(''); setSearchResults([]); setShowSearchResults(false); }} className="p-0.5 shrink-0">
                  <X className="w-3 h-3 text-text-tertiary" />
                </button>
              )}
            </div>

            {showSearchResults && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-surface-elevated border border-border rounded-xl shadow-xl max-h-80 overflow-y-auto z-50 w-80">
                {searchLoading ? (
                  <div className="p-4 text-center text-sm text-text-tertiary">{t('common.loading')}</div>
                ) : searchResults.length === 0 ? (
                  <div className="p-4 text-center text-sm text-text-tertiary">{t('header.noResults')}</div>
                ) : (
                  <div className="py-2">
                    {searchResults.map((result) => (
                      <div key={result.id} className="px-4 py-2.5 hover:bg-surface-hover cursor-pointer flex items-center gap-3 transition-colors duration-fast">
                        <div className="w-8 h-8 rounded-full bg-brand-muted flex items-center justify-center shrink-0">
                          <span className="text-xs font-medium text-brand">
                            {result.firstName[0]}{result.lastName[0]}
                          </span>
                        </div>
                        <div className="min-w-0">
                          <p className="text-sm font-medium text-text-primary truncate">{result.firstName} {result.lastName}</p>
                          <p className="text-xs text-text-tertiary truncate">{result.type === 'student' ? t('crud.student') : t('crud.teacher')}{result.email ? ` - ${result.email}` : ''}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          <ThemeToggle />

          <LanguageSelector />

          <div ref={notifRef} className="relative">
            <button
              onClick={() => { setShowNotifications(!showNotifications); }}
              className="relative p-2 rounded-lg text-text-secondary hover:bg-surface-hover transition-colors duration-fast"
              aria-label="Notifications"
            >
              <Bell className="w-[18px] h-[18px]" />
              {unreadCount > 0 && (
                <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-destructive rounded-full ring-2 ring-surface" />
              )}
            </button>

            {showNotifications && (
              <div className="absolute right-0 top-full mt-2 w-80 max-w-[calc(100vw-2rem)] bg-surface-elevated border border-border rounded-xl shadow-xl z-50">
                <div className="flex items-center justify-between px-4 py-3 border-b border-border">
                  <h3 className="text-sm font-semibold text-text-primary">{t('header.notifications')}</h3>
                  {unreadCount > 0 && (
                    <button onClick={handleMarkAllRead} className="text-xs text-brand hover:text-brand-hover transition-colors duration-fast">
                      {t('header.markAllRead')}
                    </button>
                  )}
                </div>
                <div className="max-h-80 overflow-y-auto">
                  {notifications.length === 0 ? (
                    <div className="p-4 text-center text-sm text-text-tertiary">{t('header.noNotifications')}</div>
                  ) : (
                    notifications.map((notif) => (
                      <div key={notif.id} className={`px-4 py-3 border-b border-border-subtle hover:bg-surface-hover transition-colors duration-fast ${!notif.isRead ? 'bg-brand-subtle' : ''}`}>
                        <p className="text-sm font-medium text-text-primary">{notif.title}</p>
                        <p className="text-xs text-text-secondary mt-1">{notif.message}</p>
                        <p className="text-xs text-text-tertiary mt-1">{new Date(notif.createdAt).toLocaleString()}</p>
                      </div>
                    ))
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { useAuthStore } from '@/store/auth-store';
import { usePermissionsStore } from '@/store/permissions-store';
import { ToastProvider } from '@/components/ui/toast';
import { ErrorBoundary } from '@/components/ui/error-boundary';
import { Sidebar } from '@/components/layout/sidebar';
import { Header } from '@/components/layout/header';
import { useTranslation } from '@/components/providers/i18n-provider';

const routePermissions: Record<string, string> = {
  '/students': 'students:list',
  '/teachers': 'teachers:list',
  '/parents': 'parents:list',
  '/employees': 'employees:list',
  '/classes': 'classes:list',
  '/attendance': 'attendance:list',
  '/schedule': 'calendar:list',
  '/holidays': 'calendar:list',
  '/exams': 'exams:list',
  '/payments': 'payments:list',
  '/reports': 'reports:list',
  '/rooms': 'rooms:list',
  '/settings': 'settings:list',
};

const routeTitles: Record<string, string> = {
  '/dashboard': 'pages.dashboardTitle',
  '/students': 'pages.studentsTitle',
  '/teachers': 'pages.teachersTitle',
  '/parents': 'pages.parentsTitle',
  '/employees': 'pages.employeesTitle',
  '/classes': 'pages.classesTitle',
  '/schedule': 'pages.scheduleTitle',
  '/attendance': 'pages.attendanceTitle',
  '/holidays': 'pages.holidaysTitle',
  '/exams': 'pages.examsTitle',
  '/payments': 'pages.paymentsTitle',
  '/reports': 'pages.reportsTitle',
  '/rooms': 'pages.roomsTitle',
  '/settings': 'pages.settingsTitle',
  '/admin/plans': 'pages.plansTitle',
  '/admin/tenants': 'pages.tenantsTitle',
  '/admin/subscriptions': 'pages.subscriptionsTitle',
  '/admin/permissions': 'pages.permissionsTitle',
  '/admin/modules': 'pages.modulesTitle',
};

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const { user, isLoading, isAuthenticated, loadUser, logout } = useAuthStore();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const { t } = useTranslation();

  const { hasPermission } = usePermissionsStore();

  useEffect(() => {
    loadUser();
  }, [loadUser]);

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      router.push('/login');
    }
    if (!isLoading && isAuthenticated && pathname.startsWith('/admin') && user && !user.isRoot) {
      router.push('/dashboard');
    }
    const requiredPermission = routePermissions[pathname];
    if (requiredPermission && isAuthenticated && !hasPermission(requiredPermission)) {
      router.push('/dashboard');
    }
  }, [isLoading, isAuthenticated, pathname, user, router, hasPermission]);

  const handleLogout = () => {
    logout();
    router.push('/login');
  };

  const titleKey = routeTitles[pathname] || 'pages.dashboardTitle';

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex">
        <div className="hidden lg:flex lg:w-60 bg-sidebar-bg border-r border-sidebar-border flex-col gap-3 p-4">
          <div className="h-10 skeleton" />
          <div className="space-y-2 mt-4">
            {[...Array(8)].map((_, i) => (
              <div key={i} className="h-9 skeleton" style={{ animationDelay: `${i * 100}ms` }} />
            ))}
          </div>
        </div>
        <div className="flex-1 flex flex-col">
          <div className="h-14 bg-surface border-b border-border skeleton" />
          <div className="flex-1 p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="h-32 skeleton rounded-xl" />
              ))}
            </div>
            <div className="grid lg:grid-cols-2 gap-6">
              <div className="h-64 skeleton rounded-xl" />
              <div className="h-64 skeleton rounded-xl" />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!isAuthenticated || !user) {
    return null;
  }

  return (
    <ToastProvider>
      <ErrorBoundary>
        <div className="min-h-screen bg-background flex transition-colors duration-normal">
          <Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />
          <div className="flex-1 flex flex-col min-w-0">
            <Header onMenuClick={() => setSidebarOpen(true)} title={t(titleKey)} />
            <main className="flex-1 overflow-y-auto">
              <div className="max-w-[1400px] mx-auto px-4 lg:px-6 py-6">
                {children}
              </div>
            </main>
          </div>
        </div>
      </ErrorBoundary>
    </ToastProvider>
  );
}

'use client';

import { useTheme } from '@/components/providers/theme-provider';
import { Moon, Sun, Monitor } from 'lucide-react';
import { useEffect, useState } from 'react';
import { useTranslation } from '@/components/providers/i18n-provider';

export function ThemeToggle() {
  const { theme, setTheme } = useTheme();
  const { t } = useTranslation();
  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);

  if (!mounted) {
    return (
      <button className="p-2 rounded-lg hover:bg-surface-hover" aria-label="Toggle theme">
        <Sun className="w-[18px] h-[18px] text-text-tertiary" />
      </button>
    );
  }

  return (
    <div className="flex items-center gap-0.5 bg-surface border border-border rounded-lg p-0.5">
      <button
        onClick={() => setTheme('light')}
        className={`p-1.5 rounded-md transition-all duration-fast ${
          theme === 'light' ? 'bg-surface-elevated shadow-sm text-warning' : 'text-text-tertiary hover:text-text-secondary'
        }`}
        title={t('settings.lightMode')}
        aria-label="Light mode"
      >
        <Sun className="w-3.5 h-3.5" />
      </button>
      <button
        onClick={() => setTheme('dark')}
        className={`p-1.5 rounded-md transition-all duration-fast ${
          theme === 'dark' ? 'bg-surface-elevated shadow-sm text-info' : 'text-text-tertiary hover:text-text-secondary'
        }`}
        title={t('settings.darkMode')}
        aria-label="Dark mode"
      >
        <Moon className="w-3.5 h-3.5" />
      </button>
      <button
        onClick={() => setTheme('system')}
        className={`p-1.5 rounded-md transition-all duration-fast ${
          theme === 'system' ? 'bg-surface-elevated shadow-sm text-brand' : 'text-text-tertiary hover:text-text-secondary'
        }`}
        title={t('settings.systemDefault')}
        aria-label="System theme"
      >
        <Monitor className="w-3.5 h-3.5" />
      </button>
    </div>
  );
}

'use client';

import { useTranslation, Locale } from '@/components/providers/i18n-provider';
import { Globe } from 'lucide-react';

const languages: { code: Locale; label: string; flag: string }[] = [
  { code: 'fr', label: 'Français', flag: '🇫🇷' },
  { code: 'en', label: 'English', flag: '🇬🇧' },
  { code: 'ar', label: 'العربية', flag: '🇹🇳' },
];

export function LanguageSelector() {
  const { locale, setLocale } = useTranslation();

  return (
    <div className="flex items-center gap-1.5 h-9 px-2.5 bg-surface border border-border rounded-lg cursor-pointer hover:bg-surface-hover transition-colors duration-fast">
      <Globe className="w-3.5 h-3.5 text-text-tertiary" />
      <select
        value={locale}
        onChange={(e) => setLocale(e.target.value as Locale)}
        className="bg-transparent border-none outline-none text-sm text-text-primary cursor-pointer appearance-none pr-1"
        aria-label="Select language"
      >
        {languages.map((lang) => (
          <option key={lang.code} value={lang.code}>
            {lang.flag} {lang.label}
          </option>
        ))}
      </select>
    </div>
  );
}

