'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { School, Check } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { useAuthStore } from '@/store/auth-store';
import { useTranslation } from '@/components/providers/i18n-provider';
import api from '@/lib/api';

interface Plan {
  id: string;
  name: string;
  price: number;
  currency: string;
  interval: string;
}

export default function RegisterPage() {
  const { t } = useTranslation();
  const router = useRouter();
  const { register } = useAuthStore();
  const [step, setStep] = useState(1);
  const [plans, setPlans] = useState<Plan[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string | null>(null);
  const [plansLoading, setPlansLoading] = useState(true);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const fetchPlans = async () => {
      try {
        const response = await api.get('/landing/plans');
        const data = response.data;
        const plansList = Array.isArray(data) ? data : data.data || [];
        const activePlans = plansList.filter((p: any) => p.isActive !== false);
        if (Array.isArray(activePlans) && activePlans.length > 0) {
          setPlans(activePlans);
        }
      } catch {
      } finally {
        setPlansLoading(false);
      }
    };
    fetchPlans();
  }, []);

  useEffect(() => {
    if (!plansLoading && plans.length === 0) {
      setStep(2);
    }
  }, [plansLoading, plans]);

  const handlePlanContinue = () => {
    if (plans.length > 0 && !selectedPlanId) {
      setError(t('auth.register.selectPlanError'));
      return;
    }
    setError('');
    setStep(2);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (formData.password !== formData.confirmPassword) {
      setError(t('common.passwordsDoNotMatch'));
      return;
    }

    setIsLoading(true);

    try {
      await register({
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email,
        password: formData.password,
        ...(selectedPlanId ? { planId: selectedPlanId } : {}),
      });
      router.push('/dashboard');
    } catch (err: any) {
      setError(err.response?.data?.message || t('auth.register.error'));
    } finally {
      setIsLoading(false);
    }
  };

  const getIntervalLabel = (interval: string) => {
    switch (interval?.toLowerCase()) {
      case 'monthly':
      case 'month':
        return '/mo';
      case 'yearly':
      case 'year':
        return '/yr';
      default:
        return '';
    }
  };

  return (
    <div>
      <div className="text-center mb-8">
        <Link href="/" className="inline-flex items-center gap-2 mb-6">
          <School className="w-10 h-10 text-blue-600" />
          <span className="font-bold text-2xl text-gray-900 dark:text-gray-100">BSofts</span>
        </Link>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">{t('auth.register.title')}</h1>
        <p className="text-gray-600 dark:text-gray-400 mt-2">{t('auth.register.subtitle')}</p>
      </div>

      <div className="flex items-center justify-center gap-2 mb-8">
        <div className="flex items-center gap-2">
          <div
            className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
              step >= 1
                ? 'bg-blue-600 text-white'
                : 'bg-gray-200 dark:bg-gray-700 text-gray-500 dark:text-gray-400'
            }`}
          >
            {step > 1 ? <Check className="w-4 h-4" /> : '1'}
          </div>
          <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{t('auth.register.step1')}</span>
        </div>
        <div className="w-12 h-px bg-gray-300 dark:bg-gray-600 mx-2" />
        <div className="flex items-center gap-2">
          <div
            className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
              step >= 2
                ? 'bg-blue-600 text-white'
                : 'bg-gray-200 dark:bg-gray-700 text-gray-500 dark:text-gray-400'
            }`}
          >
            2
          </div>
          <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{t('auth.register.step2')}</span>
        </div>
      </div>

      {error && (
        <div className="p-3 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 text-sm rounded-xl mb-4">
          {error}
        </div>
      )}

      {step === 1 && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {plans.map((plan) => (
              <Card
                key={plan.id}
                className={`cursor-pointer transition-all ${
                  selectedPlanId === plan.id
                    ? 'border-2 border-blue-600 ring-2 ring-blue-600/20'
                    : 'hover:border-gray-400'
                }`}
                onClick={() => setSelectedPlanId(plan.id)}
              >
                <div className="p-6 text-center">
                  {selectedPlanId === plan.id && (
                    <div className="inline-flex items-center justify-center w-6 h-6 rounded-full bg-blue-600 text-white mb-2">
                      <Check className="w-4 h-4" />
                    </div>
                  )}
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">{plan.name}</h3>
                  <div className="mt-3">
                    <span className="text-3xl font-bold text-gray-900 dark:text-gray-100">{plan.price}</span>
                    <span className="text-sm text-gray-500 dark:text-gray-400 ml-1">{plan.currency}{getIntervalLabel(plan.interval)}</span>
                  </div>
                </div>
              </Card>
            ))}
          </div>

          <div className="flex gap-3 pt-2">
            <Button type="button" className="flex-1" onClick={handlePlanContinue} isLoading={plansLoading}>
              {t('auth.register.continue')}
            </Button>
          </div>
        </div>
      )}

      {step === 2 && (
        <>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <Input
                label={t('auth.register.firstName')}
                placeholder="John"
                value={formData.firstName}
                onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                required
              />
              <Input
                label={t('auth.register.lastName')}
                placeholder="Doe"
                value={formData.lastName}
                onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                required
              />
            </div>

            <Input
              label={t('auth.register.email')}
              type="email"
              placeholder="you@example.com"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              required
            />

            <Input
              label={t('auth.register.password')}
              type="password"
              placeholder="••••••••"
              value={formData.password}
              onChange={(e) => setFormData({ ...formData, password: e.target.value })}
              required
            />

            <Input
              label={t('auth.register.confirmPassword')}
              type="password"
              placeholder="••••••••"
              value={formData.confirmPassword}
              onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
              required
            />

            <div className="flex gap-3">
              <Button type="button" variant="secondary" onClick={() => setStep(1)}>
                {t('common.back')}
              </Button>
              <Button type="submit" className="flex-1" isLoading={isLoading}>
                {t('auth.register.submit')}
              </Button>
            </div>
          </form>
        </>
      )}

      <p className="mt-6 text-center text-sm text-gray-600 dark:text-gray-400">
        {t('auth.register.hasAccount')}{' '}
        <Link href="/login" className="text-blue-600 dark:text-blue-400 hover:underline">
          {t('auth.register.signIn')}
        </Link>
      </p>
    </div>
  );
}

