'use client';

import Link from 'next/link';
import { useState, useEffect, useCallback } from 'react';
import {
  School, Check, ArrowRight, GraduationCap, Users, BookOpen, BarChart3,
  Star, Globe, Menu, X, UserPlus, Settings, Rocket, ChevronDown, ChevronUp,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useTranslation, Locale } from '@/components/providers/i18n-provider';
import { ThemeToggle } from '@/components/theme-toggle';
import api from '@/lib/api';

const features = [
  { icon: GraduationCap, titleKey: 'landing.features.studentManagement', descKey: 'landing.features.studentDesc' },
  { icon: Users, titleKey: 'landing.features.teacherPortal', descKey: 'landing.features.teacherDesc' },
  { icon: BookOpen, titleKey: 'landing.features.classManagement', descKey: 'landing.features.classDesc' },
  { icon: BarChart3, titleKey: 'landing.features.reports', descKey: 'landing.features.reportDesc' },
];

const fallbackPlans = [
  {
    nameKey: 'landing.pricing.free',
    price: '0',
    intervalKey: 'landing.pricing.monthly',
    featureKeys: ['landing.pricing.feature1', 'landing.pricing.feature2', 'landing.pricing.feature3', 'landing.pricing.feature4'],
    popular: false,
  },
  {
    nameKey: 'landing.pricing.basic',
    price: '4,900',
    intervalKey: 'landing.pricing.monthly',
    featureKeys: ['landing.pricing.feature5', 'landing.pricing.feature6', 'landing.pricing.feature7', 'landing.pricing.feature8', 'landing.pricing.feature9'],
    popular: true,
  },
  {
    nameKey: 'landing.pricing.premium',
    price: '19,900',
    intervalKey: 'landing.pricing.monthly',
    featureKeys: ['landing.pricing.feature10', 'landing.pricing.feature11', 'landing.pricing.feature12', 'landing.pricing.feature13', 'landing.pricing.feature14', 'landing.pricing.feature15'],
    popular: false,
  },
];

const testimonials = [
  { name: 'Ahmed B.', roleKey: 'landing.testimonials.items.0.role', textKey: 'landing.testimonials.items.0.text' },
  { name: 'Fatima K.', roleKey: 'landing.testimonials.items.1.role', textKey: 'landing.testimonials.items.1.text' },
  { name: 'Youssef M.', roleKey: 'landing.testimonials.items.2.role', textKey: 'landing.testimonials.items.2.text' },
];

const howItWorks = [
  { icon: UserPlus, titleKey: 'landing.howItWorks.step1', descKey: 'landing.howItWorks.step1Desc' },
  { icon: Settings, titleKey: 'landing.howItWorks.step2', descKey: 'landing.howItWorks.step2Desc' },
  { icon: Rocket, titleKey: 'landing.howItWorks.step3', descKey: 'landing.howItWorks.step3Desc' },
];

const faqs = [
  { qKey: 'landing.faq.q1', aKey: 'landing.faq.a1' },
  { qKey: 'landing.faq.q2', aKey: 'landing.faq.a2' },
  { qKey: 'landing.faq.q3', aKey: 'landing.faq.a3' },
  { qKey: 'landing.faq.q4', aKey: 'landing.faq.a4' },
  { qKey: 'landing.faq.q5', aKey: 'landing.faq.a5' },
];

const fallbackStats = {
  students: 500,
  teachers: 50,
  exams: 1000,
  uptime: 99,
};

const locales: Locale[] = ['en', 'fr', 'ar'];
const localeLabels: Record<Locale, string> = { en: 'EN', fr: 'FR', ar: 'AR' };

function LanguageSelector({
  locale,
  setLocale,
  langMenuOpen,
  setLangMenuOpen,
  variant,
}: {
  locale: Locale;
  setLocale: (l: Locale) => void;
  langMenuOpen: boolean;
  setLangMenuOpen: (v: boolean) => void;
  variant: 'desktop' | 'mobile';
}) {
  if (variant === 'desktop') {
    return (
      <div className="relative">
        <button
          onClick={() => setLangMenuOpen(!langMenuOpen)}
          className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
        >
          <Globe className="w-4 h-4" />
          {localeLabels[locale]}
        </button>
        {langMenuOpen && (
          <div className="absolute right-0 mt-2 w-32 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-xl py-1 z-50">
            {locales.map((loc) => (
              <button
                key={loc}
                onClick={() => { setLocale(loc); setLangMenuOpen(false); }}
                className={`block w-full text-left px-4 py-2 text-sm transition-colors ${
                  locale === loc
                    ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 font-medium'
                    : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50'
                }`}
              >
                {localeLabels[loc]}
              </button>
            ))}
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="relative">
      <button
        onClick={() => setLangMenuOpen(!langMenuOpen)}
        className="p-2 rounded-lg text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800"
      >
        <Globe className="w-5 h-5" />
      </button>
      {langMenuOpen && (
        <div className="absolute right-0 mt-2 w-32 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-xl py-1 z-50">
          {locales.map((loc) => (
            <button
              key={loc}
              onClick={() => { setLocale(loc); setLangMenuOpen(false); }}
              className={`block w-full text-left px-4 py-2 text-sm transition-colors ${
                locale === loc
                  ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 font-medium'
                  : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50'
              }`}
            >
              {localeLabels[loc]}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export default function LandingPage() {
  const { t, locale, setLocale } = useTranslation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [langMenuOpen, setLangMenuOpen] = useState(false);
  const [plans, setPlans] = useState(fallbackPlans);
  const [stats, setStats] = useState(fallbackStats);
  const [openFaq, setOpenFaq] = useState<number | null>(null);

  const fetchPlans = useCallback(async () => {
    try {
      const res = await api.get('/landing/plans');
      const data = res.data;
      const activePlans = (Array.isArray(data) ? data : data.data || []).filter((p: any) => p.isActive);
      if (activePlans.length > 0) {
        setPlans(activePlans.map((p: any, i: number) => ({
          nameKey: p.name || fallbackPlans[i]?.nameKey || '',
          price: String(p.price ?? fallbackPlans[i]?.price ?? '0'),
          intervalKey: p.interval || fallbackPlans[i]?.intervalKey || 'landing.pricing.monthly',
          featureKeys: fallbackPlans[i]?.featureKeys || [],
          popular: i === 1,
        })));
      }
    } catch {
      // keep fallback plans
    }
  }, []);

  const fetchStats = useCallback(async () => {
    try {
      const res = await api.get('/landing/stats');
      const data = res.data;
      if (data && typeof data === 'object') {
        setStats({
          students: data.students ?? fallbackStats.students,
          teachers: data.teachers ?? fallbackStats.teachers,
          exams: data.exams ?? fallbackStats.exams,
          uptime: data.uptime ?? fallbackStats.uptime,
        });
      }
    } catch {
      // keep fallback stats
    }
  }, []);

  useEffect(() => {
    fetchPlans();
    fetchStats();
  }, [fetchPlans, fetchStats]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('opacity-100', 'translate-y-0');
            entry.target.classList.remove('opacity-0', 'translate-y-8');
          }
        });
      },
      { threshold: 0.1 }
    );
    document.querySelectorAll('.animate-on-scroll').forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  return (
    <div className="min-h-screen bg-white dark:bg-gray-950 transition-colors duration-200" style={{ scrollBehavior: 'smooth' }}>
      {/* Navigation */}
      <nav className="sticky top-0 z-50 bg-white/80 dark:bg-gray-950/80 backdrop-blur-xl border-b border-gray-100 dark:border-gray-800/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <Link href="/" className="flex items-center gap-2">
              <div className="p-1.5 bg-gradient-to-br from-blue-500 to-blue-600 rounded-lg shadow-lg shadow-blue-500/25">
                <School className="w-6 h-6 text-white" />
              </div>
              <span className="font-bold text-xl bg-gradient-to-r from-gray-900 to-gray-600 dark:from-white dark:to-gray-400 bg-clip-text text-transparent">
                BSofts School
              </span>
            </Link>

            {/* Desktop nav */}
            <div className="hidden md:flex items-center gap-8">
              <a href="#features" className="text-sm font-medium text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors">
                {t('nav.features')}
              </a>
              <a href="#pricing" className="text-sm font-medium text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors">
                {t('nav.pricing')}
              </a>

              <LanguageSelector
                locale={locale}
                setLocale={setLocale}
                langMenuOpen={langMenuOpen}
                setLangMenuOpen={setLangMenuOpen}
                variant="desktop"
              />

              <ThemeToggle />

              <Link href="/login">
                <Button variant="ghost" className="text-gray-700 dark:text-gray-300">{t('auth.login.submit')}</Button>
              </Link>
              <Link href="/register">
                <Button>{t('landing.hero.cta')}</Button>
              </Link>
            </div>

            {/* Mobile right controls */}
            <div className="flex md:hidden items-center gap-2">
              <LanguageSelector
                locale={locale}
                setLocale={setLocale}
                langMenuOpen={langMenuOpen}
                setLangMenuOpen={setLangMenuOpen}
                variant="mobile"
              />
              <ThemeToggle />
              <button
                onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                className="p-2 rounded-lg text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800"
              >
                {mobileMenuOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile menu dropdown */}
        {mobileMenuOpen && (
          <div className="md:hidden border-t border-gray-100 dark:border-gray-800/50 bg-white/95 dark:bg-gray-950/95 backdrop-blur-xl">
            <div className="px-4 py-4 space-y-3">
              <a
                href="#features"
                onClick={() => setMobileMenuOpen(false)}
                className="block px-4 py-2.5 rounded-lg text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
              >
                {t('nav.features')}
              </a>
              <a
                href="#pricing"
                onClick={() => setMobileMenuOpen(false)}
                className="block px-4 py-2.5 rounded-lg text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
              >
                {t('nav.pricing')}
              </a>
              <Link href="/login" onClick={() => setMobileMenuOpen(false)}>
                <Button variant="ghost" className="w-full justify-start text-gray-700 dark:text-gray-300">{t('auth.login.submit')}</Button>
              </Link>
              <Link href="/register" onClick={() => setMobileMenuOpen(false)}>
                <Button className="w-full">{t('landing.hero.cta')}</Button>
              </Link>
            </div>
          </div>
        )}
      </nav>

      {/* Hero Section */}
      <section className="relative py-20 sm:py-32 overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-br from-blue-50 via-white to-cyan-50 dark:from-gray-950 dark:via-gray-900 dark:to-gray-950" />
        <div className="absolute top-1/4 left-1/4 w-72 h-72 bg-blue-400/20 dark:bg-blue-500/10 rounded-full blur-3xl animate-pulse" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-cyan-400/15 dark:bg-cyan-500/5 rounded-full blur-3xl" style={{ animationDelay: '1s' }} />

        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center max-w-4xl mx-auto">
            <div className="inline-flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/20 rounded-full border border-blue-200 dark:border-blue-800/30 mb-8">
              <Star className="w-4 h-4 text-blue-600 dark:text-blue-400" />
              <span className="text-sm font-medium text-blue-700 dark:text-blue-300">
                {t('landing.hero.badge')}
              </span>
            </div>

            <h1 className="text-4xl sm:text-6xl lg:text-7xl font-bold text-gray-900 dark:text-white tracking-tight">
              {t('landing.hero.title')}
              <span className="bg-gradient-to-r from-blue-600 to-cyan-500 bg-clip-text text-transparent"> {t('landing.hero.highlight')}</span>
            </h1>
            <p className="mt-6 text-xl text-gray-600 dark:text-gray-400 max-w-2xl mx-auto leading-relaxed">
              {t('landing.hero.subtitle')}
            </p>
            <div className="mt-10 flex flex-col sm:flex-row items-center justify-center gap-4">
              <Link href="/register">
                <Button size="lg" className="min-w-[200px] shadow-xl shadow-blue-500/25 hover:shadow-blue-500/40 transition-all duration-300">
                  {t('landing.hero.cta')}
                  <ArrowRight className="ml-2 w-5 h-5" />
                </Button>
              </Link>
              <Link href="/login">
                <Button size="lg" variant="secondary" className="min-w-[200px]">
                  {t('auth.login.submit')}
                </Button>
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* Stats Section */}
      <section className="py-12 bg-white dark:bg-gray-950 border-y border-gray-100 dark:border-gray-800/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-8 animate-on-scroll opacity-0 translate-y-8 transition-all duration-700">
            {[
              { value: `${stats.students}+`, labelKey: 'landing.stats.students' },
              { value: `${stats.teachers}+`, labelKey: 'landing.stats.teachers' },
              { value: `${stats.exams}+`, labelKey: 'landing.stats.exams' },
              { value: `${stats.uptime}%`, labelKey: 'landing.stats.uptime' },
            ].map((stat, i) => (
              <div key={stat.labelKey} className="text-center" style={{ transitionDelay: `${i * 100}ms` }}>
                <div className="text-3xl sm:text-4xl font-bold bg-gradient-to-r from-blue-600 to-cyan-500 bg-clip-text text-transparent">
                  {stat.value}
                </div>
                <div className="mt-2 text-sm text-gray-500 dark:text-gray-400 font-medium">
                  {t(stat.labelKey)}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Features Section */}
      <section id="features" className="py-20 bg-gray-50 dark:bg-gray-900/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center max-w-3xl mx-auto mb-16 animate-on-scroll opacity-0 translate-y-8 transition-all duration-700">
            <h2 className="text-3xl sm:text-4xl font-bold text-gray-900 dark:text-white">
              {t('landing.features.title')}
            </h2>
            <p className="mt-4 text-lg text-gray-600 dark:text-gray-400">
              {t('landing.features.subtitle')}
            </p>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
            {features.map((feature, i) => (
              <div
                key={feature.titleKey}
                className="group bg-white dark:bg-gray-800/50 backdrop-blur-sm p-6 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm hover:shadow-xl hover:shadow-blue-500/5 hover:-translate-y-1 transition-all duration-300 animate-on-scroll opacity-0 translate-y-8"
                style={{ transitionDelay: `${i * 100}ms` }}
              >
                <div className="w-12 h-12 bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl flex items-center justify-center mb-4 shadow-lg shadow-blue-500/25 group-hover:scale-110 transition-transform duration-300">
                  <feature.icon className="w-6 h-6 text-white" />
                </div>
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
                  {t(feature.titleKey)}
                </h3>
                <p className="text-gray-600 dark:text-gray-400 text-sm leading-relaxed">
                  {t(feature.descKey)}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* How it Works Section */}
      <section className="py-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center max-w-3xl mx-auto mb-16 animate-on-scroll opacity-0 translate-y-8 transition-all duration-700">
            <h2 className="text-3xl sm:text-4xl font-bold text-gray-900 dark:text-white">
              {t('landing.howItWorks.title')}
            </h2>
            <p className="mt-4 text-lg text-gray-600 dark:text-gray-400">
              {t('landing.howItWorks.subtitle')}
            </p>
          </div>
          <div className="grid md:grid-cols-3 gap-8 max-w-5xl mx-auto">
            {howItWorks.map((step, i) => (
              <div
                key={step.titleKey}
                className="relative text-center animate-on-scroll opacity-0 translate-y-8"
                style={{ transitionDelay: `${i * 150}ms` }}
              >
                <div className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-br from-blue-500 to-cyan-500 rounded-2xl shadow-lg shadow-blue-500/25 mb-6">
                  <step.icon className="w-8 h-8 text-white" />
                </div>
                <div className="absolute top-8 left-1/2 -translate-x-1/2 w-full hidden md:block" aria-hidden="true">
                  {i < howItWorks.length - 1 && (
                    <div className="absolute left-[calc(50%+3rem)] top-0 w-[calc(100%-6rem)] h-px bg-gradient-to-r from-blue-300 to-cyan-300 dark:from-blue-700 dark:to-cyan-700" />
                  )}
                </div>
                <div className="text-sm font-bold text-blue-600 dark:text-blue-400 mb-2">
                  {t(`landing.howItWorks.number${i + 1}` as any)}
                </div>
                <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">
                  {t(step.titleKey)}
                </h3>
                <p className="text-gray-600 dark:text-gray-400 text-sm leading-relaxed max-w-xs mx-auto">
                  {t(step.descKey)}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Pricing Section */}
      <section id="pricing" className="py-20 bg-gray-50 dark:bg-gray-900/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center max-w-3xl mx-auto mb-16 animate-on-scroll opacity-0 translate-y-8 transition-all duration-700">
            <h2 className="text-3xl sm:text-4xl font-bold text-gray-900 dark:text-white">
              {t('landing.pricing.title')}
            </h2>
            <p className="mt-4 text-lg text-gray-600 dark:text-gray-400">
              {t('landing.pricing.subtitle')}
            </p>
          </div>
          <div className="grid md:grid-cols-3 gap-8 max-w-5xl mx-auto">
            {plans.map((plan, i) => (
              <div
                key={plan.nameKey}
                className={`relative bg-white dark:bg-gray-800/50 backdrop-blur-sm rounded-2xl shadow-sm border-2 p-8 transition-all duration-300 hover:shadow-xl animate-on-scroll opacity-0 translate-y-8 ${
                  plan.popular
                    ? 'border-blue-600 dark:border-blue-500 shadow-blue-500/10 scale-105'
                    : 'border-gray-200 dark:border-gray-700/50 hover:border-blue-300 dark:hover:border-blue-700'
                }`}
                style={{ transitionDelay: `${i * 100}ms` }}
              >
                {plan.popular && (
                  <div className="absolute -top-4 left-1/2 -translate-x-1/2">
                    <span className="bg-gradient-to-r from-blue-600 to-blue-500 text-white text-sm font-medium px-4 py-1 rounded-full shadow-lg shadow-blue-500/25">
                      {t('landing.pricing.popular')}
                    </span>
                  </div>
                )}
                <h3 className="text-xl font-bold text-gray-900 dark:text-white">{t(plan.nameKey)}</h3>
                <div className="mt-4 flex items-baseline gap-1">
                  <span className="text-4xl font-bold text-gray-900 dark:text-white">{plan.price}</span>
                  <span className="text-gray-500 dark:text-gray-400">{t(plan.intervalKey)}</span>
                </div>
                <ul className="mt-8 space-y-4">
                  {plan.featureKeys.map((fk) => (
                    <li key={fk} className="flex items-center gap-3">
                      <div className="w-5 h-5 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center flex-shrink-0">
                        <Check className="w-3 h-3 text-green-600 dark:text-green-400" />
                      </div>
                      <span className="text-gray-600 dark:text-gray-400 text-sm">{t(fk)}</span>
                    </li>
                  ))}
                </ul>
                <Link href="/register" className="block mt-8">
                  <Button
                    variant={plan.popular ? 'primary' : 'secondary'}
                    className={`w-full ${plan.popular ? 'shadow-lg shadow-blue-500/25' : ''}`}
                  >
                    {t('landing.pricing.getStarted')}
                  </Button>
                </Link>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Testimonials Section */}
      <section className="py-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center max-w-3xl mx-auto mb-16 animate-on-scroll opacity-0 translate-y-8 transition-all duration-700">
            <h2 className="text-3xl sm:text-4xl font-bold text-gray-900 dark:text-white">
              {t('landing.testimonials.title')}
            </h2>
            <p className="mt-4 text-lg text-gray-600 dark:text-gray-400">
              {t('landing.testimonials.subtitle')}
            </p>
          </div>
          <div className="grid md:grid-cols-3 gap-8">
            {testimonials.map((testimonial, i) => (
              <div
                key={testimonial.name}
                className="bg-white dark:bg-gray-800/50 backdrop-blur-sm p-6 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm hover:shadow-lg transition-all duration-300 animate-on-scroll opacity-0 translate-y-8"
                style={{ transitionDelay: `${i * 100}ms` }}
              >
                <div className="flex items-center gap-1 mb-4">
                  {[...Array(5)].map((_, i) => (
                    <Star key={i} className="w-4 h-4 text-yellow-400 fill-current" />
                  ))}
                </div>
                <p className="text-gray-600 dark:text-gray-400 text-sm leading-relaxed mb-6">
                  &ldquo;{t(testimonial.textKey)}&rdquo;
                </p>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center">
                    <span className="text-white font-semibold text-sm">{testimonial.name[0]}</span>
                  </div>
                  <div>
                    <p className="font-semibold text-gray-900 dark:text-white text-sm">{testimonial.name}</p>
                    <p className="text-xs text-gray-500 dark:text-gray-400">{t(testimonial.roleKey)}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* FAQ Section */}
      <section className="py-20 bg-gray-50 dark:bg-gray-900/50">
        <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16 animate-on-scroll opacity-0 translate-y-8 transition-all duration-700">
            <h2 className="text-3xl sm:text-4xl font-bold text-gray-900 dark:text-white">
              {t('landing.faq.title')}
            </h2>
            <p className="mt-4 text-lg text-gray-600 dark:text-gray-400">
              {t('landing.faq.subtitle')}
            </p>
          </div>
          <div className="space-y-3 animate-on-scroll opacity-0 translate-y-8 transition-all duration-700">
            {faqs.map((faq, i) => (
              <div
                key={faq.qKey}
                className="bg-white dark:bg-gray-800/50 backdrop-blur-sm rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm overflow-hidden transition-all duration-300"
                style={{ transitionDelay: `${i * 80}ms` }}
              >
                <button
                  onClick={() => setOpenFaq(openFaq === i ? null : i)}
                  className="flex items-center justify-between w-full px-6 py-5 text-left"
                >
                  <span className="font-semibold text-gray-900 dark:text-white text-sm pr-4">
