      </section>

      {/* CTA Section */}
      <section className="py-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="relative bg-gradient-to-r from-blue-600 to-cyan-500 rounded-3xl p-12 sm:p-16 text-center overflow-hidden animate-on-scroll opacity-0 translate-y-8 transition-all duration-700">
            <div className="absolute top-0 left-0 w-40 h-40 bg-white/10 rounded-full -translate-x-1/2 -translate-y-1/2 blur-2xl" />
            <div className="absolute bottom-0 right-0 w-60 h-60 bg-white/10 rounded-full translate-x-1/3 translate-y-1/3 blur-2xl" />
            <div className="relative">
              <h2 className="text-3xl sm:text-4xl font-bold text-white mb-4">
                {t('landing.cta.title')}
              </h2>
              <p className="text-blue-100 text-lg max-w-2xl mx-auto mb-8">
                {t('landing.cta.subtitle')}
              </p>
              <Link href="/register">
                <Button size="lg" variant="secondary" className="min-w-[200px] bg-white text-blue-600 hover:bg-gray-100 shadow-xl">
                  {t('landing.cta.button')}
                  <ArrowRight className="ml-2 w-5 h-5" />
                </Button>
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-gray-900 dark:bg-gray-950 text-white pt-16 pb-8 border-t border-gray-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-8 mb-12">
            {/* Product */}
            <div>
              <h4 className="text-sm font-semibold text-white mb-4 uppercase tracking-wider">
                {t('landing.footer.product')}
              </h4>
              <ul className="space-y-3">
                <li>
                  <a href="#features" className="text-gray-400 hover:text-white text-sm transition-colors">
                    {t('landing.footer.features')}
                  </a>
                </li>
                <li>
                  <a href="#pricing" className="text-gray-400 hover:text-white text-sm transition-colors">
                    {t('landing.footer.pricing')}
                  </a>
                </li>
                <li>
                  <a href="#" className="text-gray-400 hover:text-white text-sm transition-colors">
                    {t('landing.footer.about')}
                  </a>
                </li>
              </ul>
            </div>

            {/* Support */}
            <div>
              <h4 className="text-sm font-semibold text-white mb-4 uppercase tracking-wider">
                {t('landing.footer.support')}
              </h4>
              <ul className="space-y-3">
                <li>
                  <a href="#" className="text-gray-400 hover:text-white text-sm transition-colors">
                    {t('landing.footer.helpCenter')}
                  </a>
                </li>
                <li>
                  <a href="#" className="text-gray-400 hover:text-white text-sm transition-colors">
                    {t('landing.footer.contact')}
                  </a>
                </li>
                <li>
                  <a href="#" className="text-gray-400 hover:text-white text-sm transition-colors">
                    {t('landing.footer.blog')}
                  </a>
                </li>
