input.content:
'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { School } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useAuthStore } from '@/store/auth-store';
import { useTranslation } from '@/components/providers/i18n-provider';

export default function LoginPage() {
  const { t } = useTranslation();
  const router = useRouter();
  const { login } = useAuthStore();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      await login(email, password);
      router.push('/dashboard');
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : t('auth.login.error');
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="animate-fade-in">
      <div className="text-center mb-8">
        <Link href="/" className="inline-flex items-center gap-2.5 mb-6">
          <div className="w-10 h-10 rounded-xl bg-brand flex items-center justify-center">
            <School className="w-5 h-5 text-white" />
          </div>
          <span className="font-semibold text-xl text-text-primary tracking-tight">BSofts School</span>
        </Link>
        <h1 className="text-xl font-semibold text-text-primary tracking-tight">{t('auth.login.title')}</h1>
        <p className="text-sm text-text-secondary mt-1.5">{t('auth.login.subtitle')}</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {error && (
          <div className="p-3 bg-destructive/10 text-destructive text-sm rounded-lg border border-destructive/20">
            {error}
          </div>
        )}

        <Input
          label={t('auth.login.email')}
          type="email"
          placeholder="you@example.com"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />

        <Input
          label={t('auth.login.password')}
          type="password"
          placeholder="••••••••"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />

        <Button type="submit" className="w-full" isLoading={isLoading}>
          {t('auth.login.submit')}
        </Button>
      </form>

      <p className="mt-6 text-center text-sm text-text-secondary">
        {t('auth.login.noAccount')}{' '}
        <Link href="/register" className="text-brand hover:text-brand-hover font-medium transition-colors duration-fast">
          {t('auth.login.createOne')}
        </Link>
      </p>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { School, Check } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useAuthStore } from '@/store/auth-store';
import { useTranslation } from '@/components/providers/i18n-provider';
import api from '@/lib/api';

interface Plan {
  id: string;
  name: string;
  price: number;
  currency: string;
  interval: string;
}

export default function RegisterPage() {
  const { t } = useTranslation();
  const router = useRouter();
  const { register } = useAuthStore();
  const [step, setStep] = useState(1);
  const [plans, setPlans] = useState<Plan[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string | null>(null);
  const [plansLoading, setPlansLoading] = useState(true);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const fetchPlans = async () => {
      try {
        const response = await api.get('/landing/plans');
        const data = response.data;
        const plansList = Array.isArray(data) ? data : data.data || [];
        const activePlans = plansList.filter((p: { isActive?: boolean }) => p.isActive !== false);
        if (Array.isArray(activePlans) && activePlans.length > 0) {
          setPlans(activePlans);
        }
      } catch {
        // keep empty
      } finally {
        setPlansLoading(false);
      }
    };
    fetchPlans();
  }, []);

  useEffect(() => {
    if (!plansLoading && plans.length === 0) {
      setStep(2);
    }
  }, [plansLoading, plans]);

  const handlePlanContinue = () => {
    if (plans.length > 0 && !selectedPlanId) {
      setError(t('auth.register.selectPlanError'));
      return;
    }
    setError('');
    setStep(2);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (formData.password !== formData.confirmPassword) {
      setError(t('common.passwordsDoNotMatch'));
      return;
    }

    setIsLoading(true);

    try {
      await register({
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email,
        password: formData.password,
        ...(selectedPlanId ? { planId: selectedPlanId } : {}),
      });
      router.push('/dashboard');
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : t('auth.register.error');
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const getIntervalLabel = (interval: string) => {
    switch (interval?.toLowerCase()) {
      case 'monthly':
      case 'month':
        return '/mo';
      case 'yearly':
      case 'year':
        return '/yr';
      default:
        return '';
    }
  };

  return (
    <div className="animate-fade-in">
      <div className="text-center mb-8">
        <Link href="/" className="inline-flex items-center gap-2.5 mb-6">
          <div className="w-10 h-10 rounded-xl bg-brand flex items-center justify-center">
            <School className="w-5 h-5 text-white" />
          </div>
          <span className="font-semibold text-xl text-text-primary tracking-tight">BSofts School</span>
        </Link>
        <h1 className="text-xl font-semibold text-text-primary tracking-tight">{t('auth.register.title')}</h1>
        <p className="text-sm text-text-secondary mt-1.5">{t('auth.register.subtitle')}</p>
      </div>

      <div className="flex items-center justify-center gap-2 mb-8">
        <div className="flex items-center gap-2">
          <div
            className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-colors duration-fast ${
              step >= 1
                ? 'bg-brand text-white'
                : 'bg-surface text-text-tertiary border border-border'
            }`}
          >
            {step > 1 ? <Check className="w-4 h-4" /> : '1'}
          </div>
          <span className="text-sm font-medium text-text-primary">{t('auth.register.step1')}</span>
        </div>
        <div className="w-12 h-px bg-border mx-2" />
        <div className="flex items-center gap-2">
          <div
            className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-colors duration-fast ${
              step >= 2
                ? 'bg-brand text-white'
                : 'bg-surface text-text-tertiary border border-border'
            }`}
          >
            2
          </div>
          <span className="text-sm font-medium text-text-primary">{t('auth.register.step2')}</span>
        </div>
      </div>

      {error && (
        <div className="p-3 bg-destructive/10 text-destructive text-sm rounded-lg mb-4 border border-destructive/20">
          {error}
        </div>
      )}

      {step === 1 && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {plans.map((plan) => (
              <div
                key={plan.id}
                className={`cursor-pointer rounded-xl border-2 p-6 text-center transition-all duration-fast ${
                  selectedPlanId === plan.id
                    ? 'border-brand bg-brand-subtle ring-2 ring-brand/20'
                    : 'border-border bg-surface hover:border-border-strong'
                }`}
                onClick={() => setSelectedPlanId(plan.id)}
              >
                {selectedPlanId === plan.id && (
                  <div className="inline-flex items-center justify-center w-6 h-6 rounded-full bg-brand text-white mb-2">
                    <Check className="w-4 h-4" />
                  </div>
                )}
                <h3 className="text-base font-semibold text-text-primary">{plan.name}</h3>
