display.text:
'use client';

import { useEffect, useState } from 'react';
import { GraduationCap, Users, BookOpen, CreditCard, TrendingUp, ArrowUpRight, UserPlus } from 'lucide-react';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import api from '@/lib/api';
import { CURRENCY } from '@/lib/constants';
import { useTranslation } from '@/components/providers/i18n-provider';

interface Student {
  id: string;
  firstName: string;
  lastName: string;
  createdAt: string;
}

interface Stats {
  students: number;
  teachers: number;
  classes: number;
  revenue: number;
}

export default function DashboardPage() {
  const { t } = useTranslation();
  const [stats, setStats] = useState<Stats>({
    students: 0,
    teachers: 0,
    classes: 0,
    revenue: 0,
  });
  const [recentStudents, setRecentStudents] = useState<Student[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [studentsRes, teachersRes, classesRes, paymentsRes, recentStudentsRes] = await Promise.all([
          api.get('/students?limit=1'),
          api.get('/teachers?limit=1'),
          api.get('/classes?limit=1'),
          api.get('/student-payments?limit=200'),
          api.get('/students?limit=5&sortBy=createdAt&sortOrder=desc'),
        ]);

        const paymentsData = paymentsRes.data.data || [];
        const revenue = paymentsData
          .filter((p: any) => p.status === 'PAID')
          .reduce((sum: number, p: any) => sum + Number(p.amount || 0), 0);

        setStats({
          students: studentsRes.data.meta?.total || 0,
          teachers: teachersRes.data.meta?.total || 0,
          classes: classesRes.data.meta?.total || 0,
          revenue,
        });

        const students = Array.isArray(recentStudentsRes.data)
          ? recentStudentsRes.data
          : recentStudentsRes.data?.data || [];
        setRecentStudents(students);
      } catch (error) {
        console.error('Failed to fetch stats:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  const statCards = [
    {
      title: t('dashboard.totalStudents'),
      value: stats.students,
      icon: GraduationCap,
      color: 'from-blue-500 to-blue-600',
      shadow: 'shadow-blue-500/25',
    },
    {
      title: t('dashboard.totalTeachers'),
      value: stats.teachers,
      icon: Users,
      color: 'from-green-500 to-green-600',
      shadow: 'shadow-green-500/25',
    },
    {
      title: t('dashboard.activeClasses'),
      value: stats.classes,
      icon: BookOpen,
      color: 'from-purple-500 to-purple-600',
      shadow: 'shadow-purple-500/25',
    },
    {
      title: t('dashboard.revenue'),
      value: `${stats.revenue.toLocaleString()} ${CURRENCY}`,
      icon: CreditCard,
      color: 'from-amber-500 to-orange-500',
      shadow: 'shadow-amber-500/25',
    },
  ];

  const formatDate = (dateStr: string) => {
    try {
      return new Date(dateStr).toLocaleDateString();
    } catch {
      return dateStr;
    }
  };

  return (
    <div className="space-y-6">
      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {statCards.map((stat) => (
          <Card key={stat.title} className="hover:shadow-lg transition-all duration-300 border-0 shadow-sm dark:bg-gray-800/50 dark:border-gray-700/50">
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-500 dark:text-gray-400">{stat.title}</p>
                   <div className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
                    {isLoading ? (
                      <div className="h-8 w-16 bg-gray-200 dark:bg-gray-700 rounded-lg animate-pulse" />
                    ) : (
                      stat.value
                    )}
                  </div>
                </div>
                <div className={`bg-gradient-to-br ${stat.color} p-3 rounded-xl shadow-lg ${stat.shadow}`}>
                  <stat.icon className="w-6 h-6 text-white" />
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Bottom Grid */}
      <div className="grid lg:grid-cols-2 gap-6">
        {/* Recent Students */}
        <Card className="border-0 shadow-sm dark:bg-gray-800/50 dark:border-gray-700/50">
          <CardHeader className="pb-4">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">{t('dashboard.recentStudents')}</h3>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="space-y-4">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="flex items-center gap-3 animate-pulse">
                    <div className="w-10 h-10 bg-gray-200 dark:bg-gray-700 rounded-full" />
                    <div className="flex-1 space-y-2">
                      <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/3" />
                      <div className="h-3 bg-gray-200 dark:bg-gray-700 rounded w-1/4" />
                    </div>
                  </div>
                ))}
              </div>
            ) : recentStudents.length > 0 ? (
              <div className="space-y-3">
                {recentStudents.map((student) => (
                  <div
                    key={student.id}
                    className="flex items-center gap-3 p-3 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                  >
                    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center flex-shrink-0">
                      <span className="text-white font-semibold text-sm">
                        {student.firstName?.[0]}{student.lastName?.[0]}
                      </span>
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-gray-900 dark:text-white truncate">
                        {student.firstName} {student.lastName}
                      </p>
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        {t('dashboard.joinedOn', { date: formatDate(student.createdAt) })}
                      </p>
                    </div>
                    <span className="px-2 py-1 text-xs font-medium bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 rounded-full">
                      {t('dashboard.enrolled')}
                    </span>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-gray-500 dark:text-gray-400 text-center py-8">
                {t('dashboard.noStudentsYet')}
              </p>
            )}
          </CardContent>
        </Card>

        {/* Quick Actions */}
        <Card className="border-0 shadow-sm dark:bg-gray-800/50 dark:border-gray-700/50">
          <CardHeader className="pb-4">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">{t('dashboard.quickActions')}</h3>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4">
              {[
                { label: t('dashboard.addStudent'), href: '/students', icon: UserPlus, color: 'from-blue-500 to-blue-600' },
                { label: t('dashboard.markAttendance'), href: '/attendance', icon: BookOpen, color: 'from-green-500 to-green-600' },
                { label: t('dashboard.viewReports'), href: '/reports', icon: TrendingUp, color: 'from-purple-500 to-purple-600' },
                { label: t('dashboard.manageClasses'), href: '/classes', icon: Users, color: 'from-amber-500 to-orange-500' },
              ].map((action) => (
                <a
                  key={action.label}
                  href={action.href}
                  className="group flex items-center gap-3 p-4 rounded-xl border border-gray-200 dark:border-gray-700/50 hover:border-blue-300 dark:hover:border-blue-700 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-all duration-200"
                >
                  <div className={`bg-gradient-to-br ${action.color} p-2 rounded-lg shadow-md group-hover:scale-110 transition-transform duration-200`}>
                    <action.icon className="w-4 h-4 text-white" />
                  </div>
                  <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{action.label}</span>
                  <ArrowUpRight className="w-4 h-4 text-gray-400 dark:text-gray-500 ml-auto group-hover:text-blue-500 transition-colors" />
                </a>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

