@import "tailwindcss";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-success: var(--success);
  --color-success-muted: var(--success-muted);
  --color-warning: var(--warning);
  --color-warning-muted: var(--warning-muted);
  --color-info: var(--info);
  --color-info-muted: var(--info-muted);
  --color-surface: var(--surface);
  --color-surface-elevated: var(--surface-elevated);
  --color-surface-hover: var(--surface-hover);
  --color-surface-active: var(--surface-active);
  --color-text-primary: var(--text-primary);
  --color-text-secondary: var(--text-secondary);
  --color-text-tertiary: var(--text-tertiary);
  --color-text-inverse: var(--text-inverse);
  --color-brand: var(--brand);
  --color-brand-hover: var(--brand-hover);
  --color-brand-active: var(--brand-active);
  --color-brand-muted: var(--brand-muted);
  --color-brand-subtle: var(--brand-subtle);
  --color-sidebar-bg: var(--sidebar-bg);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-hover: var(--sidebar-hover);
  --color-sidebar-active: var(--sidebar-active);
  --color-glass: var(--glass-bg);
  --color-glass-heavy: var(--glass-bg-heavy);
  --color-glass-border: var(--glass-border);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

/* ─── LIGHT MODE ─── */
:root {
  color-scheme: light;
  --background: #FFFFFF;
  --foreground: #111827;
  --card: #FFFFFF;
  --card-foreground: #111827;
  --popover: #FFFFFF;
  --popover-foreground: #111827;
  --primary: #4F46E5;
  --primary-foreground: #FFFFFF;
  --secondary: #F3F4F6;
  --secondary-foreground: #374151;
  --muted: #F3F4F6;
  --muted-foreground: #6B7280;
  --accent: #F3F4F6;
  --accent-foreground: #374151;
  --destructive: #DC2626;
  --destructive-foreground: #FFFFFF;
  --border: #E5E7EB;
  --input: #E5E7EB;
  --ring: #4F46E5;
  --success: #059669;
  --success-muted: rgba(5, 150, 105, 0.08);
  --warning: #D97706;
  --warning-muted: rgba(217, 119, 6, 0.08);
  --info: #2563EB;
  --info-muted: rgba(37, 99, 235, 0.08);
  --surface: #F9FAFB;
  --surface-elevated: #FFFFFF;
  --surface-hover: #F3F4F6;
  --surface-active: #E5E7EB;
  --text-primary: #111827;
  --text-secondary: #6B7280;
  --text-tertiary: #9CA3AF;
  --text-inverse: #FFFFFF;
  --brand: #4F46E5;
  --brand-hover: #4338CA;
  --brand-active: #3730A3;
  --brand-muted: rgba(79, 70, 229, 0.08);
  --brand-subtle: rgba(79, 70, 229, 0.04);
  --sidebar-bg: #F9FAFB;
  --sidebar-border: #E5E7EB;
  --sidebar-hover: #F3F4F6;
  --sidebar-active: rgba(79, 70, 229, 0.06);
  --glass-bg: rgba(255, 255, 255, 0.72);
  --glass-bg-heavy: rgba(255, 255, 255, 0.85);
  --glass-border: rgba(255, 255, 255, 0.18);
}

/* ─── DARK MODE ─── */
.dark {
  color-scheme: dark;
  --background: #0A0A0B;
  --foreground: #F5F5F7;
  --card: #111113;
  --card-foreground: #F5F5F7;
  --popover: #19191B;
  --popover-foreground: #F5F5F7;
  --primary: #818CF8;
  --primary-foreground: #FFFFFF;
  --secondary: #19191B;
  --secondary-foreground: #D1D5DB;
  --muted: #19191B;
  --muted-foreground: #A1A1AA;
  --accent: #19191B;
  --accent-foreground: #D1D5DB;
  --destructive: #F87171;
  --destructive-foreground: #FFFFFF;
  --border: rgba(255, 255, 255, 0.06);
  --input: rgba(255, 255, 255, 0.06);
  --ring: #818CF8;
  --success: #34D399;
  --success-muted: rgba(52, 211, 153, 0.10);
  --warning: #FBBF24;
  --warning-muted: rgba(251, 191, 36, 0.10);
  --info: #60A5FA;
  --info-muted: rgba(96, 165, 250, 0.10);
  --surface: #111113;
  --surface-elevated: #19191B;
  --surface-hover: #1F1F22;
  --surface-active: #26262A;
  --text-primary: #F5F5F7;
  --text-secondary: #A1A1AA;
  --text-tertiary: #71717A;
  --text-inverse: #111827;
  --brand: #818CF8;
  --brand-hover: #A5B4FC;
  --brand-active: #C7D2FE;
  --brand-muted: rgba(129, 140, 248, 0.10);
  --brand-subtle: rgba(129, 140, 248, 0.05);
  --sidebar-bg: #111113;
  --sidebar-border: rgba(255, 255, 255, 0.06);
  --sidebar-hover: #19191B;
  --sidebar-active: rgba(129, 140, 248, 0.10);
  --glass-bg: rgba(17, 17, 19, 0.72);
  --glass-bg-heavy: rgba(17, 17, 19, 0.85);
  --glass-border: rgba(255, 255, 255, 0.08);
}

/* ─── BASE ─── */
* {
  border-color: var(--border);
}

body {
  font-family: var(--font-geist-sans), -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background-color: var(--background);
  color: var(--foreground);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ─── TYPOGRAPHY UTILITIES ─── */
.font-feature-tabular {
  font-feature-settings: "tnum";
}

.font-feature-lining {
  font-feature-settings: "lnum";
}

/* ─── GLASS UTILITIES ─── */
.glass {
  background: var(--glass-bg);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);
  border: 1px solid var(--glass-border);
}

.glass-heavy {
  background: var(--glass-bg-heavy);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid var(--glass-border);
}

.glass-card {
  background: var(--glass-bg);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.08);
}

.dark .glass-card {
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.32);
}

/* Specular highlight — top edge shine */
.specular-highlight {
  position: relative;
  overflow: hidden;
}

.specular-highlight::before {
  content: '';
  position: absolute;
  inset-inline: 0;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent);
  z-index: 1;
}

/* ─── KEYFRAMES ─── */
@keyframes modalIn {
  from { opacity: 0; transform: scale(0.96) translateY(8px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

@keyframes overlayIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInFromRight {
  from { opacity: 0; transform: translateX(16px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes slideInFromBottom {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes slideIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes progress {
  from { width: 100%; }
  to { width: 0%; }
}

/* ─── MODAL ─── */
.modal-overlay {
  animation: overlayIn 0.15s ease-out;
}

.modal-content {
  animation: modalIn 0.2s cubic-bezier(0.25, 0.1, 0.25, 1);
}

/* ─── ANIMATION UTILITIES ─── */
.animate-fade-in {
  animation: fadeIn 0.3s ease-out;
}

.animate-slide-up {
  animation: slideInFromBottom 0.3s ease-out;
}

.animate-slide-right {
  animation: slideInFromRight 0.3s ease-out;
}

.animate-scale-in {
  animation: scaleIn 0.2s ease-out;
}

.animate-shimmer {
  background: linear-gradient(90deg, transparent 25%, rgba(255,255,255,0.08) 50%, transparent 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite linear;
}

.animate-toast {
  animation: slideIn 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ─── SKELETON ─── */
.skeleton {
  background: linear-gradient(
    90deg,
    var(--surface-hover) 25%,
    var(--surface-active) 50%,
    var(--surface-hover) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite linear;
  border-radius: 8px;
}

/* ─── REDUCED MOTION ─── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ─── REDUCED TRANSPARENCY ─── */
@media (prefers-reduced-transparency: reduce) {
  .glass, .glass-heavy, .glass-card {
    backdrop-filter: none;
    background: var(--surface-elevated);
  }
}

/* ─── HIGH CONTRAST ─── */
@media (prefers-contrast: more) {
  .glass, .glass-card {
    backdrop-filter: none;
    background: var(--surface);
    border: 1px solid var(--border);
  }
}

/* ─── SCROLLBAR ─── */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--text-tertiary);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-secondary);
}

