  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      await login(email, password);
      router.push('/dashboard');
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : t('auth.login.error');
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="animate-fade-in">
      <div className="text-center mb-8">
        <Link href="/" className="inline-flex items-center gap-3 mb-6">
          <div className="w-11 h-11 rounded-xl bg-gold flex items-center justify-center shadow-lg shadow-gold/20">
            <School className="w-6 h-6 text-text-primary" />
          </div>
          <div className="text-left">
            <span className="font-bold text-xl text-text-primary block tracking-tight">BSofts</span>
            <span className="text-[10px] text-text-tertiary uppercase tracking-widest">School</span>
          </div>
        </Link>
        <h1 className="text-2xl font-bold text-text-primary">{t('auth.login.title')}</h1>
        <p className="text-sm text-text-secondary mt-1">{t('auth.login.subtitle')}</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {error && (
          <div className="p-3 bg-destructive/10 text-destructive text-sm rounded-lg border border-destructive/20 animate-shake">
            {error}
          </div>
        )}

        <div className="relative">
          <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
          <input
            type="email"
            placeholder={t('auth.login.email')}
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className="w-full h-12 pl-10 pr-4 bg-surface border border-border rounded-xl text-sm text-text-primary placeholder:text-text-tertiary transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-brand/20 focus:border-brand"
          />
        </div>

        <div className="relative">
          <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
          <input
            type="password"
            placeholder={t('auth.login.password')}
            value={password}
            onChange={(e) => setPassword(e.target.value)}
