'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { School, Check, Mail, Lock, User } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuthStore } from '@/store/auth-store';
import { useTranslation } from '@/components/providers/i18n-provider';
import api from '@/lib/api';

interface Plan {
  id: string;
  name: string;
  price: number;
  currency: string;
  interval: string;
}

export default function RegisterPage() {
  const { t } = useTranslation();
  const router = useRouter();
  const { register } = useAuthStore();
  const [step, setStep] = useState(1);
  const [plans, setPlans] = useState<Plan[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string | null>(null);
  const [plansLoading, setPlansLoading] = useState(true);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const fetchPlans = async () => {
      try {
        const response = await api.get('/landing/plans');
        const data = response.data;
        const plansList = Array.isArray(data) ? data : data.data || [];
        const activePlans = plansList.filter((p: { isActive?: boolean }) => p.isActive !== false);
        if (Array.isArray(activePlans) && activePlans.length > 0) {
          setPlans(activePlans);
        }
      } catch {
        // keep empty
      } finally {
        setPlansLoading(false);
      }
    };
    fetchPlans();
  }, []);

  useEffect(() => {
    if (!plansLoading && plans.length === 0) {
      setStep(2);
    }
  }, [plansLoading, plans]);

  const handlePlanContinue = () => {
    if (plans.length > 0 && !selectedPlanId) {
      setError(t('auth.register.selectPlanError'));
      return;
    }
    setError('');
    setStep(2);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (formData.password !== formData.confirmPassword) {
      setError(t('common.passwordsDoNotMatch'));
      return;
    }

    setIsLoading(true);

    try {
      await register({
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email,
        password: formData.password,
        ...(selectedPlanId ? { planId: selectedPlanId } : {}),
      });
      router.push('/dashboard');
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : t('auth.register.error');
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const getIntervalLabel = (interval: string) => {
    switch (interval?.toLowerCase()) {
      case 'monthly': case 'month': return '/mo';
      case 'yearly': case 'year': return '/yr';
      default: return '';
    }
  };

  return (
    <div className="animate-fade-in">
      <div className="text-center mb-8">
        <Link href="/" className="inline-flex items-center gap-3 mb-6">
          <div className="w-11 h-11 rounded-xl bg-gold flex items-center justify-center shadow-lg shadow-gold/20">
            <School className="w-6 h-6 text-text-primary" />
          </div>
          <div className="text-left">
            <span className="font-bold text-xl text-text-primary block tracking-tight">BSofts</span>
            <span className="text-[10px] text-text-tertiary uppercase tracking-widest">School</span>
          </div>
        </Link>
        <h1 className="text-2xl font-bold text-text-primary">{t('auth.register.title')}</h1>
        <p className="text-sm text-text-secondary mt-1">{t('auth.register.subtitle')}</p>
      </div>

      {/* Step indicator */}
      <div className="flex items-center justify-center gap-2 mb-8">
        <div className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-all duration-200 ${step >= 1 ? 'bg-brand text-white shadow-md shadow-brand/30' : 'bg-surface text-text-tertiary border border-border'}`}>
            {step > 1 ? <Check className="w-4 h-4" /> : '1'}
          </div>
          <span className="text-sm font-medium text-text-primary">{t('auth.register.step1')}</span>
        </div>
        <div className="w-12 h-px bg-border mx-2" />
        <div className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-all duration-200 ${step >= 2 ? 'bg-brand text-white shadow-md shadow-brand/30' : 'bg-surface text-text-tertiary border border-border'}`}>
            2
          </div>
          <span className="text-sm font-medium text-text-primary">{t('auth.register.step2')}</span>
        </div>
      </div>

      {error && (
        <div className="p-3 bg-destructive/10 text-destructive text-sm rounded-lg mb-4 border border-destructive/20">
          {error}
        </div>
      )}

      {step === 1 && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {plans.map((plan) => (
              <div
                key={plan.id}
                className={`cursor-pointer rounded-xl border-2 p-6 text-center transition-all duration-200 ${
                  selectedPlanId === plan.id
                    ? 'border-brand bg-brand-subtle shadow-md shadow-brand/10'
                    : 'border-border bg-surface hover:border-brand/30'
                }`}
                onClick={() => setSelectedPlanId(plan.id)}
              >
                {selectedPlanId === plan.id && (
                  <div className="inline-flex items-center justify-center w-7 h-7 rounded-full bg-brand text-white mb-2 animate-scale-in">
                    <Check className="w-4 h-4" />
                  </div>
                )}
                <h3 className="text-base font-semibold text-text-primary">{plan.name}</h3>
                <div className="mt-3">
                  <span className="text-2xl font-bold text-text-primary font-feature-tabular">{plan.price}</span>
                  <span className="text-sm text-text-tertiary ml-1">{plan.currency}{getIntervalLabel(plan.interval)}</span>
                </div>
              </div>
            ))}
          </div>

          <Button type="button" className="w-full h-12" onClick={handlePlanContinue} isLoading={plansLoading}>
            {t('auth.register.continue')}
          </Button>
        </div>
      )}

      {step === 2 && (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="relative">
              <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
              <input
                placeholder={t('auth.register.firstName')}
                value={formData.firstName}
                onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                required
                className="w-full h-12 pl-10 pr-4 bg-surface border border-border rounded-xl text-sm text-text-primary placeholder:text-text-tertiary transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-brand/20 focus:border-brand"
              />
            </div>
            <div className="relative">
              <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
              <input
                placeholder={t('auth.register.lastName')}
                value={formData.lastName}
                onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                required
                className="w-full h-12 pl-10 pr-4 bg-surface border border-border rounded-xl text-sm text-text-primary placeholder:text-text-tertiary transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-brand/20 focus:border-brand"
              />
            </div>
          </div>

          <div className="relative">
            <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
            <input
              type="email"
              placeholder={t('auth.register.email')}
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              required
              className="w-full h-12 pl-10 pr-4 bg-surface border border-border rounded-xl text-sm text-text-primary placeholder:text-text-tertiary transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-brand/20 focus:border-brand"
            />
          </div>

          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
            <input
              type="password"
              placeholder={t('auth.register.password')}
              value={formData.password}
              onChange={(e) => setFormData({ ...formData, password: e.target.value })}
              required
              className="w-full h-12 pl-10 pr-4 bg-surface border border-border rounded-xl text-sm text-text-primary placeholder:text-text-tertiary transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-brand/20 focus:border-brand"
            />
          </div>

          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
            <input
              type="password"
              placeholder={t('auth.register.confirmPassword')}
              value={formData.confirmPassword}
              onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
              required
              className="w-full h-12 pl-10 pr-4 bg-surface border border-border rounded-xl text-sm text-text-primary placeholder:text-text-tertiary transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-brand/20 focus:border-brand"
            />
          </div>

          <div className="flex gap-3">
            <Button type="button" variant="secondary" onClick={() => setStep(1)} className="h-12">
              {t('common.back')}
            </Button>
            <Button type="submit" className="flex-1 h-12" isLoading={isLoading}>
              {t('auth.register.submit')}
            </Button>
          </div>
        </form>
      )}

      <p className="mt-6 text-center text-sm text-text-secondary">
        {t('auth.register.hasAccount')}{' '}
        <Link href="/login" className="text-brand hover:text-brand-hover font-semibold transition-colors duration-200">
          {t('auth.register.signIn')}
        </Link>
      </p>
    </div>
  );
}

