const locales: Locale[] = ['en', 'fr', 'ar'];
const localeLabels: Record<Locale, string> = { en: 'EN', fr: 'FR', ar: 'AR' };

function LandingLanguageSelector({ locale, setLocale, langMenuOpen, setLangMenuOpen, variant }: {
  locale: Locale; setLocale: (l: Locale) => void; langMenuOpen: boolean; setLangMenuOpen: (v: boolean) => void; variant: 'desktop' | 'mobile';
}) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setLangMenuOpen(false); };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [setLangMenuOpen]);

  return (
    <div ref={ref} className="relative">
      <button onClick={() => setLangMenuOpen(!langMenuOpen)} className={`flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium rounded-lg transition-colors duration-200 ${variant === 'desktop' ? 'text-text-secondary hover:text-text-primary hover:bg-surface-hover' : 'text-text-secondary hover:bg-surface-hover'}`}>
        <Globe className="w-4 h-4" />
        {variant === 'desktop' && localeLabels[locale]}
      </button>
      {langMenuOpen && (
        <div className="absolute right-0 mt-2 w-32 bg-surface border border-border rounded-xl shadow-xl py-1 z-50">
          {locales.map((loc) => (
            <button key={loc} onClick={() => { setLocale(loc); setLangMenuOpen(false); }}
              className={`block w-full text-left px-4 py-2 text-sm transition-colors duration-200 ${locale === loc ? 'bg-brand-subtle text-brand font-medium' : 'text-text-secondary hover:bg-surface-hover'}`}>
              {localeLabels[loc]}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

