'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { GraduationCap, Users, BookOpen, CreditCard, TrendingUp, ArrowUpRight, UserPlus, Calendar } from 'lucide-react';
import api from '@/lib/api';
import { CURRENCY } from '@/lib/constants';
import { useTranslation } from '@/components/providers/i18n-provider';
import { Spinner } from '@/components/ui/spinner';

interface Student {
  id: string;
  firstName: string;
  lastName: string;
  createdAt: string;
}

interface Stats {
  students: number;
  teachers: number;
  classes: number;
  revenue: number;
}

export default function DashboardPage() {
  const { t } = useTranslation();
  const [stats, setStats] = useState<Stats>({ students: 0, teachers: 0, classes: 0, revenue: 0 });
  const [recentStudents, setRecentStudents] = useState<Student[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [studentsRes, teachersRes, classesRes, paymentsRes, recentStudentsRes] = await Promise.all([
          api.get('/students?limit=1'),
          api.get('/teachers?limit=1'),
          api.get('/classes?limit=1'),
          api.get('/student-payments?limit=200'),
          api.get('/students?limit=5&sortBy=createdAt&sortOrder=desc'),
        ]);

        const paymentsData = paymentsRes.data.data || [];
        const revenue = paymentsData
          .filter((p: { status: string; amount: number }) => p.status === 'PAID')
          .reduce((sum: number, p: { amount: number }) => sum + Number(p.amount || 0), 0);

        setStats({
          students: studentsRes.data.meta?.total || 0,
          teachers: teachersRes.data.meta?.total || 0,
          classes: classesRes.data.meta?.total || 0,
          revenue,
        });

        const students = Array.isArray(recentStudentsRes.data)
          ? recentStudentsRes.data
          : recentStudentsRes.data?.data || [];
        setRecentStudents(students);
      } catch (error) {
        console.error('Failed to fetch stats:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  const statCards = [
    { title: t('dashboard.totalStudents'), value: stats.students, icon: GraduationCap },
    { title: t('dashboard.totalTeachers'), value: stats.teachers, icon: Users },
    { title: t('dashboard.activeClasses'), value: stats.classes, icon: BookOpen },
    { title: t('dashboard.revenue'), value: `${stats.revenue.toLocaleString()} ${CURRENCY}`, icon: CreditCard },
  ];

  const formatDate = (dateStr: string) => {
    try { return new Date(dateStr).toLocaleDateString(); } catch { return dateStr; }
  };

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div>
        <h1 className="text-2xl font-semibold text-text-primary tracking-tight" style={{ letterSpacing: '-0.02em' }}>
          {t('pages.dashboardTitle')}
        </h1>
        <p className="text-sm text-text-secondary mt-1">
          Welcome back. Here&apos;s what&apos;s happening today.
        </p>
      </div>

      {/* Stats Grid — Bento style */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {statCards.map((stat) => (
          <div
            key={stat.title}
            className="bg-surface-elevated border border-border rounded-xl p-5 group hover:bg-surface-hover transition-colors duration-fast"
          >
            <div className="flex items-center justify-between mb-3">
              <p className="text-xs font-medium uppercase tracking-widest text-text-tertiary">{stat.title}</p>
              <stat.icon className="w-4 h-4 text-text-tertiary" />
            </div>
            <div className="text-2xl font-semibold text-text-primary font-feature-tabular tracking-tight">
              {isLoading ? (
                <div className="h-7 w-16 skeleton" />
              ) : (
                stat.value
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Bottom Grid */}
      <div className="grid lg:grid-cols-3 gap-4">
        {/* Recent Students — 2 cols */}
        <div className="lg:col-span-2 bg-surface-elevated border border-border rounded-xl">
          <div className="px-6 py-4 border-b border-border">
            <h3 className="text-sm font-semibold text-text-primary tracking-tight">{t('dashboard.recentStudents')}</h3>
          </div>
          <div className="p-6">
            {isLoading ? (
              <div className="flex items-center justify-center py-8"><Spinner /></div>
            ) : recentStudents.length > 0 ? (
              <div className="space-y-1">
                {recentStudents.map((student) => (
                  <div
                    key={student.id}
                    className="flex items-center gap-3 p-3 rounded-lg hover:bg-surface-hover transition-colors duration-fast"
                  >
                    <div className="w-9 h-9 rounded-full bg-brand-muted flex items-center justify-center shrink-0">
                      <span className="text-sm font-medium text-brand">
                        {student.firstName?.[0]}{student.lastName?.[0]}
                      </span>
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-text-primary truncate">
                        {student.firstName} {student.lastName}
                      </p>
                      <p className="text-xs text-text-tertiary">
                        {t('dashboard.joinedOn', { date: formatDate(student.createdAt) })}
                      </p>
                    </div>
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-success-muted text-success">
                      <span className="w-1.5 h-1.5 rounded-full bg-success" />
                      {t('dashboard.enrolled')}
                    </span>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-text-tertiary text-center py-8">
                {t('dashboard.noStudentsYet')}
              </p>
            )}
          </div>
        </div>

        {/* Quick Actions — 1 col */}
        <div className="bg-surface-elevated border border-border rounded-xl">
          <div className="px-6 py-4 border-b border-border">
            <h3 className="text-sm font-semibold text-text-primary tracking-tight">{t('dashboard.quickActions')}</h3>
          </div>
          <div className="p-4 space-y-1">
            {[
              { label: t('dashboard.addStudent'), href: '/students', icon: UserPlus },
              { label: t('dashboard.markAttendance'), href: '/attendance', icon: Calendar },
              { label: t('dashboard.viewReports'), href: '/reports', icon: TrendingUp },
              { label: t('dashboard.manageClasses'), href: '/classes', icon: BookOpen },
            ].map((action) => (
              <Link
                key={action.label}
                href={action.href}
                className="group flex items-center gap-3 p-3 rounded-lg hover:bg-surface-hover transition-colors duration-fast"
              >
                <div className="w-8 h-8 bg-brand-muted rounded-lg flex items-center justify-center group-hover:bg-brand/15 transition-colors duration-fast">
                  <action.icon className="w-4 h-4 text-brand" />
                </div>
                <span className="text-sm font-medium text-text-secondary group-hover:text-text-primary transition-colors duration-fast flex-1">{action.label}</span>
                <ArrowUpRight className="w-4 h-4 text-text-tertiary group-hover:text-brand transition-colors duration-fast" />
              </Link>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

