const locales: Locale[] = ['en', 'fr', 'ar'];
const localeLabels: Record<Locale, string> = { en: 'EN', fr: 'FR', ar: 'AR' };

function AnimatedCounter({ target, suffix = '' }: { target: number; suffix?: string }) {
  const [count, setCount] = useState(0);
  const ref = useRef<HTMLSpanElement>(null);
  const hasAnimated = useRef(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasAnimated.current) {
          hasAnimated.current = true;
          const duration = 2000;
          const steps = 60;
          const increment = target / steps;
          let current = 0;
          const timer = setInterval(() => {
            current += increment;
            if (current >= target) {
              setCount(target);
              clearInterval(timer);
            } else {
              setCount(Math.floor(current));
            }
          }, duration / steps);
        }
      },
      { threshold: 0.3 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [target]);

  return <span ref={ref} className="tabular-nums">{count.toLocaleString()}{suffix}</span>;
}

function LandingLanguageSelector({ locale, setLocale, langMenuOpen, setLangMenuOpen, variant }: {
  locale: Locale; setLocale: (l: Locale) => void; langMenuOpen: boolean; setLangMenuOpen: (v: boolean) => void; variant: 'desktop' | 'mobile';
}) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setLangMenuOpen(false); };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [setLangMenuOpen]);

  return (
    <div ref={ref} className="relative">
      <button onClick={() => setLangMenuOpen(!langMenuOpen)} className={`flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium rounded-xl transition-all duration-300 ${variant === 'desktop' ? 'text-text-secondary hover:text-text-primary hover:bg-white/60 hover:backdrop-blur-sm' : 'text-text-secondary hover:bg-white/60'}`}>
        <Globe className="w-4 h-4" />
        {variant === 'desktop' && localeLabels[locale]}
      </button>
      {langMenuOpen && (
        <div className="absolute right-0 mt-2 w-36 glass rounded-2xl shadow-premium-lg py-1.5 z-50">
          {locales.map((loc) => (
            <button key={loc} onClick={() => { setLocale(loc); setLangMenuOpen(false); }}
              className={`block w-full text-left px-4 py-2.5 text-sm transition-all duration-200 ${locale === loc ? 'bg-brand/10 text-brand font-semibold' : 'text-text-secondary hover:bg-brand/5'}`}>
              {localeLabels[loc]}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

