'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { Menu, Bell, Search, X } from 'lucide-react';
import { ThemeToggle } from '@/components/theme-toggle';
import { LanguageSelector } from '@/components/language-selector';
import { useTranslation } from '@/components/providers/i18n-provider';
import api from '@/lib/api';

interface HeaderProps {
  onMenuClick: () => void;
  title: string;
}

interface SearchResult {
  id: string;
  type: 'student' | 'teacher';
  firstName: string;
  lastName: string;
  email?: string;
}

interface Notification {
  id: string;
  title: string;
  message: string;
  isRead: boolean;
  createdAt: string;
}

export function Header({ onMenuClick, title }: HeaderProps) {
  const { t } = useTranslation();
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [searchLoading, setSearchLoading] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);

  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  const fetchNotifications = useCallback(async () => {
    try {
      const res = await api.get('/notifications', { params: { isRead: false } });
      const data = res.data.data || res.data || [];
      setNotifications(data);
      setUnreadCount(data.filter((n: Notification) => !n.isRead).length);
    } catch {
      // notifications endpoint may not exist
    }
  }, []);

  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 60000);
    return () => clearInterval(interval);
  }, [fetchNotifications]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
        setShowSearchResults(false);
      }
      if (notifRef.current && !notifRef.current.contains(e.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const debounceRef = useRef<NodeJS.Timeout | null>(null);

  const handleSearch = useCallback((query: string) => {
    setSearchQuery(query);
    if (debounceRef.current) clearTimeout(debounceRef.current);

    if (!query.trim()) {
      setSearchResults([]);
      setShowSearchResults(false);
      return;
    }

    debounceRef.current = setTimeout(async () => {
      setSearchLoading(true);
      try {
        const [studentsRes, teachersRes] = await Promise.all([
          api.get('/students', { params: { search: query, limit: 5 } }).catch(() => ({ data: { data: [] } })),
          api.get('/teachers', { params: { search: query, limit: 5 } }).catch(() => ({ data: { data: [] } })),
        ]);

        const students = (studentsRes.data.data || []).map((s: Record<string, unknown>) => ({
          id: s.id as string, type: 'student' as const, firstName: s.firstName as string, lastName: s.lastName as string, email: s.email as string,
        }));
        const teachers = (teachersRes.data.data || []).map((item: Record<string, unknown>) => ({
          id: item.id as string, type: 'teacher' as const, firstName: item.firstName as string, lastName: item.lastName as string, email: item.email as string,
        }));

        setSearchResults([...students, ...teachers]);
        setShowSearchResults(true);
      } catch {
        setSearchResults([]);
      } finally {
        setSearchLoading(false);
      }
    }, 300);
  }, []);

  const handleMarkAllRead = async () => {
    try {
      await Promise.all(
        notifications.filter(n => !n.isRead).map(n =>
          api.put(`/notifications/${n.id}/read`)
        )
      );
      fetchNotifications();
    } catch {
      // ignore
    }
  };

  return (
    <header className="sticky top-0 z-40 glass border-b border-border/30">
      <div className="flex items-center justify-between h-16 px-4 lg:px-6">
        <div className="flex items-center gap-3">
          <button
            onClick={onMenuClick}
            className="lg:hidden p-2 rounded-xl hover:bg-white/60 transition-all duration-200"
            aria-label="Open menu"
          >
            <Menu className="w-5 h-5 text-text-secondary" />
          </button>
          <h1 className="text-lg font-bold text-text-primary tracking-tight truncate max-w-[calc(100vw-2rem)]" title={title}>{title}</h1>
        </div>

        <div className="flex items-center gap-2">
          <div ref={searchRef} className="relative hidden sm:block">
            <div className="flex items-center gap-2 h-10 px-3.5 glass rounded-xl transition-all duration-300 focus-within:ring-2 focus-within:ring-brand/15 focus-within:bg-white/80">
              <Search className="w-4 h-4 text-text-tertiary shrink-0" />
              <input
                type="text"
                placeholder={t('header.searchPlaceholder')}
                className="bg-transparent border-none outline-none text-sm w-44 text-text-primary placeholder:text-text-tertiary"
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                onFocus={() => searchResults.length > 0 && setShowSearchResults(true)}
              />
              {searchQuery && (
                <button onClick={() => { setSearchQuery(''); setSearchResults([]); setShowSearchResults(false); }} className="p-0.5 shrink-0 hover:bg-surface-hover rounded-md transition-colors">
                  <X className="w-3 h-3 text-text-tertiary" />
                </button>
              )}
            </div>

            {showSearchResults && (
              <div className="absolute top-full left-0 right-0 mt-2 glass rounded-2xl shadow-premium-lg max-h-80 overflow-y-auto z-50 w-80 animate-scale-in">
                {searchLoading ? (
                  <div className="p-4 text-center text-sm text-text-tertiary">{t('common.loading')}</div>
                ) : searchResults.length === 0 ? (
                  <div className="p-4 text-center text-sm text-text-tertiary">{t('header.noResults')}</div>
                ) : (
                  <div className="py-2">
                    {searchResults.map((result) => (
                      <div key={result.id} className="px-4 py-3 hover:bg-brand/5 cursor-pointer flex items-center gap-3 transition-colors duration-200">
                        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-brand/10 to-brand/5 flex items-center justify-center shrink-0">
                          <span className="text-sm font-semibold text-brand">
                            {result.firstName[0]}{result.lastName[0]}
                          </span>
                        </div>
                        <div className="min-w-0">
                          <p className="text-sm font-semibold text-text-primary truncate">{result.firstName} {result.lastName}</p>
                          <p className="text-xs text-text-tertiary truncate">{result.type === 'student' ? t('crud.student') : t('crud.teacher')}{result.email ? ` - ${result.email}` : ''}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          <ThemeToggle />
          <LanguageSelector />

          <div ref={notifRef} className="relative">
            <button
              onClick={() => { setShowNotifications(!showNotifications); }}
              className="relative p-2.5 rounded-xl text-text-secondary hover:bg-white/60 transition-all duration-200"
              aria-label="Notifications"
            >
              <Bell className="w-5 h-5" />
              {unreadCount > 0 && (
                <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-gold rounded-full ring-2 ring-surface animate-pulse-gold" />
              )}
            </button>

            {showNotifications && (
              <div className="absolute right-0 top-full mt-2 w-80 max-w-[calc(100vw-2rem)] glass rounded-2xl shadow-premium-lg z-50 animate-scale-in">
                <div className="flex items-center justify-between px-5 py-3.5 border-b border-border/30">
                  <h3 className="text-sm font-bold text-text-primary">{t('header.notifications')}</h3>
                  {unreadCount > 0 && (
                    <button onClick={handleMarkAllRead} className="text-xs font-semibold text-brand hover:text-brand-hover transition-colors duration-200">
                      {t('header.markAllRead')}
                    </button>
                  )}
                </div>
                <div className="max-h-80 overflow-y-auto">
                  {notifications.length === 0 ? (
                    <div className="p-6 text-center text-sm text-text-tertiary">{t('header.noNotifications')}</div>
                  ) : (
                    notifications.map((notif) => (
                      <div key={notif.id} className={`px-5 py-3.5 border-b border-border/20 hover:bg-white/40 transition-colors duration-200 ${!notif.isRead ? 'bg-brand/[0.03]' : ''}`}>
                        <p className="text-sm font-semibold text-text-primary">{notif.title}</p>
                        <p className="text-xs text-text-secondary mt-1 leading-relaxed">{notif.message}</p>
                        <p className="text-[11px] text-text-tertiary mt-1.5">{new Date(notif.createdAt).toLocaleString()}</p>
                      </div>
                    ))
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}

'use client';

import { useEffect, useState, useRef, useCallback } from 'react';
import Link from 'next/link';
import { GraduationCap, Users, BookOpen, CreditCard, TrendingUp, ArrowUpRight, UserPlus, Calendar } from 'lucide-react';
import api from '@/lib/api';
import { CURRENCY } from '@/lib/constants';
import { useTranslation } from '@/components/providers/i18n-provider';
import { Spinner } from '@/components/ui/spinner';

interface Student {
  id: string;
  firstName: string;
  lastName: string;
  createdAt: string;
}

interface Stats {
  students: number;
  teachers: number;
  classes: number;
  revenue: number;
}

function AnimatedNumber({ value, prefix = '' }: { value: number; prefix?: string }) {
  const [display, setDisplay] = useState(0);
  const ref = useRef<HTMLSpanElement>(null);
  const animated = useRef(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !animated.current) {
          animated.current = true;
          const duration = 1200;
          const steps = 40;
          const increment = value / steps;
          let current = 0;
          const timer = setInterval(() => {
            current += increment;
            if (current >= value) {
              setDisplay(value);
              clearInterval(timer);
            } else {
              setDisplay(Math.floor(current));
            }
          }, duration / steps);
        }
      },
      { threshold: 0.3 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [value]);

  return <span ref={ref} className="tabular-nums">{prefix}{display.toLocaleString()}</span>;
}

export default function DashboardPage() {
  const { t } = useTranslation();
  const [stats, setStats] = useState<Stats>({ students: 0, teachers: 0, classes: 0, revenue: 0 });
  const [recentStudents, setRecentStudents] = useState<Student[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const fetchData = useCallback(async () => {
    try {
      const [studentsRes, teachersRes, classesRes, paymentsRes, recentStudentsRes] = await Promise.all([
        api.get('/students?limit=1'),
        api.get('/teachers?limit=1'),
        api.get('/classes?limit=1'),
        api.get('/student-payments?limit=200'),
        api.get('/students?limit=5&sortBy=createdAt&sortOrder=desc'),
      ]);

      const paymentsData = paymentsRes.data.data || [];
      const revenue = paymentsData
        .filter((p: { status: string; amount: number }) => p.status === 'PAID')
        .reduce((sum: number, p: { amount: number }) => sum + Number(p.amount || 0), 0);

      setStats({
        students: studentsRes.data.meta?.total || 0,
        teachers: teachersRes.data.meta?.total || 0,
        classes: classesRes.data.meta?.total || 0,
        revenue,
      });

      const students = Array.isArray(recentStudentsRes.data)
        ? recentStudentsRes.data
        : recentStudentsRes.data?.data || [];
      setRecentStudents(students);
    } catch (error) {
      console.error('Failed to fetch stats:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const statCards = [
    { title: t('dashboard.totalStudents'), value: stats.students, icon: GraduationCap, gradient: 'from-brand/10 to-brand/5', iconColor: 'text-brand', iconBg: 'bg-brand/10' },
    { title: t('dashboard.totalTeachers'), value: stats.teachers, icon: Users, gradient: 'from-gold/10 to-gold/5', iconColor: 'text-gold', iconBg: 'bg-gold/10' },
    { title: t('dashboard.activeClasses'), value: stats.classes, icon: BookOpen, gradient: 'from-brand/10 to-brand/5', iconColor: 'text-brand', iconBg: 'bg-brand/10' },
    { title: t('dashboard.revenue'), value: stats.revenue, icon: CreditCard, gradient: 'from-gold/10 to-gold/5', iconColor: 'text-gold', iconBg: 'bg-gold/10', isRevenue: true },
  ];

  const formatDate = (dateStr: string) => {
    try { return new Date(dateStr).toLocaleDateString(); } catch { return dateStr; }
  };

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div>
        <h1 className="text-2xl font-bold text-text-primary tracking-tight">
          {t('pages.dashboardTitle')}
        </h1>
        <p className="text-sm text-text-secondary mt-1">
          Welcome back. Here&apos;s what&apos;s happening today.
        </p>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {statCards.map((stat, i) => (
          <div
            key={stat.title}
            className="group card-premium rounded-2xl p-5 relative overflow-hidden"
          >
            {/* Gradient overlay on hover */}
            <div className={`absolute inset-0 bg-gradient-to-br ${stat.gradient} opacity-0 group-hover:opacity-100 transition-opacity duration-500`} />
            <div className="relative">
              <div className="flex items-center justify-between mb-4">
                <p className="text-xs font-semibold uppercase tracking-[0.15em] text-text-tertiary">{stat.title}</p>
                <div className={`w-9 h-9 ${stat.iconBg} rounded-xl flex items-center justify-center group-hover:scale-110 transition-transform duration-300`}>
                  <stat.icon className={`w-4.5 h-4.5 ${stat.iconColor}`} />
                </div>
              </div>
              <div className="text-2xl font-bold text-text-primary font-feature-tabular tracking-tight">
                {isLoading ? (
                  <div className="h-7 w-20 skeleton" />
                ) : stat.isRevenue ? (
                  <><AnimatedNumber value={stat.value} /> {CURRENCY}</>
                ) : (
                  <AnimatedNumber value={stat.value} />
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Bottom Grid */}
      <div className="grid lg:grid-cols-3 gap-4">
        {/* Recent Students */}
        <div className="lg:col-span-2 card-premium rounded-2xl overflow-hidden">
          <div className="px-6 py-4 border-b border-border/30">
            <h3 className="text-sm font-bold text-text-primary tracking-tight">{t('dashboard.recentStudents')}</h3>
          </div>
          <div className="p-6">
            {isLoading ? (
              <div className="flex items-center justify-center py-8"><Spinner /></div>
            ) : recentStudents.length > 0 ? (
              <div className="space-y-1">
                {recentStudents.map((student) => (
                  <div
                    key={student.id}
                    className="flex items-center gap-3.5 p-3 rounded-xl hover:bg-brand/[0.03] transition-all duration-200 group"
                  >
                    <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-brand/10 to-brand/5 flex items-center justify-center shrink-0 group-hover:from-brand/15 group-hover:to-brand/10 transition-all duration-200">
                      <span className="text-sm font-bold text-brand">
                        {student.firstName?.[0]}{student.lastName?.[0]}
                      </span>
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-semibold text-text-primary truncate">
                        {student.firstName} {student.lastName}
                      </p>
                      <p className="text-xs text-text-tertiary">
                        {t('dashboard.joinedOn', { date: formatDate(student.createdAt) })}
                      </p>
                    </div>
                    <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-semibold bg-brand/10 text-brand">
                      <span className="w-1.5 h-1.5 rounded-full bg-brand" />
                      {t('dashboard.enrolled')}
                    </span>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-text-tertiary text-center py-8">
                {t('dashboard.noStudentsYet')}
              </p>
            )}
          </div>
        </div>

        {/* Quick Actions */}
        <div className="card-premium rounded-2xl overflow-hidden">
          <div className="px-6 py-4 border-b border-border/30">
            <h3 className="text-sm font-bold text-text-primary tracking-tight">{t('dashboard.quickActions')}</h3>
          </div>
          <div className="p-3 space-y-0.5">
            {[
              { label: t('dashboard.addStudent'), href: '/students', icon: UserPlus, gradient: 'from-brand/10 to-brand/5' },
              { label: t('dashboard.markAttendance'), href: '/attendance', icon: Calendar, gradient: 'from-gold/10 to-gold/5' },
              { label: t('dashboard.viewReports'), href: '/reports', icon: TrendingUp, gradient: 'from-brand/10 to-brand/5' },
              { label: t('dashboard.manageClasses'), href: '/classes', icon: BookOpen, gradient: 'from-gold/10 to-gold/5' },
            ].map((action) => (
              <Link
                key={action.label}
                href={action.href}
                className="group flex items-center gap-3.5 p-3 rounded-xl hover:bg-brand/[0.03] transition-all duration-200"
              >
                <div className={`w-9 h-9 bg-gradient-to-br ${action.gradient} rounded-xl flex items-center justify-center group-hover:scale-110 transition-transform duration-200`}>
                  <action.icon className="w-4 h-4 text-brand" />
                </div>
                <span className="text-sm font-semibold text-text-secondary group-hover:text-text-primary transition-colors duration-200 flex-1">{action.label}</span>
                <ArrowUpRight className="w-4 h-4 text-text-tertiary group-hover:text-brand transition-colors duration-200" />
              </Link>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

