/* ─── SCROLLBAR ─── */
::-webkit-scrollbar { width: 5px; height: 5px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--text-tertiary); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-secondary); }

/* ─── REDUCED MOTION ─── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

'use client';

import { createContext, useContext, useEffect, useState, ReactNode } from 'react';

type Theme = 'light';

interface ThemeContextType {
  theme: Theme;
}

const ThemeContext = createContext<ThemeContextType>({ theme: 'light' });

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    document.documentElement.classList.remove('dark');
    document.documentElement.classList.add('light');
  }, []);

  if (!mounted) {
    return <>{children}</>;
  }

  return (
    <ThemeContext.Provider value={{ theme: 'light' }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  return useContext(ThemeContext);
}

'use client';

import { useState, useRef, useEffect } from 'react';
import { useTranslation, Locale } from '@/components/providers/i18n-provider';

const localeConfig: Record<Locale, { label: string; flag: string }> = {
  en: { label: 'EN', flag: '🇬🇧' },
  fr: { label: 'FR', flag: '🇫🇷' },
  ar: { label: 'AR', flag: '🇹🇳' },
};

export function LanguageSelector() {
  const { locale, setLocale } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const current = localeConfig[locale];

  return (
    <div ref={ref} className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-1.5 px-2.5 py-2 rounded-xl text-sm font-semibold text-text-secondary hover:bg-surface-hover hover:text-text-primary transition-all duration-200"
      >
        <span className="text-base leading-none">{current.flag}</span>
        <span className="text-xs font-bold">{current.label}</span>
      </button>
      {isOpen && (
        <div className="absolute right-0 mt-2 w-36 bg-surface border border-border rounded-2xl shadow-premium-lg py-1.5 z-50 animate-scale-in">
          {(Object.keys(localeConfig) as Locale[]).map((loc) => (
            <button
              key={loc}
              onClick={() => { setLocale(loc); setIsOpen(false); }}
              className={`flex items-center gap-2.5 w-full px-4 py-2.5 text-sm transition-all duration-200 ${
                locale === loc
                  ? 'bg-brand/8 text-brand font-bold'
                  : 'text-text-secondary hover:bg-surface-hover'
              }`}
            >
              <span className="text-base leading-none">{localeConfig[loc].flag}</span>
              <span className="font-semibold">{localeConfig[loc].label}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

