'use client';

import { useEffect, useState } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { useAuthStore } from '@/store/auth-store';
import { usePermissionsStore } from '@/store/permissions-store';
import { ToastProvider } from '@/components/ui/toast';
import { ErrorBoundary } from '@/components/ui/error-boundary';
import { Sidebar } from '@/components/layout/sidebar';
import { Header } from '@/components/layout/header';
import { useTranslation } from '@/components/providers/i18n-provider';
import { ScrollToTop } from '@/components/ui/scroll-to-top';

const routePermissions: Record<string, string> = {
  '/students': 'students:list',
  '/teachers': 'teachers:list',
  '/parents': 'parents:list',
  '/employees': 'employees:list',
  '/classes': 'classes:list',
  '/attendance': 'attendance:list',
  '/schedule': 'calendar:list',
  '/holidays': 'calendar:list',
  '/exams': 'exams:list',
  '/payments': 'payments:list',
  '/reports': 'reports:list',
  '/rooms': 'rooms:list',
  '/settings': 'settings:list',
};

const routeTitles: Record<string, string> = {
  '/dashboard': 'pages.dashboardTitle',
  '/students': 'pages.studentsTitle',
  '/teachers': 'pages.teachersTitle',
  '/parents': 'pages.parentsTitle',
  '/employees': 'pages.employeesTitle',
  '/classes': 'pages.classesTitle',
  '/schedule': 'pages.scheduleTitle',
  '/attendance': 'pages.attendanceTitle',
  '/holidays': 'pages.holidaysTitle',
  '/exams': 'pages.examsTitle',
  '/payments': 'pages.paymentsTitle',
  '/reports': 'pages.reportsTitle',
  '/rooms': 'pages.roomsTitle',
  '/settings': 'pages.settingsTitle',
  '/admin/plans': 'pages.plansTitle',
  '/admin/tenants': 'pages.tenantsTitle',
  '/admin/subscriptions': 'pages.subscriptionsTitle',
  '/admin/permissions': 'pages.permissionsTitle',
  '/admin/modules': 'pages.modulesTitle',
};

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const { user, isLoading, isAuthenticated, loadUser, logout } = useAuthStore();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const { t } = useTranslation();

  const { hasPermission } = usePermissionsStore();

  useEffect(() => {
    loadUser();
  }, [loadUser]);

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      router.push('/login');
    }
    if (!isLoading && isAuthenticated && pathname.startsWith('/admin') && user && !user.isRoot) {
      router.push('/dashboard');
    }
    const requiredPermission = routePermissions[pathname];
    if (requiredPermission && isAuthenticated && !hasPermission(requiredPermission)) {
      router.push('/dashboard');
    }
  }, [isLoading, isAuthenticated, pathname, user, router, hasPermission]);

  const handleLogout = () => {
    logout();
    router.push('/login');
  };

  const titleKey = routeTitles[pathname] || 'pages.dashboardTitle';

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex">
