display.text:
'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { clsx } from 'clsx';
import { useState } from 'react';
import {
  LayoutDashboard,
  Users,
  GraduationCap,
  BookOpen,
  ClipboardCheck,
  FileText,
  CreditCard,
  Settings,
  ChevronLeft,
  ChevronRight,
  School,
  BarChart3,
  Crown,
  CreditCard as PlanIcon,
  UserCheck,
  Shield,
  Building2,
  Home,
  Calendar,
  Layers,
} from 'lucide-react';
import { useAuthStore } from '@/store/auth-store';
import { usePermissionsStore } from '@/store/permissions-store';
import { useTranslation } from '@/components/providers/i18n-provider';

interface NavigationItem {
  name: string;
  href: string;
  icon: typeof LayoutDashboard;
  key: string;
  permission?: string;
  children?: { name: string; href: string; icon: typeof LayoutDashboard; key: string; permission?: string }[];
}

const navigation: NavigationItem[] = [
  { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard, key: 'nav.dashboard' },
  {
    name: 'People', href: '#', icon: Users, key: 'nav.students',
    children: [
      { name: 'Students', href: '/students', icon: GraduationCap, key: 'nav.students', permission: 'students:list' },
      { name: 'Teachers', href: '/teachers', icon: Users, key: 'nav.teachers', permission: 'teachers:list' },
      { name: 'Parents', href: '/parents', icon: Users, key: 'nav.parents', permission: 'parents:list' },
      { name: 'Employees', href: '/employees', icon: Users, key: 'nav.employees', permission: 'employees:list' },
    ],
  },
  { name: 'Classes', href: '/classes', icon: BookOpen, key: 'nav.classes', permission: 'classes:list' },
  {
    name: 'Academic', href: '#', icon: Calendar, key: 'nav.schedule',
    children: [
      { name: 'Schedule', href: '/schedule', icon: Calendar, key: 'nav.schedule', permission: 'calendar:list' },
      { name: 'Holidays', href: '/holidays', icon: Calendar, key: 'nav.holidays', permission: 'calendar:list' },
      { name: 'Attendance', href: '/attendance', icon: ClipboardCheck, key: 'nav.attendance', permission: 'attendance:list' },
    ],
  },
  { name: 'Exams', href: '/exams', icon: FileText, key: 'nav.exams', permission: 'exams:list' },
  { name: 'Payments', href: '/payments', icon: CreditCard, key: 'nav.payments', permission: 'payments:list' },
  { name: 'Reports', href: '/reports', icon: BarChart3, key: 'nav.reports', permission: 'reports:list' },
  { name: 'Rooms', href: '/rooms', icon: Home, key: 'nav.rooms', permission: 'rooms:list' },
];

const rootNavigation: NavigationItem[] = [
  { name: 'Plans', href: '/admin/plans', icon: PlanIcon, key: 'nav.plans' },
  { name: 'Tenants', href: '/admin/tenants', icon: Building2, key: 'nav.tenants' },
  { name: 'Subscriptions', href: '/admin/subscriptions', icon: UserCheck, key: 'nav.subscriptions' },
  { name: 'Roles & Permissions', href: '/admin/permissions', icon: Shield, key: 'nav.rolesPermissions' },
  { name: 'Modules', href: '/admin/modules', icon: Layers, key: 'pages.modulesTitle' },
];

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  collapsed: boolean;
  onToggleCollapse: () => void;
}

export function Sidebar({ isOpen, onClose, collapsed, onToggleCollapse }: SidebarProps) {
  const pathname = usePathname();
  const { user } = useAuthStore();
  const { hasPermission } = usePermissionsStore();
  const { t } = useTranslation();
  const [hoveredItem, setHoveredItem] = useState<string | null>(null);

  const filteredNavigation = navigation.filter(item => {
    if (item.children) {
      const visibleChildren = item.children.filter(c => !c.permission || hasPermission(c.permission));
      return visibleChildren.length > 0;
    }
    if (!item.permission) return true;
    return hasPermission(item.permission);
  });

  const isItemActive = (item: NavigationItem): boolean => {
    if (item.href === '#') {
      return item.children?.some(c => pathname === c.href || pathname.startsWith(c.href + '/')) ?? false;
    }
    return pathname === item.href || pathname.startsWith(item.href + '/');
  };

  return (
    <>
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/30 backdrop-blur-sm lg:hidden z-20 animate-fade-in"
          onClick={onClose}
        />
      )}

      <aside
        className={clsx(
          'fixed lg:static inset-y-0 left-0 z-30 flex flex-col transform transition-all duration-300 ease-out bg-sidebar-bg',
          collapsed ? 'w-[72px]' : 'w-64',
          isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        )}
      >
        {/* Logo */}
        <div className={clsx('flex items-center h-16 border-b border-white/[0.06]', collapsed ? 'justify-center px-2' : 'justify-between px-5')}>
          <Link href="/dashboard" className="flex items-center gap-3 group">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-coral to-coral/80 flex items-center justify-center shadow-md shadow-coral/20 group-hover:shadow-coral/30 transition-all duration-300 shrink-0">
              <School className="w-4.5 h-4.5 text-white" />
            </div>
            {!collapsed && (
              <div>
                <span className="font-bold text-sm text-white tracking-tight block">BSofts</span>
                <span className="text-[10px] text-white/40 uppercase tracking-[0.15em] font-medium">School</span>
              </div>
            )}
          </Link>
          <button
            onClick={onToggleCollapse}
            className={clsx('hidden lg:flex p-1.5 rounded-lg hover:bg-white/[0.06] transition-colors duration-200', collapsed && 'absolute -right-3 top-5 bg-sidebar-bg border border-white/10 rounded-full shadow-md')}
            aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          >
            {collapsed ? <ChevronRight className="w-3.5 h-3.5 text-white/60" /> : <ChevronLeft className="w-3.5 h-3.5 text-white/60" />}
          </button>
        </div>

        {/* Navigation */}
        <nav className={clsx('flex-1 py-4 space-y-0.5 overflow-y-auto overflow-x-hidden', collapsed ? 'px-2' : 'px-3')} aria-label="Main navigation">
          {filteredNavigation.map((item) => {
            const isActive = isItemActive(item);
            const isHovered = hoveredItem === item.key;
            const hasChildren = item.children && item.children.length > 0;

            if (hasChildren && !collapsed) {
              return (
                <div
                  key={item.key}
                  className="relative"
                  onMouseEnter={() => setHoveredItem(item.key)}
                  onMouseLeave={() => setHoveredItem(null)}
                >
                  <div className={clsx(
                    'flex items-center gap-3 px-3 py-2.5 rounded-xl text-[13px] font-medium transition-all duration-200 cursor-pointer',
                    isActive ? 'bg-white/[0.08] text-white' : 'text-white/50 hover:bg-white/[0.04] hover:text-white/70'
                  )}>
                    <div className={clsx(
                      'w-8 h-8 rounded-lg flex items-center justify-center transition-all duration-200 shrink-0',
                      isActive ? 'bg-white/[0.1]' : 'bg-white/[0.04]'
                    )}>
                      <item.icon className={clsx('w-4 h-4', isActive ? 'text-coral' : 'text-white/40')} />
                    </div>
                    <span className="flex-1 truncate">{t(item.key)}</span>
                    <ChevronRight className={clsx('w-3.5 h-3.5 transition-transform duration-200', isHovered && 'rotate-90')} />
                  </div>

                  {/* Hover submenu */}
                  {isHovered && (
                    <div className="absolute left-full top-0 ml-2 w-52 bg-sidebar-bg border border-white/[0.08] rounded-xl shadow-premium-xl py-1.5 z-50 animate-scale-in">
                      {item.children?.map((child) => {
                        if (child.permission && !hasPermission(child.permission)) return null;
                        const childActive = pathname === child.href || pathname.startsWith(child.href + '/');
                        return (
                          <Link
                            key={child.key}
                            href={child.href}
                            className={clsx(
                              'flex items-center gap-3 px-4 py-2.5 text-[13px] font-medium transition-all duration-200',
                              childActive ? 'bg-white/[0.08] text-white' : 'text-white/50 hover:bg-white/[0.04] hover:text-white/70'
                            )}
                          >
                            <child.icon className={clsx('w-4 h-4', childActive ? 'text-coral' : 'text-white/30')} />
                            {t(child.key)}
                          </Link>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            }

            // Collapsed or no children
            if (hasChildren && collapsed) {
              return (
                <div key={item.key} className="relative" onMouseEnter={() => setHoveredItem(item.key)} onMouseLeave={() => setHoveredItem(null)}>
                  <div className={clsx(
                    'flex items-center justify-center py-2.5 rounded-xl transition-all duration-200 cursor-pointer',
                    isActive ? 'bg-white/[0.08] text-white' : 'text-white/50 hover:bg-white/[0.04]'
                  )}>
                    <item.icon className={clsx('w-5 h-5', isActive ? 'text-coral' : 'text-white/40')} />
                  </div>
                  {isHovered && (
                    <div className="absolute left-full top-0 ml-2 w-52 bg-sidebar-bg border border-white/[0.08] rounded-xl shadow-premium-xl py-1.5 z-50 animate-scale-in">
                      {item.children?.map((child) => {
                        if (child.permission && !hasPermission(child.permission)) return null;
                        const childActive = pathname === child.href || pathname.startsWith(child.href + '/');
                        return (
                          <Link key={child.key} href={child.href}
                            className={clsx('flex items-center gap-3 px-4 py-2.5 text-[13px] font-medium transition-all duration-200',
                              childActive ? 'bg-white/[0.08] text-white' : 'text-white/50 hover:bg-white/[0.04] hover:text-white/70')}>
                            <child.icon className={clsx('w-4 h-4', childActive ? 'text-coral' : 'text-white/30')} />
                            {t(child.key)}
                          </Link>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            }

            return (
              <Link
                key={item.key}
                href={item.href}
                className={clsx(
                  'flex items-center gap-3 rounded-xl text-[13px] font-medium transition-all duration-200',
                  collapsed ? 'justify-center px-2 py-2.5' : 'px-3 py-2.5',
                  isActive ? 'bg-white/[0.08] text-white' : 'text-white/50 hover:bg-white/[0.04] hover:text-white/70'
                )}
                onClick={onClose}
              >
                <div className={clsx(
                  'rounded-lg flex items-center justify-center transition-all duration-200 shrink-0',
                  collapsed ? 'w-9 h-9' : 'w-8 h-8',
                  isActive ? 'bg-white/[0.1]' : 'bg-white/[0.04]'
                )}>
                  <item.icon className={clsx('w-4 h-4', isActive ? 'text-coral' : 'text-white/40')} />
                </div>
                {!collapsed && t(item.key)}
              </Link>
            );
          })}

          {user?.isRoot && (
            <>
              {!collapsed && <div className="mx-3 my-3 h-px bg-white/[0.06]" />}
              {collapsed && <div className="mx-2 my-3 h-px bg-white/[0.06]" />}
              {!collapsed && (
                <p className="px-3 py-2 text-[10px] font-semibold uppercase tracking-[0.2em] text-white/25 flex items-center gap-2">
                  <Crown className="w-3 h-3 text-coral/60" />
                  {t('nav.rootAdmin')}
                </p>
              )}
              {rootNavigation.map((item) => {
                const isActive = isItemActive(item);
                return (
                  <Link
                    key={item.key}
                    href={item.href}
                    className={clsx(
                      'flex items-center gap-3 rounded-xl text-[13px] font-medium transition-all duration-200',
                      collapsed ? 'justify-center px-2 py-2.5' : 'px-3 py-2.5',
                      isActive ? 'bg-white/[0.08] text-white' : 'text-white/50 hover:bg-white/[0.04] hover:text-white/70'
                    )}
                    onClick={onClose}
                  >
                    <div className={clsx(
                      'rounded-lg flex items-center justify-center transition-all duration-200 shrink-0',
                      collapsed ? 'w-9 h-9' : 'w-8 h-8',
                      isActive ? 'bg-white/[0.1]' : 'bg-white/[0.04]'
                    )}>
                      <item.icon className={clsx('w-4 h-4', isActive ? 'text-coral' : 'text-white/40')} />
                    </div>
                    {!collapsed && t(item.key)}
                  </Link>
                );
              })}
            </>
          )}
        </nav>

        {/* Settings at bottom */}
        <div className={clsx('border-t border-white/[0.06] p-3', collapsed && 'px-2')}>
          <Link
            href="/settings"
            className={clsx(
              'flex items-center gap-3 rounded-xl text-[13px] font-medium transition-all duration-200',
              collapsed ? 'justify-center px-2 py-2.5' : 'px-3 py-2.5',
              pathname === '/settings' ? 'bg-white/[0.08] text-white' : 'text-white/50 hover:bg-white/[0.04] hover:text-white/70'
            )}
          >
            <div className={clsx(
              'rounded-lg flex items-center justify-center shrink-0',
              collapsed ? 'w-9 h-9' : 'w-8 h-8',
              pathname === '/settings' ? 'bg-white/[0.1]' : 'bg-white/[0.04]'
            )}>
              <Settings className="w-4 h-4 text-white/40" />
            </div>
            {!collapsed && t('nav.settings')}
          </Link>
        </div>
      </aside>
    </>
  );
}

