display.text:
'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import Link from 'next/link';
import { Menu, Bell, Search, X, LogOut, Settings, User, ChevronDown } from 'lucide-react';
import { LanguageSelector } from '@/components/language-selector';
import { useTranslation } from '@/components/providers/i18n-provider';
import { useAuthStore } from '@/store/auth-store';
import api from '@/lib/api';

interface HeaderProps {
  onMenuClick: () => void;
  title: string;
}

interface SearchResult {
  id: string;
  type: 'student' | 'teacher';
  firstName: string;
  lastName: string;
  email?: string;
}

interface Notification {
  id: string;
  title: string;
  message: string;
  isRead: boolean;
  createdAt: string;
}

export function Header({ onMenuClick, title }: HeaderProps) {
  const { t } = useTranslation();
  const { user, logout } = useAuthStore();
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [searchLoading, setSearchLoading] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);

  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  const [showProfile, setShowProfile] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);

  const fetchNotifications = useCallback(async () => {
    try {
      const res = await api.get('/notifications', { params: { isRead: false } });
      const data = res.data.data || res.data || [];
      setNotifications(data);
      setUnreadCount(data.filter((n: Notification) => !n.isRead).length);
    } catch { /* empty */ }
  }, []);

  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 60000);
    return () => clearInterval(interval);
  }, [fetchNotifications]);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) setShowSearchResults(false);
      if (notifRef.current && !notifRef.current.contains(e.target as Node)) setShowNotifications(false);
      if (profileRef.current && !profileRef.current.contains(e.target as Node)) setShowProfile(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const debounceRef = useRef<NodeJS.Timeout | null>(null);

  const handleSearch = useCallback((query: string) => {
    setSearchQuery(query);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (!query.trim()) { setSearchResults([]); setShowSearchResults(false); return; }
    debounceRef.current = setTimeout(async () => {
      setSearchLoading(true);
      try {
        const [studentsRes, teachersRes] = await Promise.all([
          api.get('/students', { params: { search: query, limit: 5 } }).catch(() => ({ data: { data: [] } })),
          api.get('/teachers', { params: { search: query, limit: 5 } }).catch(() => ({ data: { data: [] } })),
        ]);
        const students = (studentsRes.data.data || []).map((s: Record<string, unknown>) => ({
          id: s.id as string, type: 'student' as const, firstName: s.firstName as string, lastName: s.lastName as string,
        }));
        const teachers = (teachersRes.data.data || []).map((item: Record<string, unknown>) => ({
          id: item.id as string, type: 'teacher' as const, firstName: item.firstName as string, lastName: item.lastName as string,
        }));
        setSearchResults([...students, ...teachers]);
        setShowSearchResults(true);
      } catch { setSearchResults([]); } finally { setSearchLoading(false); }
    }, 300);
  }, []);

  const handleMarkAllRead = async () => {
    try {
      await Promise.all(notifications.filter(n => !n.isRead).map(n => api.put(`/notifications/${n.id}/read`)));
      fetchNotifications();
    } catch { /* empty */ }
  };

  return (
    <header className="sticky top-0 z-40 glass border-b border-border/30">
      <div className="flex items-center justify-between h-16 px-4 lg:px-6">
        <div className="flex items-center gap-3">
          <button onClick={onMenuClick} className="lg:hidden p-2 rounded-xl hover:bg-surface-hover transition-all duration-200" aria-label="Open menu">
            <Menu className="w-5 h-5 text-text-secondary" />
          </button>
          <h1 className="text-lg font-bold text-text-primary tracking-tight truncate max-w-[calc(100vw-2rem)]">{title}</h1>
        </div>

        <div className="flex items-center gap-2">
          {/* Search */}
          <div ref={searchRef} className="relative hidden sm:block">
            <div className="flex items-center gap-2 h-10 px-3.5 glass rounded-xl transition-all duration-300 focus-within:ring-2 focus-within:ring-brand/15">
              <Search className="w-4 h-4 text-text-tertiary shrink-0" />
              <input type="text" placeholder={t('header.searchPlaceholder')}
                className="bg-transparent border-none outline-none text-sm w-44 text-text-primary placeholder:text-text-tertiary"
                value={searchQuery} onChange={(e) => handleSearch(e.target.value)}
                onFocus={() => searchResults.length > 0 && setShowSearchResults(true)} />
              {searchQuery && (
                <button onClick={() => { setSearchQuery(''); setSearchResults([]); setShowSearchResults(false); }} className="p-0.5 shrink-0 hover:bg-surface-hover rounded-md transition-colors">
                  <X className="w-3 h-3 text-text-tertiary" />
                </button>
              )}
            </div>
            {showSearchResults && (
              <div className="absolute top-full left-0 right-0 mt-2 glass rounded-2xl shadow-premium-lg max-h-80 overflow-y-auto z-50 w-80 animate-scale-in">
                {searchLoading ? (
                  <div className="p-4 text-center text-sm text-text-tertiary">{t('common.loading')}</div>
                ) : searchResults.length === 0 ? (
                  <div className="p-4 text-center text-sm text-text-tertiary">{t('header.noResults')}</div>
                ) : (
                  <div className="py-2">
                    {searchResults.map((result) => (
                      <div key={result.id} className="px-4 py-3 hover:bg-brand/5 cursor-pointer flex items-center gap-3 transition-colors duration-200">
                        <div className="w-10 h-10 rounded-xl bg-brand/10 flex items-center justify-center shrink-0">
                          <span className="text-sm font-bold text-brand">{result.firstName[0]}{result.lastName[0]}</span>
                        </div>
                        <div className="min-w-0">
                          <p className="text-sm font-semibold text-text-primary truncate">{result.firstName} {result.lastName}</p>
                          <p className="text-xs text-text-tertiary truncate">{result.type}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Notifications */}
          <div ref={notifRef} className="relative">
            <button onClick={() => setShowNotifications(!showNotifications)}
              className="relative p-2.5 rounded-xl text-text-secondary hover:bg-surface-hover transition-all duration-200">
              <Bell className="w-5 h-5" />
              {unreadCount > 0 && <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-coral rounded-full ring-2 ring-surface animate-pulse-coral" />}
            </button>
            {showNotifications && (
              <div className="absolute right-0 top-full mt-2 w-80 max-w-[calc(100vw-2rem)] glass rounded-2xl shadow-premium-lg z-50 animate-scale-in">
                <div className="flex items-center justify-between px-5 py-3.5 border-b border-border/30">
                  <h3 className="text-sm font-bold text-text-primary">{t('header.notifications')}</h3>
                  {unreadCount > 0 && (
                    <button onClick={handleMarkAllRead} className="text-xs font-semibold text-brand hover:text-brand-hover transition-colors duration-200">
                      {t('header.markAllRead')}
                    </button>
                  )}
                </div>
                <div className="max-h-80 overflow-y-auto">
                  {notifications.length === 0 ? (
                    <div className="p-6 text-center text-sm text-text-tertiary">{t('header.noNotifications')}</div>
                  ) : notifications.map((notif) => (
                    <div key={notif.id} className={`px-5 py-3.5 border-b border-border/20 hover:bg-surface-hover/50 transition-colors duration-200 ${!notif.isRead ? 'bg-brand/[0.03]' : ''}`}>
                      <p className="text-sm font-semibold text-text-primary">{notif.title}</p>
                      <p className="text-xs text-text-secondary mt-1 leading-relaxed">{notif.message}</p>
                      <p className="text-[11px] text-text-tertiary mt-1.5">{new Date(notif.createdAt).toLocaleString()}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Language */}
          <LanguageSelector />

          {/* Profile dropdown */}
          <div ref={profileRef} className="relative">
            <button onClick={() => setShowProfile(!showProfile)}
              className="flex items-center gap-2.5 pl-2 pr-3 py-1.5 rounded-xl hover:bg-surface-hover transition-all duration-200">
              <div className="w-8 h-8 rounded-xl bg-gradient-to-br from-brand to-brand-hover flex items-center justify-center shadow-sm">
                <span className="text-xs font-bold text-white">{user?.firstName?.[0]}{user?.lastName?.[0]}</span>
              </div>
              <div className="hidden md:block text-left">
                <p className="text-[13px] font-semibold text-text-primary leading-tight">{user?.firstName} {user?.lastName}</p>
                <p className="text-[11px] text-text-tertiary leading-tight">{user?.email}</p>
              </div>
              <ChevronDown className="w-3.5 h-3.5 text-text-tertiary hidden md:block" />
            </button>
            {showProfile && (
              <div className="absolute right-0 top-full mt-2 w-56 glass rounded-2xl shadow-premium-lg py-1.5 z-50 animate-scale-in">
                <div className="px-4 py-3 border-b border-border/30 md:hidden">
                  <p className="text-sm font-bold text-text-primary">{user?.firstName} {user?.lastName}</p>
                  <p className="text-xs text-text-tertiary">{user?.email}</p>
                </div>
                <Link href="/settings" className="flex items-center gap-3 px-4 py-2.5 text-sm font-medium text-text-secondary hover:bg-surface-hover hover:text-text-primary transition-all duration-200"
                  onClick={() => setShowProfile(false)}>
                  <Settings className="w-4 h-4" /> {t('nav.settings')}
                </Link>
                <Link href="/settings" className="flex items-center gap-3 px-4 py-2.5 text-sm font-medium text-text-secondary hover:bg-surface-hover hover:text-text-primary transition-all duration-200"
                  onClick={() => setShowProfile(false)}>
                  <User className="w-4 h-4" /> Profile
                </Link>
                <div className="mx-4 my-1 h-px bg-border/30" />
                <button onClick={() => { logout(); setShowProfile(false); }}
                  className="flex items-center gap-3 w-full px-4 py-2.5 text-sm font-medium text-coral hover:bg-coral/5 transition-all duration-200">
                  <LogOut className="w-4 h-4" /> {t('nav.logout')}
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}

