import { useTranslation } from '@/components/providers/i18n-provider';

interface NavigationItem {
  name: string;
  href: string;
  icon: typeof LayoutDashboard;
  key: string;
  permission?: string;
  children?: { name: string; href: string; icon: typeof LayoutDashboard; key: string; permission?: string }[];
}

const navigation: NavigationItem[] = [
  { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard, key: 'nav.dashboard' },
  {
    name: 'People', href: '#', icon: Users, key: 'nav.people',
    children: [
      { name: 'Students', href: '/students', icon: GraduationCap, key: 'nav.students', permission: 'students:list' },
      { name: 'Teachers', href: '/teachers', icon: Users, key: 'nav.teachers', permission: 'teachers:list' },
      { name: 'Parents', href: '/parents', icon: Users, key: 'nav.parents', permission: 'parents:list' },
      { name: 'Employees', href: '/employees', icon: Users, key: 'nav.employees', permission: 'employees:list' },
    ],
  },
  { name: 'Classes', href: '/classes', icon: BookOpen, key: 'nav.classes', permission: 'classes:list' },
  {
    name: 'Academic', href: '#', icon: Calendar, key: 'nav.academic',
    children: [
      { name: 'Schedule', href: '/schedule', icon: Calendar, key: 'nav.schedule', permission: 'calendar:list' },
      { name: 'Holidays', href: '/holidays', icon: Calendar, key: 'nav.holidays', permission: 'calendar:list' },
      { name: 'Attendance', href: '/attendance', icon: ClipboardCheck, key: 'nav.attendance', permission: 'attendance:list' },
    ],
  },
  { name: 'Exams', href: '/exams', icon: FileText, key: 'nav.exams', permission: 'exams:list' },
  { name: 'Payments', href: '/payments', icon: CreditCard, key: 'nav.payments', permission: 'payments:list' },
  { name: 'Reports', href: '/reports', icon: BarChart3, key: 'nav.reports', permission: 'reports:list' },
  { name: 'Rooms', href: '/rooms', icon: Home, key: 'nav.rooms', permission: 'rooms:list' },
];

const rootNavigation: NavigationItem[] = [
  { name: 'Plans', href: '/admin/plans', icon: CreditCard, key: 'nav.plans' },
  { name: 'Tenants', href: '/admin/tenants', icon: Building2, key: 'nav.tenants' },
  { name: 'Subscriptions', href: '/admin/subscriptions', icon: UserCheck, key: 'nav.subscriptions' },
  { name: 'Roles & Permissions', href: '/admin/permissions', icon: Shield, key: 'nav.rolesPermissions' },
  { name: 'Modules', href: '/admin/modules', icon: Layers, key: 'pages.modulesTitle' },
];

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  collapsed: boolean;
  onToggleCollapse: () => void;
}

export function Sidebar({ isOpen, onClose, collapsed, onToggleCollapse }: SidebarProps) {
  const pathname = usePathname();
  const { user } = useAuthStore();
  const { hasPermission } = usePermissionsStore();
  const { t } = useTranslation();
  const [openSubmenu, setOpenSubmenu] = useState<string | null>(null);
  const [isHovering, setIsHovering] = useState(false);
  const hoverTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const filteredNavigation = navigation.filter(item => {
    if (item.children) {
      const visibleChildren = item.children.filter(c => !c.permission || hasPermission(c.permission));
      return visibleChildren.length > 0;
    }
    if (!item.permission) return true;
    return hasPermission(item.permission);
  });

  const isItemActive = (item: NavigationItem): boolean => {
    if (item.href === '#') {
      return item.children?.some(c => pathname === c.href || pathname.startsWith(c.href + '/')) ?? false;
    }
    return pathname === item.href || pathname.startsWith(item.href + '/');
  };

  const toggleSubmenu = (key: string) => {
    setOpenSubmenu(openSubmenu === key ? null : key);
  };

  const handleMouseEnter = () => {
    if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
    setIsHovering(true);
  };

  const handleMouseLeave = () => {
    hoverTimeoutRef.current = setTimeout(() => {
      setIsHovering(false);
      setOpenSubmenu(null);
    }, 200);
  };

  useEffect(() => {
    return () => { if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current); };
  }, []);

  const sidebarWidth = collapsed && !isHovering ? 80 : 270;

  const renderMenuItem = (item: NavigationItem, isRoot = false) => {
    const isActive = isItemActive(item);
    const hasChildren = item.children && item.children.length > 0;

    if (hasChildren) {
      const isOpen = openSubmenu === item.key || (collapsed && isHovering && openSubmenu === item.key);
      return (
        <li key={item.key} className="mb-0.5">
          <button
            onClick={() => toggleSubmenu(item.key)}
            className={clsx(
              'flex items-center gap-3 w-full rounded-lg text-[14px] font-medium transition-all duration-200',
              collapsed && !isHovering ? 'justify-center px-2 py-2.5' : 'px-3 py-2.5',
              isActive ? 'bg-brand/10 text-brand' : 'text-[#3A4252] hover:bg-[#F6F7F9]'
            )}
          >
            <item.icon className={clsx('w-5 h-5 shrink-0', isActive ? 'text-brand' : 'text-[#64748B]')} />
            {!collapsed || isHovering ? (
              <>
                <span className="flex-1 text-left">{t(item.key)}</span>
                <ChevronDown className={clsx('w-4 h-4 transition-transform duration-200', isOpen && 'rotate-180')} />
              </>
            ) : null}
          </button>
          {(!collapsed || isHovering) && isOpen && (
            <ul className="ml-4 mt-0.5 space-y-0.5">
              {item.children?.map((child) => {
                if (child.permission && !hasPermission(child.permission)) return null;
                const childActive = pathname === child.href || pathname.startsWith(child.href + '/');
                return (
                  <li key={child.key}>
                    <Link
                      href={child.href}
                      className={clsx(
                        'flex items-center gap-3 px-3 py-2 rounded-lg text-[13px] font-medium transition-all duration-200',
                        childActive ? 'bg-brand/10 text-brand' : 'text-[#64748B] hover:bg-[#F6F7F9] hover:text-[#3A4252]'
                      )}
                      onClick={onClose}
                    >
                      <span className={clsx(
                        'w-2 h-2 rounded-full border shrink-0',
                        childActive ? 'bg-brand border-brand' : 'border-[#64748B]'
                      )} />
                      {t(child.key)}
                    </Link>
                  </li>
                );
              })}
            </ul>
          )}
        </li>
      );
    }

    return (
      <li key={item.key} className="mb-0.5">
        <Link
          href={item.href}
          className={clsx(
            'flex items-center gap-3 rounded-lg text-[14px] font-medium transition-all duration-200',
            collapsed && !isHovering ? 'justify-center px-2 py-2.5' : 'px-3 py-2.5',
            isActive ? 'bg-brand/10 text-brand' : 'text-[#3A4252] hover:bg-[#F6F7F9]'
          )}
          onClick={onClose}
        >
          <item.icon className={clsx('w-5 h-5 shrink-0', isActive ? 'text-brand' : 'text-[#64748B]')} />
          {!collapsed || isHovering ? t(item.key) : null}
        </Link>
      </li>
    );
  };

  return (
    <>
      {/* Mobile overlay */}
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/30 backdrop-blur-sm lg:hidden z-40 animate-fade-in"
          onClick={onClose}
        />
      )}

      {/* Sidebar */}
      <aside
        className={clsx(
          'fixed top-0 left-0 h-full bg-white z-50 transition-all duration-300 ease-in-out flex flex-col border-r border-[#ECF0FF]',
          collapsed && !isHovering ? 'w-[80px]' : 'w-[270px]',
          isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        )}
        onMouseEnter={collapsed ? handleMouseEnter : undefined}
        onMouseLeave={collapsed ? handleMouseLeave : undefined}
      >
        {/* Logo */}
        <div className={clsx(
          'flex items-center h-[70px] border-b border-[#ECF0FF] shrink-0',
          collapsed && !isHovering ? 'justify-center px-2' : 'px-6'
        )}>
          <Link href="/dashboard" className="flex items-center gap-3 group">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-brand to-brand-hover flex items-center justify-center shadow-md shadow-brand/20 shrink-0">
              <School className="w-5 h-5 text-white" />
            </div>
            {(!collapsed || isHovering) && (
              <div>
                <span className="font-bold text-[20px] text-[#1a1a2e] tracking-tight block leading-tight">BSofts</span>
                <span className="text-[11px] text-[#9999b3] uppercase tracking-[0.15em] font-medium">School</span>
              </div>
            )}
          </Link>
        </div>

        {/* Menu */}
        <nav className="flex-1 overflow-y-auto py-5 px-4" style={{ scrollbarWidth: 'thin', scrollbarColor: '#e0e0e2 #F0F0F4' }}>
          {/* Section: Main */}
          {(!collapsed || isHovering) && (
            <p className="px-3 mb-2 text-[11px] font-semibold uppercase tracking-[0.15em] text-[#445164]">
              {t('nav.main') || 'Main'}
            </p>
          )}
          <ul className="space-y-0.5">
            {filteredNavigation.map(item => renderMenuItem(item))}
          </ul>

          {/* Root admin section */}
          {user?.isRoot && (
            <>
              {(!collapsed || isHovering) && (
                <>
                  <div className="mx-3 my-4 h-px bg-[#ECF0FF]" />
                  <p className="px-3 mb-2 text-[11px] font-semibold uppercase tracking-[0.15em] text-[#445164] flex items-center gap-2">
                    <Crown className="w-3 h-3 text-coral" />
                    {t('nav.rootAdmin')}
                  </p>
                </>
              )}
              {collapsed && !isHovering && <div className="mx-2 my-4 h-px bg-[#ECF0FF]" />}
              <ul className="space-y-0.5">
                {rootNavigation.map(item => renderMenuItem(item, true))}
              </ul>
            </>
          )}
        </nav>

        {/* Settings at bottom */}
        <div className="border-t border-[#ECF0FF] p-4 shrink-0">
          <Link
            href="/settings"
            className={clsx(
              'flex items-center gap-3 rounded-lg text-[14px] font-medium transition-all duration-200',
              collapsed && !isHovering ? 'justify-center px-2 py-2.5' : 'px-3 py-2.5',
              pathname === '/settings' ? 'bg-brand/10 text-brand' : 'text-[#3A4252] hover:bg-[#F6F7F9]'
            )}
          >
            <Settings className={clsx('w-5 h-5 shrink-0', pathname === '/settings' ? 'text-brand' : 'text-[#64748B]')} />
            {(!collapsed || isHovering) && t('nav.settings')}
          </Link>
        </div>
      </aside>
    </>
  );
}

