input.content:
'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import Link from 'next/link';
import { Menu, Bell, Search, X, LogOut, Settings, User, ChevronDown } from 'lucide-react';
import { LanguageSelector } from '@/components/language-selector';
import { useTranslation } from '@/components/providers/i18n-provider';
import { useAuthStore } from '@/store/auth-store';
import api from '@/lib/api';

interface HeaderProps {
  onMenuClick: () => void;
  title: string;
}

interface SearchResult {
  id: string;
  type: 'student' | 'teacher';
  firstName: string;
  lastName: string;
  email?: string;
}

interface Notification {
  id: string;
  title: string;
  message: string;
  isRead: boolean;
  createdAt: string;
}

export function Header({ onMenuClick, title }: HeaderProps) {
  const { t } = useTranslation();
  const { user, logout } = useAuthStore();
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [searchLoading, setSearchLoading] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);

  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const notifRef = useRef<HTMLDivElement>(null);

  const [showProfile, setShowProfile] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);

  const [isSticky, setIsSticky] = useState(false);

  const fetchNotifications = useCallback(async () => {
    try {
      const res = await api.get('/notifications', { params: { isRead: false } });
      const data = res.data.data || res.data || [];
      setNotifications(data);
      setUnreadCount(data.filter((n: Notification) => !n.isRead).length);
    } catch { /* empty */ }
  }, []);

  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 60000);
    return () => clearInterval(interval);
  }, [fetchNotifications]);

  useEffect(() => {
    const handleScroll = () => setIsSticky(window.scrollY >= 150);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) setShowSearchResults(false);
      if (notifRef.current && !notifRef.current.contains(e.target as Node)) setShowNotifications(false);
      if (profileRef.current && !profileRef.current.contains(e.target as Node)) setShowProfile(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const debounceRef = useRef<NodeJS.Timeout | null>(null);

  const handleSearch = useCallback((query: string) => {
    setSearchQuery(query);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (!query.trim()) { setSearchResults([]); setShowSearchResults(false); return; }
    debounceRef.current = setTimeout(async () => {
      setSearchLoading(true);
      try {
        const [studentsRes, teachersRes] = await Promise.all([
          api.get('/students', { params: { search: query, limit: 5 } }).catch(() => ({ data: { data: [] } })),
          api.get('/teachers', { params: { search: query, limit: 5 } }).catch(() => ({ data: { data: [] } })),
        ]);
        const students = (studentsRes.data.data || []).map((s: Record<string, unknown>) => ({
          id: s.id as string, type: 'student' as const, firstName: s.firstName as string, lastName: s.lastName as string,
        }));
        const teachers = (teachersRes.data.data || []).map((item: Record<string, unknown>) => ({
          id: item.id as string, type: 'teacher' as const, firstName: item.firstName as string, lastName: item.lastName as string,
        }));
        setSearchResults([...students, ...teachers]);
        setShowSearchResults(true);
      } catch { setSearchResults([]); } finally { setSearchLoading(false); }
    }, 300);
  }, []);

  const handleMarkAllRead = async () => {
    try {
      await Promise.all(notifications.filter(n => !n.isRead).map(n => api.put(`/notifications/${n.id}/read`)));
      fetchNotifications();
    } catch { /* empty */ }
  };

  return (
    <header
      className={clsx(
        'sticky top-0 z-30 bg-white transition-shadow duration-300 mb-4 rounded-b-[15px]',
        isSticky && 'shadow-[0px_7px_29px_0px_rgba(100,100,111,0.2)]'
      )}
      style={{ boxShadow: isSticky ? undefined : 'none' }}
    >
      <div className="flex items-center justify-between h-[68px] px-5 lg:px-6">
        {/* Left side */}
        <div className="flex items-center gap-5">
          <button
            onClick={onMenuClick}
            className="lg:hidden p-2 rounded-lg hover:bg-[#F6F7F9] transition-colors duration-200"
            aria-label="Open menu"
          >
            <Menu className="w-6 h-6 text-[#64748B]" />
          </button>

          {/* Search */}
          <div ref={searchRef} className="relative hidden sm:block">
            <div className="flex items-center h-[46px] w-[282px] px-5 bg-[#F6F7F9] border border-[#F6F7F9] rounded-[7px] transition-all duration-200 focus-within:border-brand focus-within:ring-0">
              <Search className="w-[18px] h-[18px] text-brand shrink-0" />
              <input
                type="text"
                placeholder={t('header.searchPlaceholder')}
                className="bg-transparent border-none outline-none text-[14px] text-[#3A4252] placeholder:text-[#9999b3] ml-2.5 w-full"
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                onFocus={() => searchResults.length > 0 && setShowSearchResults(true)}
              />
              {searchQuery && (
                <button onClick={() => { setSearchQuery(''); setSearchResults([]); setShowSearchResults(false); }} className="p-0.5 shrink-0 hover:bg-white rounded-md transition-colors">
                  <X className="w-3.5 h-3.5 text-[#9999b3]" />
                </button>
              )}
            </div>
            {showSearchResults && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[7px] shadow-[0px_4px_45px_0px_rgba(0,0,0,0.1)] max-h-80 overflow-y-auto z-50 w-80 animate-scale-in">
                {searchLoading ? (
                  <div className="p-4 text-center text-[14px] text-[#64748B]">{t('common.loading')}</div>
                ) : searchResults.length === 0 ? (
                  <div className="p-4 text-center text-[14px] text-[#64748B]">{t('header.noResults')}</div>
                ) : (
                  <div className="py-2">
                    {searchResults.map((result) => (
                      <div key={result.id} className="px-5 py-3 hover:bg-[#ebf2fa] cursor-pointer flex items-center gap-3 transition-colors duration-200">
                        <div className="w-10 h-10 rounded-full bg-[#F6F7F9] flex items-center justify-center shrink-0">
                          <span className="text-sm font-bold text-brand">{result.firstName[0]}{result.lastName[0]}</span>
                        </div>
                        <div className="min-w-0">
                          <p className="text-[14px] font-medium text-[#3A4252] truncate">{result.firstName} {result.lastName}</p>
                          <p className="text-[12px] text-[#64748B] capitalize">{result.type}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Right side */}
        <div className="flex items-center gap-5">
          {/* Notifications */}
          <div ref={notifRef} className="relative">
            <button
              onClick={() => setShowNotifications(!showNotifications)}
              className="relative p-2 rounded-lg text-[#64748B] hover:bg-[#F6F7F9] transition-colors duration-200"
            >
              <Bell className="w-[22px] h-[22px]" />
              {unreadCount > 0 && (
                <span className="absolute top-1 right-1 w-[7px] h-[7px] bg-coral rounded-full" />
              )}
            </button>
            {showNotifications && (
              <div className="absolute right-0 top-full mt-2 w-[350px] max-w-[calc(100vw-2rem)] bg-white rounded-[7px] shadow-[0px_4px_45px_0px_rgba(0,0,0,0.1)] z-50 animate-scale-in">
                <div className="flex items-center justify-between px-5 py-3 border-b border-[#ECF0FF]">
                  <h3 className="text-[14px] font-semibold text-[#3A4252]">
                    {t('header.notifications')} ({notifications.filter(n => !n.isRead).length})
                  </h3>
                  {unreadCount > 0 && (
                    <button onClick={handleMarkAllRead} className="text-[12px] font-medium text-brand hover:text-brand-hover transition-colors duration-200">
                      {t('header.markAllRead')}
                    </button>
                  )}
                </div>
                <div className="max-h-[217px] overflow-y-auto" style={{ scrollbarWidth: 'thin' }}>
                  {notifications.length === 0 ? (
                    <div className="p-6 text-center text-[14px] text-[#64748B]">{t('header.noNotifications')}</div>
                  ) : notifications.map((notif) => (
                    <div key={notif.id} className={`px-5 py-3 border-b border-dashed border-[#eee] hover:bg-[#ebf2fa] transition-colors duration-200 ${!notif.isRead ? 'relative' : ''}`}>
                      {!notif.isRead && <span className="absolute right-5 top-1/2 -translate-y-1/2 w-[5px] h-[5px] rounded-full bg-brand" />}
                      <div className="flex items-start gap-3">
                        <div className="w-[44px] h-[44px] rounded-full bg-[#f6f5fe] flex items-center justify-center shrink-0">
                          <Bell className="w-4 h-4 text-brand" />
                        </div>
                        <div className="min-w-0 flex-1">
                          <p className="text-[14px] font-medium text-[#3A4252]">{notif.title}</p>
                          <p className="text-[13px] text-[#64748B] mt-0.5 leading-relaxed">{notif.message}</p>
                          <p className="text-[11px] text-[#9999b3] mt-1">{new Date(notif.createdAt).toLocaleString()}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                {notifications.length > 0 && (
                  <div className="px-5 py-3 border-t border-dashed border-[#eee] text-center">
                    <button className="text-[13px] font-medium text-brand hover:underline transition-all duration-200">
                      {t('header.seeAll') || 'See All'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Language */}
          <LanguageSelector />

          {/* Profile */}
          <div ref={profileRef} className="relative">
            <button
              onClick={() => setShowProfile(!showProfile)}
              className="flex items-center gap-2.5 pl-2 pr-3 py-1 rounded-lg hover:bg-[#F6F7F9] transition-colors duration-200"
            >
              <div className="w-[40px] h-[40px] rounded-full bg-gradient-to-br from-brand to-brand-hover flex items-center justify-center border-2 border-[#C2CDFF]">
                <span className="text-[13px] font-bold text-white">{user?.firstName?.[0]}{user?.lastName?.[0]}</span>
              </div>
              <div className="hidden md:block text-left">
                <p className="text-[14px] font-semibold text-[#3A4252] leading-tight">{user?.firstName} {user?.lastName}</p>
                <p className="text-[12px] text-[#64748B] leading-tight">{user?.isRoot ? 'Root Admin' : 'Admin'}</p>
              </div>
              <ChevronDown className="w-4 h-4 text-[#64748B] hidden md:block" />
            </button>
            {showProfile && (
              <div className="absolute right-0 top-full mt-2 w-[195px] bg-white rounded-[7px] shadow-[0px_4px_45px_0px_rgba(0,0,0,0.1)] p-5 z-50 animate-scale-in">
                <div className="flex items-center gap-3 pb-4 mb-4 border-b border-[#F6F7F9]">
                  <div className="w-[30px] h-[30px] rounded-full bg-gradient-to-br from-brand to-brand-hover flex items-center justify-center">
                    <span className="text-[11px] font-bold text-white">{user?.firstName?.[0]}{user?.lastName?.[0]}</span>
                  </div>
                  <div className="min-w-0">
                    <p className="text-[14px] font-medium text-[#3A4252] truncate">{user?.firstName} {user?.lastName}</p>
                    <p className="text-[11px] text-[#64748B] truncate">{user?.isRoot ? 'Root Admin' : 'Admin'}</p>
                  </div>
                </div>
                <div className="space-y-1">
                  <Link href="/settings" className="flex items-center gap-2.5 px-3 py-2 text-[14px] font-medium text-[#3A4252] hover:bg-brand/5 hover:text-brand rounded-[5px] transition-all duration-200 group"
                    onClick={() => setShowProfile(false)}>
                    <Settings className="w-4 h-4 text-[#64748B] group-hover:text-brand transition-colors" /> {t('nav.settings')}
                  </Link>
                  <Link href="/settings" className="flex items-center gap-2.5 px-3 py-2 text-[14px] font-medium text-[#3A4252] hover:bg-brand/5 hover:text-brand rounded-[5px] transition-all duration-200 group"
                    onClick={() => setShowProfile(false)}>
                    <User className="w-4 h-4 text-[#64748B] group-hover:text-brand transition-colors" /> Profile
                  </Link>
                </div>
                <div className="border-t border-[#F6F7F9] mt-3 pt-3">
                  <button
                    onClick={() => { logout(); setShowProfile(false); }}
                    className="flex items-center gap-2.5 w-full px-3 py-2 text-[14px] font-medium text-coral hover:bg-coral/5 rounded-[5px] transition-all duration-200"
                  >
                    <LogOut className="w-4 h-4" /> {t('nav.logout')}
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
