'use client';

import { useEffect, useState, useRef, useCallback } from 'react';
import Link from 'next/link';
import { GraduationCap, Users, BookOpen, CreditCard, TrendingUp, ArrowUpRight, ArrowDownRight, UserPlus, Calendar } from 'lucide-react';
import api from '@/lib/api';
import { CURRENCY } from '@/lib/constants';
import { useTranslation } from '@/components/providers/i18n-provider';
import { Spinner } from '@/components/ui/spinner';

interface Student {
  id: string;
  firstName: string;
  lastName: string;
  createdAt: string;
}

interface Stats {
  students: number;
  teachers: number;
  classes: number;
  revenue: number;
}

function AnimatedNumber({ value, prefix = '' }: { value: number; prefix?: string }) {
  const [display, setDisplay] = useState(0);
  const ref = useRef<HTMLSpanElement>(null);
  const animated = useRef(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !animated.current) {
          animated.current = true;
          const duration = 1200;
          const steps = 40;
          const increment = value / steps;
          let current = 0;
          const timer = setInterval(() => {
            current += increment;
            if (current >= value) {
              setDisplay(value);
              clearInterval(timer);
            } else {
              setDisplay(Math.floor(current));
            }
          }, duration / steps);
        }
      },
      { threshold: 0.3 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [value]);

  return <span ref={ref} className="tabular-nums">{prefix}{display.toLocaleString()}</span>;
}

export default function DashboardPage() {
  const { t } = useTranslation();
  const [stats, setStats] = useState<Stats>({ students: 0, teachers: 0, classes: 0, revenue: 0 });
  const [recentStudents, setRecentStudents] = useState<Student[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const fetchData = useCallback(async () => {
    try {
      const [studentsRes, teachersRes, classesRes, paymentsRes, recentStudentsRes] = await Promise.all([
        api.get('/students?limit=1'),
        api.get('/teachers?limit=1'),
        api.get('/classes?limit=1'),
        api.get('/student-payments?limit=200'),
        api.get('/students?limit=5&sortBy=createdAt&sortOrder=desc'),
      ]);

      const paymentsData = paymentsRes.data.data || [];
      const revenue = paymentsData
        .filter((p: { status: string; amount: number }) => p.status === 'PAID')
        .reduce((sum: number, p: { amount: number }) => sum + Number(p.amount || 0), 0);

      setStats({
        students: studentsRes.data.meta?.total || 0,
        teachers: teachersRes.data.meta?.total || 0,
        classes: classesRes.data.meta?.total || 0,
        revenue,
      });

      const students = Array.isArray(recentStudentsRes.data)
        ? recentStudentsRes.data
        : recentStudentsRes.data?.data || [];
      setRecentStudents(students);
    } catch (error) {
      console.error('Failed to fetch stats:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const statCards = [
    {
      title: t('dashboard.totalStudents'), value: stats.students, icon: GraduationCap,
      iconBg: 'bg-[#ECF0FF]', iconColor: 'text-brand',
      trend: '+12%', trendUp: true,
    },
    {
      title: t('dashboard.totalTeachers'), value: stats.teachers, icon: Users,
      iconBg: 'bg-[#FFE8D4]', iconColor: 'text-[#FD5812]',
      trend: '+5%', trendUp: true,
    },
    {
      title: t('dashboard.activeClasses'), value: stats.classes, icon: BookOpen,
      iconBg: 'bg-[#ECF0FF]', iconColor: 'text-brand',
      trend: '+8%', trendUp: true,
    },
    {
      title: t('dashboard.revenue'), value: stats.revenue, icon: CreditCard,
      iconBg: 'bg-[#D8FFC8]', iconColor: 'text-[#1E8308]',
      trend: '+15%', trendUp: true, isRevenue: true,
    },
  ];

  const formatDate = (dateStr: string) => {
    try { return new Date(dateStr).toLocaleDateString(); } catch { return dateStr; }
  };

  return (
    <div className="space-y-6">
      {/* Welcome Banner */}
      <div className="bg-gradient-to-r from-brand to-[#4a4faa] rounded-[15px] p-6 text-white relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -translate-y-1/2 translate-x-1/3" />
        <div className="absolute bottom-0 left-1/3 w-32 h-32 bg-white/5 rounded-full translate-y-1/2" />
        <div className="relative">
          <h1 className="text-2xl font-bold mb-1">
            {t('dashboard.welcomeBack') || 'Welcome Back'}, {user?.firstName || 'Admin'}!
          </h1>
          <p className="text-white/70 text-[15px]">
            {t('dashboard.welcomeSubtitle') || "Here's what's happening at your school today."}
          </p>
          <div className="flex items-center gap-6 mt-5">
            <div className="flex items-center gap-2.5">
              <div className="w-[42px] h-[42px] rounded-[7px] bg-white/10 flex items-center justify-center">
                <GraduationCap className="w-5 h-5" />
              </div>
              <div>
                <p className="text-[20px] font-bold">{isLoading ? '—' : stats.students}</p>
                <p className="text-[12px] text-white/60">{t('dashboard.totalStudents')}</p>
              </div>
            </div>
            <div className="w-px h-10 bg-white/15" />
            <div className="flex items-center gap-2.5">
              <div className="w-[42px] h-[42px] rounded-[7px] bg-[#FD5812]/20 flex items-center justify-center">
                <Users className="w-5 h-5 text-[#FD5812]" />
              </div>
              <div>
                <p className="text-[20px] font-bold">{isLoading ? '—' : stats.teachers}</p>
                <p className="text-[12px] text-white/60">{t('dashboard.totalTeachers')}</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {statCards.map((stat) => (
          <div key={stat.title} className="bg-white rounded-[15px] p-5 border-0 shadow-[0px_4px_45px_0px_rgba(0,0,0,0.05)] hover:shadow-[0px_4px_45px_0px_rgba(0,0,0,0.1)] transition-shadow duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className={`w-[46px] h-[46px] ${stat.iconBg} rounded-[7px] flex items-center justify-center`}>
                <stat.icon className={`w-5 h-5 ${stat.iconColor}`} />
              </div>
              <div className={`flex items-center gap-1 px-2.5 py-1 rounded-full text-[12px] font-medium border ${stat.trendUp ? 'bg-[#D8FFC8] border-[#82FC5A] text-[#1E8308]' : 'bg-[#FFE1DD] border-[#FFCEA9] text-[#FD5812]'}`}>
                {stat.trendUp ? <ArrowUpRight className="w-3 h-3" /> : <ArrowDownRight className="w-3 h-3" />}
                {stat.trend}
              </div>
            </div>
            <p className="text-[13px] font-medium text-[#64748B] mb-1">{stat.title}</p>
            <div className="text-[26px] font-bold text-[#3A4252] font-feature-tabular">
              {isLoading ? (
                <div className="h-8 w-24 skeleton" />
              ) : stat.isRevenue ? (
                <><AnimatedNumber value={stat.value} /> {CURRENCY}</>
              ) : (
                <AnimatedNumber value={stat.value} />
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Bottom Grid */}
      <div className="grid lg:grid-cols-3 gap-4">
        {/* Recent Students */}
        <div className="lg:col-span-2 bg-white rounded-[15px] overflow-hidden shadow-[0px_4px_45px_0px_rgba(0,0,0,0.05)]">
          <div className="px-6 py-4 border-b border-[#ECF0FF] flex items-center justify-between">
            <h3 className="text-[16px] font-semibold text-[#3A4252]">{t('dashboard.recentStudents')}</h3>
            <Link href="/students" className="text-[13px] font-medium text-brand hover:underline transition-all duration-200">
              {t('common.viewAll') || 'View All'}
            </Link>
          </div>
          <div className="p-6">
            {isLoading ? (
              <div className="flex items-center justify-center py-8"><Spinner /></div>
            ) : recentStudents.length > 0 ? (
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="bg-[#F6F7F9]">
                      <th className="text-left text-[12px] font-medium text-[#445164] px-4 py-3 rounded-tl-[8px]">{t('fields.name') || 'Name'}</th>
                      <th className="text-left text-[12px] font-medium text-[#445164] px-4 py-3">{t('fields.email') || 'Joined'}</th>
                      <th className="text-left text-[12px] font-medium text-[#445164] px-4 py-3 rounded-tr-[8px]">{t('fields.status') || 'Status'}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentStudents.map((student) => (
                      <tr key={student.id} className="border-b border-[#ECEEF2] hover:bg-[#F6F7F9]/50 transition-colors duration-200">
                        <td className="px-4 py-3.5">
                          <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-[#ECF0FF] flex items-center justify-center shrink-0">
                              <span className="text-[13px] font-bold text-brand">{student.firstName?.[0]}{student.lastName?.[0]}</span>
                            </div>
                            <span className="text-[14px] font-medium text-[#3A4252]">{student.firstName} {student.lastName}</span>
                          </div>
                        </td>
                        <td className="px-4 py-3.5 text-[14px] text-[#64748B]">{formatDate(student.createdAt)}</td>
                        <td className="px-4 py-3.5">
                          <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[12px] font-medium bg-[#D8FFC8] text-[#1E8308]">
                            <span className="w-1.5 h-1.5 rounded-full bg-[#1E8308]" />
                            {t('dashboard.enrolled')}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <p className="text-[14px] text-[#64748B] text-center py-8">{t('dashboard.noStudentsYet')}</p>
            )}
          </div>
        </div>

        {/* Quick Actions */}
        <div className="bg-white rounded-[15px] overflow-hidden shadow-[0px_4px_45px_0px_rgba(0,0,0,0.05)]">
          <div className="px-6 py-4 border-b border-[#ECF0FF]">
            <h3 className="text-[16px] font-semibold text-[#3A4252]">{t('dashboard.quickActions')}</h3>
          </div>
          <div className="p-4 space-y-1">
            {[
              { label: t('dashboard.addStudent'), href: '/students', icon: UserPlus, iconBg: 'bg-[#ECF0FF]', iconColor: 'text-brand' },
              { label: t('dashboard.markAttendance'), href: '/attendance', icon: Calendar, iconBg: 'bg-[#FFE8D4]', iconColor: 'text-[#FD5812]' },
              { label: t('dashboard.viewReports'), href: '/reports', icon: TrendingUp, iconBg: 'bg-[#ECF0FF]', iconColor: 'text-brand' },
              { label: t('dashboard.manageClasses'), href: '/classes', icon: BookOpen, iconBg: 'bg-[#D8FFC8]', iconColor: 'text-[#1E8308]' },
            ].map((action) => (
              <Link
                key={action.label}
                href={action.href}
                className="group flex items-center gap-3.5 p-3 rounded-[7px] hover:bg-[#F6F7F9] transition-all duration-200"
              >
                <div className={`w-[42px] h-[42px] ${action.iconBg} rounded-[7px] flex items-center justify-center group-hover:scale-105 transition-transform duration-200`}>
                  <action.icon className={`w-[18px] h-[18px] ${action.iconColor}`} />
                </div>
                <span className="text-[14px] font-medium text-[#3A4252] flex-1">{action.label}</span>
                <ArrowUpRight className="w-4 h-4 text-[#9999b3] group-hover:text-brand transition-colors duration-200" />
              </Link>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

