'use client';

import { useEffect, useState } from 'react';
import { Plus, Search, Edit, Trash2, Eye, Users } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Modal } from '@/components/ui/modal';
import { ConfirmDialog } from '@/components/ui/confirm-dialog';
import { Can } from '@/components/auth/can';
import { useTranslation } from '@/components/providers/i18n-provider';
import { useToast } from '@/components/ui/toast';
import { usePagination } from '@/hooks/use-pagination';
import { Pagination } from '@/components/ui/pagination';
import api from '@/lib/api';
import { LoadingCard } from '@/components/ui/spinner';

interface Parent {
  id: string;
  firstName: string;
  lastName: string;
  phone: string;
  email: string;
  isActive: boolean;
  students?: { id: string }[];
}

export default function ParentsPage() {
  const { t } = useTranslation();
  const toast = useToast();
  const [parents, setParents] = useState<Parent[]>([]);
  const [search, setSearch] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({ firstName: '', lastName: '', phone: '', email: '', password: '' });
  const [formLoading, setFormLoading] = useState(false);

  const [confirmDelete, setConfirmDelete] = useState<{ show: boolean; id: string | null }>({ show: false, id: null });
  const [deleteLoading, setDeleteLoading] = useState(false);

  const [viewParent, setViewParent] = useState<Parent | null>(null);

  useEffect(() => {
    fetchParents();
  }, []);

  const fetchParents = async () => {
    try {
      const response = await api.get('/parents');
      setParents(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch parents:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const openAddForm = () => {
    setEditingId(null);
    setFormData({ firstName: '', lastName: '', phone: '', email: '', password: '' });
    setShowForm(true);
  };

  const openEditForm = (parent: Parent) => {
    setEditingId(parent.id);
    setFormData({ firstName: parent.firstName, lastName: parent.lastName, phone: parent.phone, email: parent.email, password: '' });
    setShowForm(true);
  };

  const handleFormSubmit = async () => {
    setFormLoading(true);
    try {
      if (editingId) {
        await api.put(`/parents/${editingId}`, { firstName: formData.firstName, lastName: formData.lastName, phone: formData.phone, email: formData.email });
      } else {
        await api.post('/parents', formData);
      }
      setShowForm(false);
      fetchParents();
      toast.showToast(editingId ? t('crud.updateSuccess') : t('crud.createSuccess'), 'success');
    } catch (error) {
      console.error('Failed to save parent:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete.id) return;
    setDeleteLoading(true);
    try {
      await api.delete(`/parents/${confirmDelete.id}`);
      setConfirmDelete({ show: false, id: null });
      fetchParents();
      toast.showToast(t('crud.deleteSuccess'), 'success');
    } catch (error) {
      console.error('Failed to delete parent:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setDeleteLoading(false);
    }
  };

  const filteredParents = parents.filter(
    (p) =>
      p.firstName.toLowerCase().includes(search.toLowerCase()) ||
      p.lastName.toLowerCase().includes(search.toLowerCase()) ||
      p.email.toLowerCase().includes(search.toLowerCase()) ||
      p.phone.includes(search)
  );

  const { paginatedItems, currentPage, totalPages, goToPage, totalItems } = usePagination({ items: filteredParents });

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
