'use client';

import { useEffect, useState } from 'react';
import { Plus, Search, Edit, Trash2, Eye } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Modal } from '@/components/ui/modal';
import { ConfirmDialog } from '@/components/ui/confirm-dialog';
import { Can } from '@/components/auth/can';
import { useTranslation } from '@/components/providers/i18n-provider';
import { useToast } from '@/components/ui/toast';
import { usePagination } from '@/hooks/use-pagination';
import { Pagination } from '@/components/ui/pagination';
import api from '@/lib/api';
import { LoadingCard } from '@/components/ui/spinner';

interface Employee {
  id: string;
  firstName: string;
  lastName: string;
  position: string;
  email: string;
  phone: string;
  hireDate: string;
  isActive: boolean;
}

export default function EmployeesPage() {
  const { t } = useTranslation();
  const toast = useToast();
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [search, setSearch] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({ firstName: '', lastName: '', position: '', email: '', phone: '', hireDate: '' });
  const [formLoading, setFormLoading] = useState(false);

  const [confirmDelete, setConfirmDelete] = useState<{ show: boolean; id: string | null }>({ show: false, id: null });
  const [deleteLoading, setDeleteLoading] = useState(false);

  const [viewEmployee, setViewEmployee] = useState<Employee | null>(null);

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      const response = await api.get('/employees');
      setEmployees(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch employees:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const openAddForm = () => {
    setEditingId(null);
    setFormData({ firstName: '', lastName: '', position: '', email: '', phone: '', hireDate: '' });
    setShowForm(true);
  };

  const openEditForm = (emp: Employee) => {
    setEditingId(emp.id);
    setFormData({ firstName: emp.firstName, lastName: emp.lastName, position: emp.position, email: emp.email, phone: emp.phone, hireDate: emp.hireDate?.split('T')[0] || '' });
    setShowForm(true);
  };

  const handleFormSubmit = async () => {
    setFormLoading(true);
    try {
      if (editingId) {
        await api.put(`/employees/${editingId}`, formData);
      } else {
        await api.post('/employees', formData);
      }
      setShowForm(false);
      fetchEmployees();
      toast.showToast(editingId ? t('crud.updateSuccess') : t('crud.createSuccess'), 'success');
    } catch (error) {
      console.error('Failed to save employee:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete.id) return;
    setDeleteLoading(true);
    try {
      await api.delete(`/employees/${confirmDelete.id}`);
      setConfirmDelete({ show: false, id: null });
      fetchEmployees();
      toast.showToast(t('crud.deleteSuccess'), 'success');
    } catch (error) {
      console.error('Failed to delete employee:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setDeleteLoading(false);
    }
  };

  const filteredEmployees = employees.filter(
    (e) =>
      e.firstName.toLowerCase().includes(search.toLowerCase()) ||
      e.lastName.toLowerCase().includes(search.toLowerCase()) ||
      e.position.toLowerCase().includes(search.toLowerCase()) ||
      e.email.toLowerCase().includes(search.toLowerCase())
  );

  const { paginatedItems, currentPage, totalPages, goToPage, totalItems } = usePagination({ items: filteredEmployees });

  const formatDate = (date: string) => {
    if (!date) return '-';
    return new Date(date).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-text-primary">{t('pages.employeesTitle')}</h1>
          <p className="text-text-secondary">{t('pages.employeesDesc')}</p>
        </div>
        <Can permission="employees:create">
          <Button onClick={openAddForm}>
            <Plus className="w-4 h-4 mr-2" />
            {t('crud.addEmployee')}
          </Button>
        </Can>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4">
            <div className="flex-1 flex items-center gap-2 px-4 py-2 bg-surface rounded-lg">
              <Search className="w-4 h-4 text-text-tertiary" />
              <input
                type="text"
                placeholder={t('crud.searchEmployees')}
                className="bg-transparent border-none outline-none text-sm flex-1 text-text-primary"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <LoadingCard />
          ) : filteredEmployees.length === 0 ? (
            <div className="text-center py-8 text-text-tertiary">
              {t('crud.noEmployeesFound')}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-border">
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.name')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.position')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.emailLabel')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.phoneLabel')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.hireDate')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('common.status')}</th>
                    <th className="text-right py-3 px-4 text-sm font-medium text-text-secondary">{t('common.actions')}</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedItems.map((employee) => (
                    <tr key={employee.id} className="border-b border-border-subtle hover:bg-surface-hover">
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-indigo-100/50/30 flex items-center justify-center">
                            <span className="text-indigo-600 text-sm font-medium">
                              {employee.firstName?.[0]}{employee.lastName?.[0]}
                            </span>
                          </div>
                          <span className="font-medium text-text-primary">
                            {employee.firstName} {employee.lastName}
                          </span>
                        </div>
                      </td>
                      <td className="py-3 px-4 text-text-secondary">{employee.position}</td>
                      <td className="py-3 px-4 text-text-secondary">{employee.email}</td>
                      <td className="py-3 px-4 text-text-secondary">{employee.phone}</td>
                      <td className="py-3 px-4 text-text-secondary">{formatDate(employee.hireDate)}</td>
                      <td className="py-3 px-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                          employee.isActive ? 'bg-success-muted text-success' : 'bg-surface text-text-secondary'
                        }`}>
                          {employee.isActive ? t('common.active') : t('common.inactive')}
                        </span>
                      </td>
                      <td className="py-3 px-4">
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={() => setViewEmployee(employee)} className="p-2 hover:bg-surface-hover rounded">
                            <Eye className="w-4 h-4 text-text-tertiary" />
                          </button>
                          <Can permission="employees:update">
                            <button onClick={() => openEditForm(employee)} className="p-2 hover:bg-surface-hover rounded">
                              <Edit className="w-4 h-4 text-text-tertiary" />
                            </button>
                          </Can>
                          <Can permission="employees:delete">
                            <button
                              onClick={() => setConfirmDelete({ show: true, id: employee.id })}
                              className="p-2 hover:bg-surface-hover rounded"
                            >
                              <Trash2 className="w-4 h-4 text-destructive" />
                            </button>
                          </Can>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {totalItems > 0 && <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={goToPage} />}
        </CardContent>
      </Card>

      <Modal isOpen={showForm} onClose={() => setShowForm(false)} title={editingId ? t('crud.editEmployee') : t('crud.createEmployee')}>
        <div className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <Input label={t('auth.firstName')} value={formData.firstName} onChange={(e) => setFormData({ ...formData, firstName: e.target.value })} />
            <Input label={t('auth.lastName')} value={formData.lastName} onChange={(e) => setFormData({ ...formData, lastName: e.target.value })} />
          </div>
          <Input label={t('crud.position')} value={formData.position} onChange={(e) => setFormData({ ...formData, position: e.target.value })} />
          <Input label={t('crud.emailLabel')} type="email" value={formData.email} onChange={(e) => setFormData({ ...formData, email: e.target.value })} />
          <Input label={t('crud.phoneLabel')} value={formData.phone} onChange={(e) => setFormData({ ...formData, phone: e.target.value })} />
          <Input label={t('crud.hireDate')} type="date" value={formData.hireDate} onChange={(e) => setFormData({ ...formData, hireDate: e.target.value })} />
          <div className="flex justify-end gap-3">
            <Button variant="secondary" onClick={() => setShowForm(false)}>{t('common.cancel')}</Button>
            <Button onClick={handleFormSubmit} isLoading={formLoading}>{t('common.save')}</Button>
          </div>
        </div>
      </Modal>

      <ConfirmDialog
        isOpen={confirmDelete.show}
        onClose={() => setConfirmDelete({ show: false, id: null })}
        onConfirm={handleDelete}
        title={t('crud.confirmDelete')}
        message={t('crud.deleteEmployee')}
        isLoading={deleteLoading}
      />

      <Modal isOpen={!!viewEmployee} onClose={() => setViewEmployee(null)} title={t('pages.employeesTitle')} size="lg">
        {viewEmployee && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-text-tertiary">{t('auth.firstName')}</p>
                <p className="font-medium text-text-primary">{viewEmployee.firstName}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('auth.lastName')}</p>
                <p className="font-medium text-text-primary">{viewEmployee.lastName}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('crud.position')}</p>
                <p className="font-medium text-text-primary">{viewEmployee.position}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('crud.emailLabel')}</p>
                <p className="font-medium text-text-primary">{viewEmployee.email}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('crud.phoneLabel')}</p>
                <p className="font-medium text-text-primary">{viewEmployee.phone}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('crud.hireDate')}</p>
                <p className="font-medium text-text-primary">{formatDate(viewEmployee.hireDate)}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('common.status')}</p>
