      setRooms(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch rooms:', error);
      showToast('Failed to load data', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const openAddForm = () => {
    setEditingId(null);
    setFormData({ name: '', type: '', capacity: '' });
    setShowForm(true);
  };

  const openEditForm = (room: Room) => {
    setEditingId(room.id);
    setFormData({ name: room.name, type: room.type, capacity: String(room.capacity || '') });
    setShowForm(true);
  };

  const handleFormSubmit = async () => {
    setFormLoading(true);
    try {
      const payload = { ...formData, capacity: Number(formData.capacity) };
      if (editingId) {
        await api.put(`/rooms/${editingId}`, payload);
      } else {
        await api.post('/rooms', payload);
      }
      setShowForm(false);
      showToast(t('common.saved'), 'success');
      fetchRooms();
    } catch (error) {
      console.error('Failed to save room:', error);
      showToast('Failed to save', 'error');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete.id) return;
    setDeleteLoading(true);
    try {
      await api.delete(`/rooms/${confirmDelete.id}`);
      setConfirmDelete({ show: false, id: null });
      showToast(t('common.deleted'), 'success');
      fetchRooms();
    } catch (error) {
      console.error('Failed to delete room:', error);
      showToast('Failed to delete', 'error');
    } finally {
      setDeleteLoading(false);
    }
  };

  const filteredRooms = rooms.filter(
    (r) =>
      r.name.toLowerCase().includes(search.toLowerCase()) ||
      r.type.toLowerCase().includes(search.toLowerCase())
  );

  const { paginatedItems, currentPage, totalPages, goToPage, totalItems } = usePagination({ items: filteredRooms });

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-text-primary">{t('pages.roomsTitle')}</h1>
          <p className="text-text-secondary">{t('pages.roomsDesc')}</p>
        </div>
        <Button onClick={openAddForm}>
          <Plus className="w-4 h-4 mr-2" />
          {t('crud.addRoom')}
        </Button>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4">
            <div className="flex-1 flex items-center gap-2 px-4 py-2 bg-surface rounded-lg">
              <Search className="w-4 h-4 text-text-tertiary" />
              <input
                type="text"
                placeholder={t('crud.searchRooms')}
                className="bg-transparent border-none outline-none text-sm flex-1 text-text-primary"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <LoadingCard />
          ) : filteredRooms.length === 0 ? (
            <div className="text-center py-8 text-text-tertiary">
              {t('crud.noRoomsFound')}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-border">
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.name')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.type')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.capacity')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('common.status')}</th>
                    <th className="text-right py-3 px-4 text-sm font-medium text-text-secondary">{t('common.actions')}</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedItems.map((room) => (
                    <tr key={room.id} className="border-b border-border-subtle hover:bg-surface-hover">
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-teal-100/50 flex items-center justify-center">
                            <Home className="w-4 h-4 text-teal-600" />
                          </div>
                          <span className="font-medium text-text-primary">{room.name}</span>
                        </div>
                      </td>
                      <td className="py-3 px-4 text-text-secondary">{room.type}</td>
                      <td className="py-3 px-4 text-text-secondary">{room.capacity}</td>
                      <td className="py-3 px-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                          room.isActive ? 'bg-success-muted text-success' : 'bg-surface text-text-secondary'
                        }`}>
                          {room.isActive ? t('common.active') : t('common.inactive')}
                        </span>
                      </td>
                      <td className="py-3 px-4">
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={() => setViewRoom(room)} className="p-1 hover:bg-surface-hover rounded">
                            <Eye className="w-4 h-4 text-text-tertiary" />
                          </button>
                          <button onClick={() => openEditForm(room)} className="p-1 hover:bg-surface-hover rounded">
                            <Edit className="w-4 h-4 text-text-tertiary" />
                          </button>
                          <button
                            onClick={() => setConfirmDelete({ show: true, id: room.id })}
                            className="p-1 hover:bg-surface-hover rounded"
                          >
                            <Trash2 className="w-4 h-4 text-destructive" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {totalItems > 0 && <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={goToPage} />}
        </CardContent>
      </Card>

      <Modal isOpen={showForm} onClose={() => setShowForm(false)} title={editingId ? t('crud.editRoom') : t('crud.createRoom')}>
        <div className="space-y-4">
          <Input label={t('crud.name')} value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} />
          <Input label={t('crud.type')} value={formData.type} onChange={(e) => setFormData({ ...formData, type: e.target.value })} />
          <Input label={t('crud.capacity')} type="number" value={formData.capacity} onChange={(e) => setFormData({ ...formData, capacity: e.target.value })} />
          <div className="flex justify-end gap-3">
            <Button variant="secondary" onClick={() => setShowForm(false)}>{t('common.cancel')}</Button>
            <Button onClick={handleFormSubmit} isLoading={formLoading}>{t('common.save')}</Button>
          </div>
        </div>
      </Modal>

      <ConfirmDialog
        isOpen={confirmDelete.show}
        onClose={() => setConfirmDelete({ show: false, id: null })}
        onConfirm={handleDelete}
        title={t('crud.confirmDelete')}
        message={t('crud.deleteRoom')}
        isLoading={deleteLoading}
      />

      <Modal isOpen={!!viewRoom} onClose={() => setViewRoom(null)} title={t('pages.roomsTitle')} size="lg">
        {viewRoom && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-text-tertiary">{t('crud.name')}</p>
                <p className="font-medium text-text-primary">{viewRoom.name}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('crud.type')}</p>
                <p className="font-medium text-text-primary">{viewRoom.type}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('crud.capacity')}</p>
                <p className="font-medium text-text-primary">{viewRoom.capacity}</p>
              </div>
              <div>
                <p className="text-sm text-text-tertiary">{t('common.status')}</p>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                  viewRoom.isActive ? 'bg-success-muted text-success' : 'bg-surface text-text-secondary'
                }`}>
                  {viewRoom.isActive ? t('common.active') : t('common.inactive')}
                </span>
              </div>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

