'use client';

import { useEffect, useState } from 'react';
import { Plus, Search, Edit, Trash2, Calendar } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Modal } from '@/components/ui/modal';
import { ConfirmDialog } from '@/components/ui/confirm-dialog';
import { useTranslation } from '@/components/providers/i18n-provider';
import { useToast } from '@/components/ui/toast';
import { usePagination } from '@/hooks/use-pagination';
import { Pagination } from '@/components/ui/pagination';
import api from '@/lib/api';
import { LoadingCard } from '@/components/ui/spinner';

interface Holiday {
  id: string;
  name: string;
  startDate: string;
  endDate: string;
}

export default function HolidaysPage() {
  const { t } = useTranslation();
  const { showToast } = useToast();
  const [holidays, setHolidays] = useState<Holiday[]>([]);
  const [search, setSearch] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({ name: '', startDate: '', endDate: '' });
  const [formLoading, setFormLoading] = useState(false);

  const [confirmDelete, setConfirmDelete] = useState<{ show: boolean; id: string | null }>({ show: false, id: null });
  const [deleteLoading, setDeleteLoading] = useState(false);

  useEffect(() => {
    fetchHolidays();
  }, []);

  const fetchHolidays = async () => {
    try {
      const response = await api.get('/holidays');
      setHolidays(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch holidays:', error);
      showToast('Failed to load data', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const openAddForm = () => {
    setEditingId(null);
    setFormData({ name: '', startDate: '', endDate: '' });
    setShowForm(true);
  };

  const openEditForm = (holiday: Holiday) => {
    setEditingId(holiday.id);
    setFormData({
      name: holiday.name,
      startDate: holiday.startDate?.split('T')[0] || '',
      endDate: holiday.endDate?.split('T')[0] || '',
    });
    setShowForm(true);
  };

  const handleFormSubmit = async () => {
    setFormLoading(true);
    try {
      if (editingId) {
        await api.put(`/holidays/${editingId}`, formData);
      } else {
        await api.post('/holidays', formData);
      }
      setShowForm(false);
      showToast(t('common.saved'), 'success');
      fetchHolidays();
    } catch (error) {
      console.error('Failed to save holiday:', error);
      showToast('Failed to save', 'error');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete.id) return;
    setDeleteLoading(true);
    try {
      await api.delete(`/holidays/${confirmDelete.id}`);
      setConfirmDelete({ show: false, id: null });
      showToast(t('common.deleted'), 'success');
      fetchHolidays();
    } catch (error) {
      console.error('Failed to delete holiday:', error);
      showToast('Failed to delete', 'error');
    } finally {
      setDeleteLoading(false);
    }
  };

  const formatDate = (date: string) => {
    if (!date) return '-';
    return new Date(date).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  };

  const filteredHolidays = holidays.filter(
    (h) => h.name.toLowerCase().includes(search.toLowerCase())
  );

  const { paginatedItems, currentPage, totalPages, goToPage, totalItems } = usePagination({ items: filteredHolidays });

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-text-primary">{t('pages.holidaysTitle')}</h1>
          <p className="text-text-secondary">{t('pages.holidaysDesc')}</p>
        </div>
        <Button onClick={openAddForm}>
          <Plus className="w-4 h-4 mr-2" />
          {t('crud.addHoliday')}
        </Button>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4">
            <div className="flex-1 flex items-center gap-2 px-4 py-2 bg-surface rounded-lg">
              <Search className="w-4 h-4 text-text-tertiary" />
              <input
                type="text"
                placeholder={t('crud.searchHolidays')}
                className="bg-transparent border-none outline-none text-sm flex-1 text-text-primary"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <LoadingCard />
          ) : filteredHolidays.length === 0 ? (
            <div className="text-center py-8 text-text-tertiary">
              {t('crud.noHolidaysFound')}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-border">
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.name')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.startDate')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.endDate')}</th>
                    <th className="text-right py-3 px-4 text-sm font-medium text-text-secondary">{t('common.actions')}</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedItems.map((holiday) => (
                    <tr key={holiday.id} className="border-b border-border-subtle hover:bg-surface-hover">
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-orange-100/50 flex items-center justify-center">
                            <Calendar className="w-4 h-4 text-orange-600" />
                          </div>
                          <span className="font-medium text-text-primary">{holiday.name}</span>
                        </div>
                      </td>
                      <td className="py-3 px-4 text-text-secondary">{formatDate(holiday.startDate)}</td>
                      <td className="py-3 px-4 text-text-secondary">{formatDate(holiday.endDate)}</td>
                      <td className="py-3 px-4">
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={() => openEditForm(holiday)} className="p-1 hover:bg-surface-hover rounded">
                            <Edit className="w-4 h-4 text-text-tertiary" />
                          </button>
                          <button
                            onClick={() => setConfirmDelete({ show: true, id: holiday.id })}
                            className="p-1 hover:bg-surface-hover rounded"
                          >
                            <Trash2 className="w-4 h-4 text-destructive" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {totalItems > 0 && <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={goToPage} />}
        </CardContent>
      </Card>

      <Modal isOpen={showForm} onClose={() => setShowForm(false)} title={editingId ? t('crud.editHoliday') : t('crud.createHoliday')}>
        <div className="space-y-4">
          <Input label={t('crud.name')} value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} />
          <Input label={t('crud.startDate')} type="date" value={formData.startDate} onChange={(e) => setFormData({ ...formData, startDate: e.target.value })} />
          <Input label={t('crud.endDate')} type="date" value={formData.endDate} onChange={(e) => setFormData({ ...formData, endDate: e.target.value })} />
          <div className="flex justify-end gap-3">
            <Button variant="secondary" onClick={() => setShowForm(false)}>{t('common.cancel')}</Button>
            <Button onClick={handleFormSubmit} isLoading={formLoading}>{t('common.save')}</Button>
          </div>
        </div>
      </Modal>

      <ConfirmDialog
        isOpen={confirmDelete.show}
        onClose={() => setConfirmDelete({ show: false, id: null })}
        onConfirm={handleDelete}
        title={t('crud.confirmDelete')}
        message={t('crud.deleteHoliday')}
        isLoading={deleteLoading}
      />
    </div>
  );
}

