'use client';

import { useEffect, useState } from 'react';
import { Plus, Search, FileText, Edit, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Modal } from '@/components/ui/modal';
import { ConfirmDialog } from '@/components/ui/confirm-dialog';
import { useTranslation } from '@/components/providers/i18n-provider';
import { useToast } from '@/components/ui/toast';
import { usePagination } from '@/hooks/use-pagination';
import { Pagination } from '@/components/ui/pagination';
import api from '@/lib/api';
import { LoadingCard } from '@/components/ui/spinner';

interface Exam {
  id: string;
  title: string;
  type: string;
  status: string;
  class?: { name: string };
  matiere?: { name: string };
  maxScore: number;
  startTime?: string;
  duration?: number;
}

export default function ExamsPage() {
  const { t } = useTranslation();
  const toast = useToast();
  const [exams, setExams] = useState<Exam[]>([]);
  const [search, setSearch] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({ title: '', type: '', maxScore: '', duration: '' });
  const [formLoading, setFormLoading] = useState(false);

  const [confirmDelete, setConfirmDelete] = useState<{ show: boolean; id: string | null }>({ show: false, id: null });
  const [deleteLoading, setDeleteLoading] = useState(false);

  useEffect(() => {
    fetchExams();
  }, []);

  const fetchExams = async () => {
    try {
      const response = await api.get('/exams');
      setExams(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch exams:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const openAddForm = () => {
    setEditingId(null);
    setFormData({ title: '', type: '', maxScore: '', duration: '' });
    setShowForm(true);
  };

  const openEditForm = (exam: Exam) => {
    setEditingId(exam.id);
    setFormData({
      title: exam.title,
      type: exam.type,
      maxScore: String(exam.maxScore || ''),
      duration: String(exam.duration || ''),
    });
    setShowForm(true);
  };

  const handleFormSubmit = async () => {
    setFormLoading(true);
    try {
      const payload = { ...formData, maxScore: Number(formData.maxScore), duration: Number(formData.duration) };
      if (editingId) {
        await api.put(`/exams/${editingId}`, payload);
      } else {
        await api.post('/exams', payload);
      }
      setShowForm(false);
      fetchExams();
      toast.showToast(editingId ? t('crud.updateSuccess') : t('crud.createSuccess'), 'success');
    } catch (error) {
      console.error('Failed to save exam:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete.id) return;
    setDeleteLoading(true);
    try {
      await api.delete(`/exams/${confirmDelete.id}`);
      setConfirmDelete({ show: false, id: null });
      fetchExams();
      toast.showToast(t('crud.deleteSuccess'), 'success');
    } catch (error) {
      console.error('Failed to delete exam:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setDeleteLoading(false);
    }
  };

  const filteredExams = exams.filter(
    (e) =>
      e.title.toLowerCase().includes(search.toLowerCase()) ||
      e.class?.name.toLowerCase().includes(search.toLowerCase()) ||
      e.matiere?.name.toLowerCase().includes(search.toLowerCase())
  );

  const { paginatedItems, currentPage, totalPages, goToPage, totalItems } = usePagination({ items: filteredExams });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'DRAFT': return 'bg-surface text-text-secondary';
      case 'PUBLISHED': return 'bg-success-muted text-success';
      case 'ACTIVE': return 'bg-brand-muted text-brand';
      case 'COMPLETED': return 'bg-purple-100/50 text-purple-600';
      default: return 'bg-surface text-text-secondary';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-text-primary">{t('pages.examsTitle')}</h1>
          <p className="text-text-secondary">{t('pages.examsDesc')}</p>
        </div>
        <Button onClick={openAddForm}>
          <Plus className="w-4 h-4 mr-2" />
          {t('crud.createExam')}
        </Button>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4">
            <div className="flex-1 flex items-center gap-2 px-4 py-2 bg-surface rounded-lg">
              <Search className="w-4 h-4 text-text-tertiary" />
              <input
                type="text"
                placeholder={t('crud.searchExams')}
                className="bg-transparent border-none outline-none text-sm flex-1 text-text-primary"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <LoadingCard />
          ) : filteredExams.length === 0 ? (
            <div className="text-center py-8 text-text-tertiary">
              {t('crud.noExamsFound')}
            </div>
          ) : (
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
              {paginatedItems.map((exam) => (
                <div
                  key={exam.id}
                  className="p-4 border border-border rounded-lg transition-shadow"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-brand-muted/30 rounded-lg">
                        <FileText className="w-5 h-5 text-brand" />
                      </div>
                      <div>
                        <h3 className="font-semibold text-text-primary">{exam.title}</h3>
                        <p className="text-sm text-text-tertiary">{exam.matiere?.name || exam.type}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-1">
                      <button onClick={() => openEditForm(exam)} className="p-2 hover:bg-surface-hover rounded">
                        <Edit className="w-4 h-4 text-text-tertiary" />
                      </button>
                      <button
                        onClick={() => setConfirmDelete({ show: true, id: exam.id })}
                        className="p-2 hover:bg-surface-hover rounded"
                      >
                        <Trash2 className="w-4 h-4 text-destructive" />
                      </button>
                    </div>
                  </div>
                  <div className="mt-4 flex items-center justify-between text-sm">
                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(exam.status)}`}>
                      {exam.status}
                    </span>
                    <span className="text-text-tertiary">
                      {t('crud.maxScore')}: {exam.maxScore} | {exam.duration || '-'} {t('crud.duration')}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
          {totalItems > 0 && <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={goToPage} />}
        </CardContent>
      </Card>

      <Modal isOpen={showForm} onClose={() => setShowForm(false)} title={editingId ? t('crud.editExam') : t('crud.createExamTitle')}>
        <div className="space-y-4">
          <Input label={t('crud.name')} value={formData.title} onChange={(e) => setFormData({ ...formData, title: e.target.value })} />
          <Input label={t('crud.type')} value={formData.type} onChange={(e) => setFormData({ ...formData, type: e.target.value })} />
          <Input label={t('crud.maxScore')} type="number" value={formData.maxScore} onChange={(e) => setFormData({ ...formData, maxScore: e.target.value })} />
          <Input label={t('crud.duration')} type="number" value={formData.duration} onChange={(e) => setFormData({ ...formData, duration: e.target.value })} />
          <div className="flex justify-end gap-3">
            <Button variant="secondary" onClick={() => setShowForm(false)}>{t('common.cancel')}</Button>
            <Button onClick={handleFormSubmit} isLoading={formLoading}>{t('common.save')}</Button>
          </div>
        </div>
      </Modal>

      <ConfirmDialog
        isOpen={confirmDelete.show}
        onClose={() => setConfirmDelete({ show: false, id: null })}
        onConfirm={handleDelete}
        title={t('crud.confirmDelete')}
        message={t('crud.deleteExam')}
        isLoading={deleteLoading}
      />
    </div>
  );
}

