display.text:
'use client';

import { useEffect, useState } from 'react';
import { Plus, Search, CreditCard, CheckCircle, Clock, AlertCircle, Edit, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Select } from '@/components/ui/select';
import { Modal } from '@/components/ui/modal';
import { ConfirmDialog } from '@/components/ui/confirm-dialog';
import { useTranslation } from '@/components/providers/i18n-provider';
import { useToast } from '@/components/ui/toast';
import { usePagination } from '@/hooks/use-pagination';
import { Pagination } from '@/components/ui/pagination';
import api from '@/lib/api';
import { LoadingCard } from '@/components/ui/spinner';
import { CURRENCY } from '@/lib/constants';

interface Payment {
  id: string;
  amount: number;
  status: string;
  paymentDate?: string;
  paymentMethod?: string;
  student?: { firstName: string; lastName: string; matricule: string };
  feeType?: { name: string };
}

export default function PaymentsPage() {
  const { t } = useTranslation();
  const toast = useToast();
  const [payments, setPayments] = useState<Payment[]>([]);
  const [search, setSearch] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({ studentId: '', feeTypeId: '', amount: '', paymentMethod: 'CASH', status: 'PAID' });
  const [formLoading, setFormLoading] = useState(false);

  const [confirmDelete, setConfirmDelete] = useState<{ show: boolean; id: string | null }>({ show: false, id: null });
  const [deleteLoading, setDeleteLoading] = useState(false);

  useEffect(() => {
    fetchPayments();
  }, []);

  const fetchPayments = async () => {
    try {
      const response = await api.get('/student-payments');
      setPayments(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch payments:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const openAddForm = () => {
    setEditingId(null);
    setFormData({ studentId: '', feeTypeId: '', amount: '', paymentMethod: 'CASH', status: 'PAID' });
    setShowForm(true);
  };

  const openEditForm = (payment: Payment) => {
    setEditingId(payment.id);
    setFormData({
      studentId: '',
      feeTypeId: '',
      amount: String(payment.amount || ''),
      paymentMethod: payment.paymentMethod || 'CASH',
      status: payment.status || 'PAID',
    });
    setShowForm(true);
  };

  const handleFormSubmit = async () => {
    setFormLoading(true);
    try {
      if (editingId) {
        await api.put(`/student-payments/${editingId}`, {
          amount: Number(formData.amount),
          paymentMethod: formData.paymentMethod,
          status: formData.status,
        });
      } else {
        await api.post('/student-payments', {
          studentId: formData.studentId,
          feeTypeId: formData.feeTypeId || undefined,
          amount: Number(formData.amount),
          paymentMethod: formData.paymentMethod,
          status: formData.status,
          paymentDate: new Date().toISOString(),
        });
      }
      setShowForm(false);
      setEditingId(null);
      setFormData({ studentId: '', feeTypeId: '', amount: '', paymentMethod: 'CASH', status: 'PAID' });
      fetchPayments();
      toast.showToast(editingId ? t('crud.updateSuccess') : t('crud.createSuccess'), 'success');
    } catch (error) {
      console.error('Failed to save payment:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setFormLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete.id) return;
    setDeleteLoading(true);
    try {
      await api.delete(`/student-payments/${confirmDelete.id}`);
      setConfirmDelete({ show: false, id: null });
      fetchPayments();
      toast.showToast(t('crud.deleteSuccess'), 'success');
    } catch (error) {
      console.error('Failed to delete payment:', error);
      toast.showToast(t('common.error'), 'error');
    } finally {
      setDeleteLoading(false);
    }
  };

  const filteredPayments = payments.filter(
    (p) =>
      p.student?.firstName?.toLowerCase().includes(search.toLowerCase()) ||
      p.student?.lastName?.toLowerCase().includes(search.toLowerCase()) ||
      p.feeType?.name?.toLowerCase().includes(search.toLowerCase())
  );

  const { paginatedItems, currentPage, totalPages, goToPage, totalItems } = usePagination({ items: filteredPayments });

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'PAID': return <CheckCircle className="w-4 h-4 text-success" />;
      case 'PENDING': return <Clock className="w-4 h-4 text-warning" />;
      case 'OVERDUE': return <AlertCircle className="w-4 h-4 text-destructive" />;
      default: return <CreditCard className="w-4 h-4 text-text-tertiary" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PAID': return 'bg-success-muted text-success';
      case 'PENDING': return 'bg-warning-muted text-warning';
      case 'OVERDUE': return 'bg-destructive/10 text-destructive';
      case 'PARTIAL': return 'bg-brand-muted text-brand';
      default: return 'bg-surface text-text-secondary';
    }
  };

  const totalPaid = payments.filter((p) => p.status === 'PAID').reduce((sum, p) => sum + Number(p.amount), 0);
  const totalPending = payments.filter((p) => p.status === 'PENDING').reduce((sum, p) => sum + Number(p.amount), 0);

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-text-primary">{t('pages.paymentsTitle')}</h1>
          <p className="text-text-secondary">{t('pages.paymentsDesc')}</p>
        </div>
        <Button onClick={openAddForm}>
          <Plus className="w-4 h-4 mr-2" />
          {t('crud.recordPayment')}
        </Button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card>
          <CardContent>
            <div className="flex items-center gap-4">
              <div className="p-3 bg-success-muted/30 rounded-lg">
                <CheckCircle className="w-6 h-6 text-success" />
              </div>
              <div>
                <p className="text-sm text-text-secondary">{t('reports.paid')}</p>
                <p className="text-2xl font-bold text-text-primary">{totalPaid.toLocaleString()} {CURRENCY}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent>
            <div className="flex items-center gap-4">
              <div className="p-3 bg-warning-muted rounded-lg">
                <Clock className="w-6 h-6 text-warning" />
              </div>
              <div>
                <p className="text-sm text-text-secondary">{t('reports.pending')}</p>
                <p className="text-2xl font-bold text-text-primary">{totalPending.toLocaleString()} {CURRENCY}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent>
            <div className="flex items-center gap-4">
              <div className="p-3 bg-brand-muted/30 rounded-lg">
                <CreditCard className="w-6 h-6 text-brand" />
              </div>
              <div>
                <p className="text-sm text-text-secondary">{t('pages.paymentsTitle')}</p>
                <p className="text-2xl font-bold text-text-primary">{payments.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4">
            <div className="flex-1 flex items-center gap-2 px-4 py-2 bg-surface rounded-lg">
              <Search className="w-4 h-4 text-text-tertiary" />
              <input
                type="text"
                placeholder={t('crud.searchPayments')}
                className="bg-transparent border-none outline-none text-sm flex-1 text-text-primary"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <LoadingCard />
          ) : filteredPayments.length === 0 ? (
            <div className="text-center py-8 text-text-tertiary">
              {t('crud.noPaymentsFound')}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-border">
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.student')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.feeType')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.amount')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('common.status')}</th>
                    <th className="text-left py-3 px-4 text-sm font-medium text-text-secondary">{t('crud.date')}</th>
                    <th className="text-right py-3 px-4 text-sm font-medium text-text-secondary">{t('common.actions')}</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedItems.map((payment) => (
                    <tr key={payment.id} className="border-b border-border-subtle hover:bg-surface-hover">
                      <td className="py-3 px-4">
                        <span className="font-medium text-text-primary">
                          {payment.student?.firstName} {payment.student?.lastName}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-text-secondary">{payment.feeType?.name || '-'}</td>
                      <td className="py-3 px-4 font-medium text-text-primary">
                        {Number(payment.amount).toLocaleString()} {CURRENCY}
                      </td>
                      <td className="py-3 px-4">
                        <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(payment.status)}`}>
                          {getStatusIcon(payment.status)}
                          {payment.status}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-text-secondary">
                        {payment.paymentDate ? new Date(payment.paymentDate).toLocaleDateString() : '-'}
                      </td>
                      <td className="py-3 px-4">
                        <div className="flex items-center justify-end gap-2">
                          <button
                            onClick={() => openEditForm(payment)}
                            className="p-2 hover:bg-surface-hover rounded-lg transition-colors"
                          >
                            <Edit className="w-4 h-4 text-text-tertiary" />
                          </button>
                          <button
                            onClick={() => setConfirmDelete({ show: true, id: payment.id })}
                            className="p-2 hover:bg-surface-hover rounded-lg transition-colors"
                          >
                            <Trash2 className="w-4 h-4 text-destructive" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {totalItems > 0 && <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={goToPage} />}
        </CardContent>
      </Card>

      <Modal isOpen={showForm} onClose={() => setShowForm(false)} title={editingId ? t('crud.editPayment') || 'Edit Payment' : t('crud.recordPayment')}>
        <div className="space-y-4">
          {!editingId && (
            <Input
              label={t('crud.student') + ' ID'}
              value={formData.studentId}
              onChange={(e) => setFormData({ ...formData, studentId: e.target.value })}
            />
          )}
          <Input
            label={t('crud.amount')}
            type="number"
            value={formData.amount}
            onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
          />
          {!editingId && (
            <Input
              label={t('crud.feeType') + ' ID (optional)'}
              value={formData.feeTypeId}
              onChange={(e) => setFormData({ ...formData, feeTypeId: e.target.value })}
            />
          )}
          <Select
            label={t('crud.status')}
            value={formData.status}
            onChange={(e) => setFormData({ ...formData, status: e.target.value })}
            options={[
              { value: 'PAID', label: t('reports.paid') },
              { value: 'PENDING', label: t('reports.pending') },
            ]}
          />
          <div className="flex justify-end gap-3">
            <Button variant="secondary" onClick={() => setShowForm(false)}>{t('common.cancel')}</Button>
            <Button onClick={handleFormSubmit} isLoading={formLoading}>{t('common.save')}</Button>
          </div>
        </div>
      </Modal>

      <ConfirmDialog
        isOpen={confirmDelete.show}
        onClose={() => setConfirmDelete({ show: false, id: null })}
        onConfirm={handleDelete}
        title={t('common.delete')}
        message={t('common.confirmDelete')}
        isLoading={deleteLoading}
      />
    </div>
  );
}

